// ====== AJUSTE AQUI se o formulário da intranet usar outros valores ======
const STATUS_INTRANET = 'CONFIRMACAO DE DATA DE ENTREGA'; // campo "Status"  -> parâmetro motivo
const TIPO_INTRANET   = 'AE';                          // valor real do <option value="AE">CONTATO CLIENTE</option>
// =========================================================================

const n0  = $('Normalizar Categoria').first().json;
const cat = n0.categoria ?? '';

let dp0 = {};
try { dp0 = JSON.parse(n0.dadosPedido ?? '{}'); } catch (_) {}

// A Intranet usa <input type="date">, cujo valor enviado pelo navegador
// é YYYY-MM-DD. Normaliza aqui para evitar erro de conversão no SQL Server.
const normalizarDataIntranet = valor => {
  const s = String(valor ?? '').trim();
  if (!s) return '';

  // ISO: YYYY-MM-DD ou timestamp ISO
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:$|T)/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;

  // Brasil: DD/MM/YYYY, DD-MM-YYYY ou DD.MM.YYYY
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  if (m) {
    const dia = m[1].padStart(2, '0');
    const mes = m[2].padStart(2, '0');
    const ano = m[3];
    const d = new Date(Number(ano), Number(mes) - 1, Number(dia));
    if (d.getFullYear() !== Number(ano) || d.getMonth() !== Number(mes) - 1 || d.getDate() !== Number(dia)) return '';
    return `${ano}-${mes}-${dia}`;
  }
  return '';
};

// o texto da intranet segue o padrão do aviso de boleto: maiúsculas e sem acentos
const semAcento = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '');
const numBR = d => Number(String(d).split('/').reverse().join(''));
const DATA_FICTICIA_1A = '01/12/2040';

function montar(n, dp) {
  const pedidoLider  = String(n.pedidoLider ?? dp.pedidoLider ?? '').trim();
  const clienteLider = String(
    dp.clienteLider ?? dp.Cliente ?? dp.cliente ?? n.clienteLider ?? n.cliente ?? ''
  ).trim();

  // datas informadas ao cliente (parcial pode ter mais de uma)
  const datasInformadas = (Array.isArray(dp.entregas) ? dp.entregas.map(e => e.data).filter(Boolean) : []);
  if (!datasInformadas.length && Array.isArray(n.entregas)) {
    datasInformadas.push(...n.entregas.map(e => typeof e === 'string' ? e : e?.data).filter(Boolean));
  }
  if (!datasInformadas.length && n.dataPrevistaOriginal) datasInformadas.push(n.dataPrevistaOriginal);
  const datas = datasInformadas.join(' E ');

  let datEntrega = normalizarDataIntranet(datasInformadas[0] ?? '');
  let observacao = '';

  // 1ª confirmação de planejados: não há data na mensagem -> usa a data do sistema (fictícia 01/12/2040)
  let tipoMsg = String(n.tipoMensagem ?? dp.tipoMensagem ?? '');
  if (!tipoMsg) { try { tipoMsg = String($('Escolher Linha').first().json.tipoMensagem ?? ''); } catch (_) {} }
  const primeiraConfirmacao = tipoMsg === 'PRIMEIRA_CONFIRMACAO';

  if (primeiraConfirmacao) {
    if (cat === 'ACEITA' || cat === 'ACEITA_PEDE_ADIANTAR') {
      datEntrega = normalizarDataIntranet(dp.dataSistema || dp.entregaLider || DATA_FICTICIA_1A);
      observacao = 'CLIENTE CONTATADO VIA WHATSAPP (1A CONFIRMACAO - PLANEJADOS) E CONFIRMOU O RECEBIMENTO DA MENSAGEM. PRAZO DE ENTREGA SERA INFORMADO APOS A POSTAGEM DO PROJETO.';
    }
  } else if (cat === 'ACEITA') {
    observacao = `CLIENTE CONTATADO VIA WHATSAPP E CONFIRMOU A DATA DE ENTREGA ${datas}.`;
  } else if (cat === 'ACEITA_PEDE_ADIANTAR') {
    observacao = `CLIENTE CONTATADO VIA WHATSAPP E CONFIRMOU A DATA DE ENTREGA ${datas}, PORÉM SOLICITOU ANTECIPAR A ENTREGA. CLIENTE ORIENTADO QUE A DATA É A PREVISÃO REGISTRADA NO SISTEMA.`;
  } else if (cat === 'PEDE_ADIAR' && n.adiamentoValido === true && n.dataSolicitada) {
    datEntrega = normalizarDataIntranet(n.dataSolicitada);
    observacao = `CLIENTE CONTATADO VIA WHATSAPP E SOLICITOU ADIAMENTO DA ENTREGA DE ${n.dataPrevistaOriginal || datas} PARA ${n.dataSolicitada}. PRAZO ALTERADO NO SISTEMA.`;
  } else if (cat === 'NAO_ACEITA') {
    observacao = `CLIENTE CONTATADO VIA WHATSAPP E NÃO ACEITA A DATA DE ENTREGA ${datas}.`;
  }

  // Sem observação definida = não registra (casos que vão para atendente).
  // Também não envia data vazia/inválida ao PHP, pois isso causa erro de conversão no SQL Server.
  if (!observacao || !pedidoLider || !datEntrega) return null;

  return {
    pedidoLider,
    clienteLider: semAcento(clienteLider),
    datEntrega,
    status: STATUS_INTRANET,
    tipoInformacao: TIPO_INTRANET,
    observacao: semAcento(observacao).toUpperCase()
  };
}

// v12: 1 item por pedido gravado na planilha. Pedido de mensagem única (grupo) usa os dados do próprio pedido.
const localizados = $('Localizar Linha Sheet').all().map(i => i.json);
const saida = [];
$input.all().forEach((_, i) => {
  const cls = localizados[i] || {};
  let n = n0, dp = dp0;
  if (cls.membro) {
    const m = cls.membro;
    const datasM = (m.entregas || []).map(e => e.data).filter(Boolean).sort((a, b) => numBR(a) - numBR(b));
    n = { ...n0, pedidoLider: m.pedidoLider, tipoMensagem: m.tipoMensagem, entregas: m.entregas, dataPrevistaOriginal: datasM[0] || n0.dataPrevistaOriginal };
    dp = { ...dp0, pedidoLider: m.pedidoLider, clienteLider: m.clienteLider ?? dp0.clienteLider, entregas: m.entregas,
           tipoMensagem: m.tipoMensagem, dataSistema: m.dataSistema, entregaLider: m.entregaLider };
  }
  const obs = montar(n, dp);
  if (obs) saida.push({ json: obs, pairedItem: { item: i } });
});
return saida;

// v12: pode vir mais de um pedido (mensagem única para vários pedidos do mesmo cliente).
const alvos = $('Classificar Resposta Sheet').all().map(i => i.json);
const rows = $input.all().map(i => i.json).filter(r => r.row_number !== undefined);

// compara só o último bloco numérico, sem zeros à esquerda (11-0205548 == 11-205548)
const norm = v => { const g = String(v ?? '').match(/\d+/g); return g ? g[g.length - 1].replace(/^0+/, '') : ''; };

const saida = [], faltando = [];
for (const cls of alvos) {
  const alvo = norm(cls.pedidoSheet);
  let achadas = rows.filter(r => norm(r['Pedido']) === alvo);
  if (achadas.length > 1) {
    const exata = achadas.filter(r => String(r['Pedido']).trim() === cls.pedidoSheet);
    if (exata.length) achadas = exata;
  }
  if (!achadas.length) { faltando.push(cls.pedidoSheet); continue; }
  saida.push({ json: { ...cls, row_number: achadas[0].row_number }, pairedItem: { item: 0 } });
}
if (!saida.length) {
  throw new Error(`Pedido ${faltando.join(', ')} não encontrado na planilha para gravar a resposta do cliente.`);
}
if (faltando.length) saida.forEach(s => { s.json.pedidosForaDaPlanilha = faltando; });
return saida;

const n = $('Normalizar Categoria').first().json;
const cat = n.categoria ?? '';
const pid = String(n.pedidoLider ?? '').trim();

const ts = new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: false
}).format(new Date()).replace(',', '');

// Pedido como está na planilha (ex.: 11-205548). Se não vier no dadosPedido, usa o número do Líder.
let pedidoSheet = `11-${pid}`;
let dp = {};
try {
  dp = JSON.parse(n.dadosPedido ?? '{}');
  const original = dp.Pedido ?? dp.pedidoOriginal;
  if (original) pedidoSheet = String(original).trim();
} catch (_) {}

// Cliente confirmou a data, ou confirmou pedindo adiantamento
const CONFIRMADO   = ['ACEITA', 'ACEITA_PEDE_ADIANTAR'];
// Pedido de adiamento só conta quando o cliente informou uma data válida (já aplicada na intranet)
let alteracaoOk = true;
try { alteracaoOk = $('Confirmar Alteração Intranet').first().json.alteracaoDataConcluida !== false; } catch (_) {}
const ADIAMENTO_OK = cat === 'PEDE_ADIAR' && n.adiamentoValido === true && !!n.dataSolicitada && alteracaoOk;
// Cliente foi contatado, mas recusou a data
const NAO_CONCORDA = ['NAO_ACEITA'];

let deveAtualizar = false, sheetG = '', sheetH = '', sheetI = '';

if (CONFIRMADO.includes(cat) || ADIAMENTO_OK) {
  deveAtualizar = true; sheetG = 'SIM'; sheetH = 'CONFIRMADO'; sheetI = ts;
} else if (NAO_CONCORDA.includes(cat)) {
  deveAtualizar = true; sheetG = 'SIM'; sheetH = 'CLIENTE NÃO CONCORDA'; sheetI = ts;
}
// Qualquer outra categoria (OUTRO, ACEITA_CONTATO_RESPONSAVEL, RECUSA_CONTATO_RESPONSAVEL...)
// precisa de atendente: não preenche nada.

// v26 — REGISTRO ÚNICO: planilha e observação da intranet são preenchidas UMA vez por pedido.
// Depois do 1º registro (IA ou consultor), nenhuma resposta do cliente grava de novo.
const registroAnterior = dp.registroContato || null;
let jaRegistrado = false;
if (deveAtualizar && registroAnterior) {
  jaRegistrado = true; deveAtualizar = false; sheetG = ''; sheetH = ''; sheetI = '';
  console.log(`[registro único] pedido ${pid} já registrado em ${registroAnterior.em} (${registroAnterior.resultado || registroAnterior.categoria}); nada gravado de novo`);
}

// v12 — mensagem única para vários pedidos do mesmo cliente: a resposta vale para TODOS.
// Sai 1 item por pedido do grupo (planilha e observação da intranet em cada um).
const membros = Array.isArray(dp.pedidosGrupo) && dp.pedidosGrupo.length > 1 ? dp.pedidosGrupo : null;
if (membros) {
  return membros.map(m => ({ json: {
    deveAtualizar, sheetG, sheetH, sheetI, jaRegistrado,
    pedidoSheet: String(m.Pedido ?? `11-${m.pedidoLider}`).trim(),
    pedidoLider: String(m.pedidoLider ?? '').trim(),
    categoria: cat,
    membro: m,
    pedidoPrincipal: pid
  }, pairedItem: { item: 0 } }));
}

return [{ json: { deveAtualizar, jaRegistrado, sheetG, sheetH, sheetI, pedidoSheet, pedidoLider: pid, categoria: cat } }];

const j = $input.first().json;
const t = String(j.textoCliente || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const nao = /\b(nao|nem|n)\b|pode deixar|deixa (pra la|quieto|assim)|dispens|sem necessidade|tudo certo assim|esta bom assim|ta bom assim/.test(t);
const sim = /\b(sim|quero|pode( sim| encaminhar| passar)?|por favor|encaminh|claro|ok|beleza|isso|aceito|gostaria|prefiro|manda|com certeza)\b/.test(t);
// "nao" manda, exceto quando o cliente diz "sim" explicitamente sem negar ("sim, nao tenho problema")
let decisao = 'AMBIGUA';
if (nao && !/^(sim|pode sim)\b/.test(t)) decisao = 'NAO';
else if (sim) decisao = 'SIM';
return [{ json: { ...j, decisaoResponsavel: decisao } }];

