// v12: junta o resultado de todos os pedidos alterados (mensagem única pode ter vários).
// Só conta como concluído se TODOS os pedidos foram alterados.
const p = $('Normalizar Categoria').first().json;
const entradas = $input.all();
const pegar = (no, i) => {
  try { return $(no).itemMatching(i).json || {}; }
  catch (_) { try { return ($(no).all()[i] || {}).json || {}; } catch (e) { return {}; } }
};
const resultados = entradas.map((it, i) => {
  const montar = pegar('Montar URL Adiamento', i);
  const alvo = pegar('Expandir adiamento (grupo)', i);
  const j = it.json || {};
  const ok = !!montar.urlAlterar && !j.error;
  return {
    pedidoLider: String(montar.pedidoLider ?? alvo.pedidoLider ?? p.pedidoLider),
    ok,
    resposta: String(j.data ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 400),
    erro: ok ? null : (montar.erroAdiamento || String(j.error?.message || j.error || 'falha ao alterar na intranet'))
  };
});
const tudoOk = resultados.length > 0 && resultados.every(r => r.ok);
const varios = resultados.length > 1;
const erros = resultados.filter(r => !r.ok).map(r => varios ? `pedido ${r.pedidoLider}: ${r.erro}` : r.erro);
return { json: {
  ...p,
  resultadoIntranet: varios ? resultados.map(r => `${r.pedidoLider}: ${r.resposta}`).join(' | ').slice(0, 800) : (resultados[0]?.resposta ?? ''),
  alteracaoDataConcluida: tudoOk,
  erroAdiamento: tudoOk ? null : (erros.join(' | ') || 'falha ao alterar na intranet'),
  resultadosAdiamento: resultados
} };

// v12: roda 1 vez por pedido (mensagem única pode ter vários pedidos).
const p = $('Expandir adiamento (grupo)').item.json;
const html = String($json.data ?? '');
const itens=[];
for (const tag of (html.match(/<input\b[^>]*>/gi)||[])) {
  if (!/name\s*=\s*["']?item\[\]["']?/i.test(tag)) continue;
  const v=tag.match(/value\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
  if(v) itens.push((v[1]??v[2]??v[3]??'').replace(/&amp;/g,'&'));
}
const unique=[...new Set(itens)];
if(!unique.length){const txt=html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(); return {json:{urlAlterar:null,qtdItens:0,dataISO:null,pedidoLider:p.pedidoLider,erroAdiamento:`Não encontrei os itens do formulário para o pedido ${p.pedidoLider}. Resposta: ${txt.slice(0,250)}`}};}
const iso=p.dataSolicitada.split('/').reverse().join('-');
const observacao=`ADIAMENTO SOLICITADO PELO CLIENTE: data alterada de ${p.dataPrevistaOriginal} para ${p.dataSolicitada}. Resposta: ${p.textoCliente}`;
const params=[['data',iso],['cod_empresa','11'],['pedido',p.pedidoLider],['motivo','SOLICITACAO DO CLIENTE'],['agendamento',''],['observacao',observacao],['opcao[]','A'],...unique.map(i=>['item[]',i])];
const qs=params.map(([k,v])=>`${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
return {json:{urlAlterar:`http://192.168.0.6/vdp/altera_data_entrega2.php?${qs}`,qtdItens:unique.length,dataISO:iso,pedidoLider:p.pedidoLider}};

// v15 — Volta para a linha do pedido e anota o resultado do envio do vídeo.
return $input.all().map((item, i) => {
  const linha = $('Escolher Linha').itemMatching(i).json;
  const r = item.json || {};
  let status, detalhe = '';
  if (r.videoPronto === false) { status = 'NAO_ENVIADO'; detalhe = r.videoErro || ''; }
  else if (r.error) { status = 'FALHOU'; detalhe = String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 300); }
  else if (r.id) { status = 'ENVIADO'; detalhe = String(r.id); }
  else { status = 'FALHOU'; detalhe = 'Resposta sem id: ' + JSON.stringify(r).slice(0, 200); }
  return { json: { ...linha, videoEnvio: { status, detalhe, em: $now.toISO() } }, pairedItem: { item: i } };
});

// v15 — A API da Digisac (POST /api/v1/messages) recebe arquivo em JSON:
// file: { base64, mimetype, name }. Antes ia como multipart e a Digisac recusava (erro escondido).
const LIMITE_WHATSAPP = 16 * 1024 * 1024;   // vídeo no WhatsApp: até 16 MB
const itens = $input.all();
const saida = [];
for (let i = 0; i < itens.length; i++) {
  const item = itens[i];
  const linha = $('Escolher Linha').itemMatching(i).json;
  const base = { contactId: linha.contactId, pedidoLider: linha.pedidoLider };
  const bin = item.binary && item.binary.data;
  if (!bin) {
    const erro = item.json && item.json.error ? String(item.json.error.message || item.json.error) : '';
    saida.push({ json: { ...base, videoPronto: false, videoErro: 'ARQUIVO_NAO_LIDO' + (erro ? ': ' + erro : '') }, pairedItem: { item: i } });
    continue;
  }
  let buf;
  try {
    buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  } catch (e) {
    buf = bin.data && !String(bin.id || '').includes(':') ? Buffer.from(bin.data, 'base64') : null;
  }
  if (!buf || !buf.length) {
    saida.push({ json: { ...base, videoPronto: false, videoErro: 'ARQUIVO_VAZIO' }, pairedItem: { item: i } });
    continue;
  }
  if (buf.length > LIMITE_WHATSAPP) {
    saida.push({ json: { ...base, videoPronto: false, videoErro: 'ARQUIVO_MAIOR_QUE_16MB (' + (buf.length / 1048576).toFixed(1) + ' MB)' }, pairedItem: { item: i } });
    continue;
  }
  saida.push({
    json: {
      ...base,
      videoPronto: true,
      videoBytes: buf.length,
      file: { base64: buf.toString('base64'), mimetype: bin.mimeType || 'video/mp4', name: bin.fileName || 'LIDER.mp4' }
    },
    pairedItem: { item: i }
  });
}
return saida;

const pedido = $('Decidir Revisão').first().json;

const norm = s => String(s ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^A-Z0-9 ]/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .toUpperCase();
const ignorar = new Set(['DE', 'DA', 'DO', 'DAS', 'DOS', 'E', 'DR', 'DRA']);

const MAPA_FIXO = {};

const responsavel = norm(pedido['RESPONSÁVEL'] ?? pedido.responsavel ?? '');
if (MAPA_FIXO[responsavel]) {
  return [{ json: { ...pedido, userIdResponsavel: MAPA_FIXO[responsavel], nomeUsuarioResponsavel: responsavel, statusResponsavel: 'OK_MAPA_FIXO', totalUsuariosConsultados: null } }];
}

const tokens = responsavel.split(' ').filter(t => t && !ignorar.has(t));
const todos = [];
function coletar(valor) {
  if (!valor) return;
  if (Array.isArray(valor)) { for (const x of valor) coletar(x); return; }
  if (typeof valor !== 'object') return;
  const id = valor.id ?? valor.userId ?? valor.user_id;
  const name = valor.name ?? valor.nome ?? valor.fullName ?? valor.full_name;
  if (id && name) todos.push({ id: String(id), name: String(name), raw: valor });
  for (const k of ['data','users','items','results','records','content','rows','payload']) {
    if (valor[k] && typeof valor[k] === 'object') coletar(valor[k]);
  }
}
for (const item of $input.all()) coletar(item.json);
const vistos = new Set();
const usuarios = todos.filter(u => {
  const key = u.id;
  if (vistos.has(key)) return false;
  vistos.add(key); return true;
});

const pontuar = u => {
  const nome = norm(u.name);
  const partes = nome.split(' ').filter(Boolean);
  const nomeSemCargo = nome.split(/\s+-\s+/)[0].trim();
  const partesBase = nomeSemCargo.split(' ').filter(Boolean);
  if (!tokens.length) return -1;
  let score = 0;
  for (const t of tokens) {
    if (partesBase.includes(t)) score += 10;
    else if (partesBase.some(p => p.startsWith(t) && t.length >= 4)) score += 7;
    else if (t.length >= 4 && partes.some(p => p === t || p.startsWith(t))) score += 3;
    else return -1;
  }
  if (nomeSemCargo === responsavel) score += 20;
  if (partesBase.length && partesBase[0] === tokens[0]) score += 2;
  return score;
};
const classificados = usuarios.map(u => ({...u, score: pontuar(u)})).filter(u => u.score >= 0).sort((a,b) => b.score-a.score);
const melhorScore = classificados[0]?.score ?? -1;
const melhores = classificados.filter(u => u.score === melhorScore);
let userIdResponsavel = '';
let statusResponsavel = 'NAO_ENCONTRADO';
let nomeUsuarioResponsavel = '';
if (melhores.length === 1) {
  userIdResponsavel = melhores[0].id;
  nomeUsuarioResponsavel = melhores[0].name;
  statusResponsavel = 'OK';
} else if (melhores.length > 1) {
  statusResponsavel = 'AMBIGUO: ' + melhores.map(u => u.name).join(' / ');
}
return [{ json: {
  ...pedido,
  userIdResponsavel,
  nomeUsuarioResponsavel,
  statusResponsavel,
  totalUsuariosConsultados: usuarios.length,
    candidatosResponsavel: classificados.slice(0, 10).map(u => ({ id: u.id, name: u.name, score: u.score }))} }];

const OK = [
  'EM_PROCESSAMENTO','PENDENTE_DESTINO','RESOLVIDO','INDIVIDUAL','PENDENTE_REVISAO','BLOQUEADO','CANCELADO',
  'AGUARDANDO','DATA_ENVIADA','AGUARDANDO_DECISAO_RESPONSAVEL','AGUARDANDO_CONSULTOR',
  'CONCLUIDO','ESCALADO','TRANSFERIDO','TRANSFERENCIA_MANUAL','AGUARDANDO_CHAMADO_LIVRE',
  'PENDENTE_RESPOSTA_TARDIA','SEM_RETORNO_CLIENTE','AGRUPADO','OUTLET'
];

const saida = $input.all()
  .filter(i => i.json.pedidoLider && i.json.status)
  .map(i => ({ json: { ...i.json, criadoEm: i.json.criadoEm ?? i.json.createdAt, statusConhecido: OK.includes(i.json.status) } }));

return saida.length ? saida : [{ json: {} }];

const body = $('Central - Lider - Decisão de Envio').first().json.body ?? {};
const linha = $input.first().json;

let dados;
try { dados = JSON.parse(linha.dadosPedido); }
catch (e) { throw new Error(`dadosPedido inválido no pedido ${linha.pedidoLider}`); }

const enviar = body.decisao === 'enviar';

// v8 — RESPOSTA TARDIA: decisão vinda da tela "Respostas tardias" do front.
//   enviar sem texto  -> FLUXO_NORMAL: template + mensagem padrão (como qualquer pedido)
//   enviar com texto  -> RESPOSTA_DIFERENTE: template primeiro; depois do aceite vai o texto do consultor
//   cancelar          -> NAO_ENVIAR: nada é enviado (consultor trata por fora)
const origemTardia = body.origem === 'RESPOSTA_TARDIA';
if (origemTardia && String(linha.status ?? '') !== 'PENDENTE_RESPOSTA_TARDIA') return [];   // já decidido / linha errada

if (origemTardia) {
  const textoConsultor = String(body.mensagemPersonalizada ?? '').trim();
  const modo = !enviar ? 'NAO_ENVIAR' : (textoConsultor ? 'RESPOSTA_DIFERENTE' : 'FLUXO_NORMAL');
  if (modo === 'RESPOSTA_DIFERENTE') {
    dados.mensagemPadrao = dados.mensagem;
    dados.mensagem = textoConsultor;
    dados.anexoUrlPadrao = dados.anexoUrl ?? null;
    dados.anexoUrl = '';   // resposta personalizada vai só em texto, sem o vídeo
  }
  dados.respostaTardiaDecisao = {
    modo,
    texto: modo === 'RESPOSTA_DIFERENTE' ? textoConsultor : '',
    decididoEm: new Date().toISOString()
  };
}

// v9 — MENSAGEM EDITADA na Revisão de envio: o texto editado substitui a mensagem padrão
// (vai ao cliente depois que ele aceitar o template). Respostas tardias usam o próprio campo acima.
const editada = String(body.mensagemEditada ?? '').replace(/\r\n/g, '\n').trim();
if (!origemTardia && enviar && editada && editada !== String(dados.mensagem ?? '').trim()) {
  dados.mensagemOriginal = dados.mensagemOriginal ?? dados.mensagem;
  dados.mensagem = editada;
  dados.mensagemEditada = { editadaEm: new Date().toISOString() };
}

return [{ json: {
  ...dados,
  pedidoLider: String(linha.pedidoLider),
  enviar,
  origemTardia,
  dadosPedidoFinal: JSON.stringify(dados)
} }];

// Todas as UFs do Brasil são aceitas. UFs com depósito usam o depósito; MG e UFs sem depósito usam a Referência de Origem informada.
const ufsValidas = ['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
const depositos = {
  'SP': { cidade: 'BARUERI', uf: 'SP', nome: 'DEPÓSITO BARUERI' },
  'RJ': { cidade: 'RIO DE JANEIRO', uf: 'RJ', nome: 'DEPÓSITO RIO DE JANEIRO' },
  'ES': { cidade: 'CARIACICA', uf: 'ES', nome: 'DEPÓSITO CARIACICA' },
  'BA': { cidade: 'LAURO DE FREITAS', uf: 'BA', nome: 'DEPÓSITO LAURO DE FREITAS' },
  'DF': { cidade: 'BRASILIA', uf: 'DF', nome: 'DEPÓSITO BRASILIA' }
};
const norm = t => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim().toUpperCase();

function normalizarCelular(raw) {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length >= 12) d = d.slice(2);
  d = d.replace(/^0+/, '');
  if (d.length === 10 && /^[1-9][1-9][6-9]/.test(d)) d = d.slice(0, 2) + '9' + d.slice(2);
  return /^[1-9][1-9]9\d{8}$/.test(d) ? '55' + d : null;
}

const body = $('Central - Lider - Resolver Pendência').first().json.body ?? {};
const linha = $('Buscar Pendência').first().json;

let pedido;
try { pedido = JSON.parse(linha.dadosPedido); }
catch (e) { pedido = {}; }

// Garante o ID exato da linha da tabela e o pedidoLider clicado
const pedidoLider = String(linha.pedidoLider || body.pedidoLider || pedido.pedidoLider || pedido.pedido || '').trim();
const idLinha = linha.id;

if (body.acao === 'individual') {
  return [{
    json: {
      ...pedido,
      id: idLinha,
      pedidoLider,
      tratarIndividual: true,
      motivoIndividual: String(body.observacao ?? '').trim() || null,
      rota: { ...(pedido.rota || {}), origemIdentificada: false, status: 'PENDENTE', motivoOrigem: 'TRATAR_INDIVIDUALMENTE' }
    }
  }];
}

const telManual = String(body.telefone ?? '').trim();
let telefoneAtualizado = pedido.telefone;
let telefonesAtualizados = Array.isArray(pedido.telefones) ? [...pedido.telefones] : [];

if (telManual) {
  const normTel = normalizarCelular(telManual) || telManual.replace(/\D/g, '');
  telefoneAtualizado = normTel;
  if (!telefonesAtualizados.includes(normTel)) {
    telefonesAtualizados.unshift(normTel);
  }
}

const telFinalNormalizado = normalizarCelular(telefoneAtualizado);
const cidade = norm(body.cidade) || norm(pedido.cidadeEntrega);
const uf = norm(body.uf) || norm(pedido.ufEntrega);
const refManual = norm(body.referencia);

if (!cidade || !ufsValidas.includes(uf)) {
  throw new Error(`Destino inválido para o pedido ${pedidoLider}`);
}

let origem;
let motivoOrigem;

// Converte a referência (loja/cidade) em origem MG
function origemPorReferencia(ref) {
  if (/SILVIANO|S\.BRANDAO|PONTEIO|CATALAO|SION/.test(ref)) {
    return { cidade: 'BELO HORIZONTE', uf: 'MG', nome: 'BELO HORIZONTE' };
  }
  const m = ref.match(/\(([^)]+)\)/);
  const c = (m ? m[1].trim() : ref).replace(/^M\.LEME$/, 'MATEUS LEME');
  if (/CORP|SAO PAULO|CENTRAL/.test(c)) {
    throw new Error(`Pedido ${pedidoLider}: a referência "${ref}" não é uma cidade de origem em MG`);
  }
  return { cidade: c, uf: 'MG', nome: c };
}

if (uf !== 'MG' && depositos[uf]) {
  origem = depositos[uf];
  motivoOrigem = 'DESTINO_MANUAL_DEPOSITO_REGIONAL';
} else if (uf === 'MG') {
  const ref = refManual || norm(pedido.referencia);
  if (!ref) throw new Error(`Pedido ${pedidoLider}: informe a referência de origem (MG)`);
  origem = origemPorReferencia(ref);
  motivoOrigem = 'DESTINO_MANUAL_REFERENCIA_MG';
} else {
  // UF sem depósito regional (ex.: GO): exige referência digitada manualmente
  if (!refManual) throw new Error(`Pedido ${pedidoLider}: UF ${uf} sem depósito regional — informe a referência de origem`);
  origem = origemPorReferencia(refManual);
  motivoOrigem = 'DESTINO_MANUAL_UF_SEM_DEPOSITO';
}

return [{
  json: {
    ...pedido,
    id: idLinha,
    pedidoLider,
    tratarIndividual: false,
    telefone: telFinalNormalizado || telefoneAtualizado,
    phone: telFinalNormalizado,   // null se não for celular válido (fixo)
    telefones: telefonesAtualizados,
    cidadeEntrega: cidade,
    ufEntrega: uf,
    referencia: refManual || pedido.referencia || null,
    rota: {
      ...(pedido.rota || {}),
      origem,
      origemIdentificada: true,
      telefoneIdentificado: !!telFinalNormalizado,
      semPendencia: !!telFinalNormalizado,
      apto: true,
      origemManual: true,
      status: telFinalNormalizado ? 'OK' : 'PENDENTE',
      motivoOrigem,
      motivoPendencia: telFinalNormalizado ? null : 'TELEFONE_FIXO_OU_INVALIDO',
      destino: { cidade, uf }
    }
  }
}];

const VIDEO_URL = '/files/LIDER.mp4';
const REGEX_PLANEJADO = /PLANEJAD/i;
const ANO_ABSURDO = 2040;
const PLACEHOLDERS = ['01/01/2027'];

// ---------------------------------------------------------------------------
// REGRA DE PLANEJADOS (1ª x 2ª confirmação)
// 1ª confirmação: data fictícia (ano >= 2040, ex.: 01/12/2040) e/ou algum item com
//   código de ambiente (lista RESTRITA abaixo) SEM projeto postado.
// 2ª confirmação: todos os itens de ambiente com projeto postado -> data + produtos.
//
// Projetos postados: http://192.168.0.6/liderprojeto/listar_arq_pojetos.php
// Nome do arquivo: <empresa>-<pedido>-<códigoItem>-<seq>-<timestamp>.<ext>
//   ex.: 11-118128-1AMBANO705018C-1-20260121164211.zip
//        11-182231-1WY13SA393986.-1-20260309155914.zip  (às vezes vem um "." no fim do código)
// Só conta como projeto arquivo compactado (.zip / .rar / .7z). PDF/JPG/PNG não contam.
// ---------------------------------------------------------------------------
const PREFIXOS_PROJETO = [
  '1AMBAN', '1AMCOZ', '1AMDES', '1AMGOU', '1AMSER', '1COORP',
  '1ESPAU', '1MOSPL', '1PROIN', '1QUCAS', '1QUCLO', '1QUHOS',
  '1QUOFF', '1QUROU', '1QUSOL', '1SLEST', '1SLJAN', '1SLTEL'
];
const EXTENSOES_PROJETO = ['ZIP', 'RAR', '7Z'];

const entradas = $('Consultar Itens Planejado').all();
const produtos = $('Separ produtos').all(1); // saída 1 = Planejados

// ---- Lista de projetos postados (consultada 1 vez por execução) ----
let htmlProjetos = '';
try {
  const r = $('Consultar Projetos Postados').first()?.json ?? {};
  htmlProjetos = typeof r.data === 'string' ? r.data : '';
} catch (e) {
  htmlProjetos = '';
}

const normCodigo = c => String(c ?? '').trim().toUpperCase().replace(/\.+$/, '');
const decodificar = s => { try { return decodeURIComponent(s); } catch (e) { return s; } };

const arquivosProjeto = new Set();
for (const m of htmlProjetos.matchAll(/arquivo=([^"'&<>\s]+)/gi)) {
  arquivosProjeto.add(decodificar(m[1]).trim().toUpperCase());
}

// índice: "empresa|pedido|codigoItem" -> [arquivos compactados]
const indiceProjetos = new Map();
for (const arq of arquivosProjeto) {
  const m = arq.match(/^(\d+)-(\d+)-(.+?)-(\d+)-(\d{14})\.([A-Z0-9]+)$/);
  if (!m) continue;
  if (!EXTENSOES_PROJETO.includes(m[6])) continue;
  const k = `${Number(m[1])}|${Number(m[2])}|${normCodigo(m[3])}`;
  if (!indiceProjetos.has(k)) indiceProjetos.set(k, []);
  indiceProjetos.get(k).push(arq);
}
const listaProjetosValida = /arquivo=/i.test(htmlProjetos) && arquivosProjeto.size > 2;

const exigeProjeto = codigo => {
  const c = normCodigo(codigo);
  return PREFIXOS_PROJETO.some(pref => c.startsWith(pref));
};

const limpar = t => String(t ?? '').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
const semTags = t => limpar(String(t ?? '').replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' '));
const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
const parseData = d => { const [dd, mm, aa] = d.split('/').map(Number); return new Date(aa, mm - 1, dd); };
const num = d => Number(d.split('/').reverse().join(''));
const dataValida = d => !!d && !PLACEHOLDERS.includes(d) && parseData(d) >= hoje;
const absurda = d => Number(String(d).split('/')[2]) >= ANO_ABSURDO;

function primeiroNome(nome) {
  const n = String(nome ?? '').trim();
  if (!n || /\b(LTDA|S\/A|SA|ME|EIRELI|SISTEMAS|COMERCIO|INDUSTRIA)\b/i.test(n)) return null;
  const x = n.split(/\s+/)[0];
  return x.charAt(0).toUpperCase() + x.slice(1).toLowerCase();
}

const linhaItem = it => {
  const nome = String(it.descricao ?? '').split(' - ')[0].replace(/\s+/g, ' ').trim();
  const q = Number(String(it.quantidade ?? '').replace(/\./g, '').replace(',', '.'));
  return `• ${q > 1 ? q + 'x ' : ''}${nome}`;
};

// Formato 1: situacao_pedidos.php ("Saldo de pedidos entre os dias")
function itensSaldo(html, pedido) {
  const identificador = `(11)-${pedido}`;
  const mapa = new Map();
  for (const linha of (html.match(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi) || [])) {
    if (!semTags(linha).includes(identificador)) continue;
    const celulas = (linha.match(/<td\b[^>]*>[\s\S]*?<\/td>/gi) || []).map(semTags);
    if (celulas.length < 7) continue;
    const [pedidoHtml, , situacao, dataEntrega, , codigoItem, descricao, quantidade] = celulas;
    if (!pedidoHtml.includes(identificador) || !/^\d{2}\/\d{2}\/\d{4}$/.test(dataEntrega) || !codigoItem) continue;
    const k = `${codigoItem}|${dataEntrega}`;
    if (!mapa.has(k)) mapa.set(k, { codigoItem, descricao, quantidade, dataEntrega, situacao });
  }
  return [...mapa.values()];
}

// Formato 2: Ordem de Expedição (lojas.php) – código / qtd / descrição em tabelas
function itensOrdem(html, pedido) {
  const texto = semTags(html);
  const pm = texto.match(/PEDIDO:\s*(\d+)/i);
  if (!pm || Number(pm[1]) !== Number(pedido)) return [];
  const mapa = new Map();
  const re = /ENTREGA:\s*(?:<[^>]+>|\s)*(\d{2}\/\d{2}\/\d{4})|<td[^>]*width="150"[^>]*>([\s\S]*?)<\/td>\s*<td[^>]*width="50"[^>]*>([\s\S]*?)<\/td>\s*<td[^>]*>([\s\S]*?)<\/td>/gi;
  let dataAtual = null;
  for (const m of html.matchAll(re)) {
    if (m[1]) { dataAtual = m[1]; continue; }
    const codigoItem = semTags(m[2]);
    if (!/^[0-9A-Z][0-9A-Z.\-]{4,}$/i.test(codigoItem) || !dataAtual) continue;
    const k = `${codigoItem}|${dataAtual}`;
    if (!mapa.has(k)) mapa.set(k, { codigoItem, descricao: semTags(m[4]), quantidade: semTags(m[3]), dataEntrega: dataAtual, situacao: null });
  }
  return [...mapa.values()];
}

return entradas.map((entrada, index) => {
  const p = produtos[index]?.json;

  if (!p) {
    throw new Error(
      `Não foi encontrado o produto correspondente ao item ${index + 1} em Separ produtos.`
    );
  }

  const html = String(entrada.json.data ?? '');
  const pedido = String(p.pedidoLider).trim();

  let itensLink = [];
  let paginaValida = false;
  if (/Saldo de pedidos entre os dias/i.test(html)) {
    paginaValida = true;
    itensLink = itensSaldo(html, pedido);
  } else if (/Ordem de Expedi/i.test(html)) {
    paginaValida = true;
    itensLink = itensOrdem(html, pedido);
  }

  // Itens que entram na mensagem: descrição/código com PLANEJAD ou código de ambiente
  const itensPlanejados = itensLink.filter(it =>
    REGEX_PLANEJADO.test(`${it.codigoItem} ${it.descricao}`) || exigeProjeto(it.codigoItem)
  );

  // ---- Conferência de projeto postado (cada item de ambiente precisa do seu .zip/.rar) ----
  const codigosExigemProjeto = [...new Set(
    itensLink.filter(it => exigeProjeto(it.codigoItem)).map(it => normCodigo(it.codigoItem))
  )];
  const projetosPorItem = codigosExigemProjeto.map(codigo => {
    const arquivos = indiceProjetos.get(`11|${Number(pedido)}|${codigo}`) || [];
    return { codigoItem: codigo, postado: arquivos.length > 0, arquivos };
  });
  const itensSemProjeto = projetosPorItem.filter(x => !x.postado).map(x => x.codigoItem);

  const motivos = [];
  if (!p.phone) motivos.push('TELEFONE_INVALIDO');
  if (!p.contactId) motivos.push('SEM_CONTATO_DIGISAC');
  if (!paginaValida) motivos.push('PAGINA_SITUACAO_INVALIDA');
  if (paginaValida && itensLink.length === 0) motivos.push('ITENS_NAO_LOCALIZADOS');

  const temDataAbsurda =
    itensPlanejados.some(it => absurda(it.dataEntrega)) ||
    [...(p.datasEntrega || []), p.entregaLider].filter(Boolean).some(absurda);
  const faltaProjeto = itensSemProjeto.length > 0;

  // Sem data fictícia e com itens de ambiente: se a lista de projetos não carregou,
  // não dá para saber se é 1ª ou 2ª -> bloqueia para revisão (não envia nada errado).
  if (!temDataAbsurda && codigosExigemProjeto.length > 0 && !listaProjetosValida) {
    motivos.push('LISTA_PROJETOS_INDISPONIVEL');
  }

  const primeiraConfirmacao =
    itensPlanejados.length === 0 ||
    temDataAbsurda ||
    faltaProjeto;

  const criterios = [];
  if (itensPlanejados.length === 0) criterios.push('SEM_ITENS_PLANEJADOS');
  if (temDataAbsurda) criterios.push('DATA_FICTICIA');
  if (faltaProjeto) criterios.push(`PROJETO_NAO_POSTADO (${itensSemProjeto.join(', ')})`);

  const nome = primeiroNome(p.clienteLider);
  const saudacao = nome ? `Olá, ${nome}!` : 'Olá!';

  let entregas = [];
  let mensagem = null;

  if (primeiraConfirmacao) {
    if (!motivos.length) {
      mensagem = [
        saudacao,
        '',
        `O seu pedido nº *${p.pedidoLider}* está em nossas mãos e já está sendo cuidadosamente desenvolvido. Nesse momento, nossos designers estão finalizando os detalhes do seu projeto personalizado para garantir que seus móveis planejados sejam perfeitos para o seu ambiente.`,
        '',
        'Para que possamos encaminhar os projetos finais para a fábrica, precisaremos das medidas definitivas do local de instalação. Isso garantirá que a fabricação e a montagem sejam realizadas com precisão. Após a aprovação final do projeto e a liberação para a fábrica, o prazo de entrega será definido de acordo com o calendário vigente de postagens.',
        '',
        'Dessa forma, o prazo poderá variar conforme a data em que o pedido for efetivamente postado para produção, seguindo a tabela de prazos da fábrica. Assim que o pedido for postado, entraremos em contato novamente para informar a previsão de entrega de acordo com o prazo correspondente à data de postagem.',
        '',
        'Nossa equipe também fará contato com antecedência para agendar a medição do ambiente.',
        '',
        'Pedimos, por gentileza, que confirme o recebimento da mensagem anterior. Ficamos no aguardo da sua confirmação.'
      ].join('\n');
    }
  } else {
    const mapaDatas = Object.fromEntries((p.datasCalculadas ?? []).map(x => [x.original, x.calculada]));
    const grupos = {};

    for (const it of itensPlanejados) {
      const nova = mapaDatas[it.dataEntrega];
      if (!nova) { motivos.push('DATA_ITEM_SEM_CALCULO'); continue; }
      if (!dataValida(nova)) continue;
      (grupos[nova] ??= []).push(it);
    }

    entregas = Object.entries(grupos)
      .map(([data, itens]) => ({ data, itens }))
      .sort((a, b) => num(a.data) - num(b.data));

    if (!entregas.length) motivos.push('TODAS_ENTREGAS_VENCIDAS');

    if (!motivos.length) {
      const abertura = `${saudacao} Aqui é da *Líder*.`;
      const rodape = 'Lembrando que se trata de uma data *prevista*. Se houver qualquer impedimento para receber, é só nos avisar por aqui.\n\nPodemos confirmar a data de entrega?';

      mensagem = entregas.length === 1
        ? [
            abertura, '',
            `A previsão de entrega dos seus móveis planejados do pedido *${p.pedidoLider}* é *${entregas[0].data}*.`, '',
            '*Produtos do pedido:*',
            entregas[0].itens.map(linhaItem).join('\n'), '',
            rodape
          ].join('\n')
        : [
            abertura, '',
            `Seu pedido *${p.pedidoLider}* será entregue em mais de uma data:`, '',
            entregas.map(e => `\u{1F4C5} *${e.data}*\n${e.itens.map(linhaItem).join('\n')}`).join('\n\n'), '',
            rodape
          ].join('\n');
    }
  }

  return {
    json: {
      pedidoLider: p.pedidoLider,
      Pedido: p.Pedido ?? p.pedidoOriginal ?? null,
      clienteLider: p.clienteLider,
      RESPONSÁVEL: p['RESPONSÁVEL'],
      referencia: p.referencia,
      tipoMovel: p.tipoMovel,
      phone: p.phone ?? null,
      telefones: p.telefones ?? [],
      cpf: p.cpf ?? null,
      contactId: p.contactId ?? null,
      serviceId: p.serviceId ?? null,
      statusBusca: p.statusBusca ?? null,
      tipoMensagem: primeiraConfirmacao ? 'PRIMEIRA_CONFIRMACAO' : 'SEGUNDA_CONFIRMACAO',
      // data atual do sistema (na 1ª confirmação normalmente a fictícia 01/12/2040) -> usada no aviso_entrega da intranet
      entregaLider: p.entregaLider ?? null,
      datasEntrega: p.datasEntrega ?? [],
      dataSistema: [...(p.datasEntrega || []), p.entregaLider].filter(Boolean).find(absurda) || p.entregaLider || null,
      criteriosPrimeiraConfirmacao: criterios.join(', '),
      anexoUrl: primeiraConfirmacao ? VIDEO_URL : null,
      entregas,
      mensagem,
      qtdItensLink: itensLink.length,
      qtdItensPlanejados: itensPlanejados.length,
      projetosPorItem,
      itensSemProjeto,
      bloqueado: motivos.length > 0,
      motivosBloqueio: [...new Set(motivos)].join(', ')
    }
  };
});

