      } else {
        dataSolicitada = util;
        adiamentoValido = true; tipoResposta = 'ADIAR_VALIDO';
      }
    }
  } else if (mesSolicitado && dataPrevista) {
    const nomeMes = MESES[mesSolicitado.mes - 1] || 'esse mês';
    const ini = new Date(mesSolicitado.ano, mesSolicitado.mes - 1, 1);
    const fim = new Date(mesSolicitado.ano, mesSolicitado.mes, 0);
    if (fim <= dataPrevista) {
      categoria = 'NAO_ACEITA'; respostaFixa = respostas.NAO_ACEITA.txt; statusFinal = 'CONCLUIDO'; tipoResposta = 'MES_ANTES_DA_PREVISTA';
    } else if (ini > ultimoPossivel) {
