      statusFinal = 'AGUARDANDO_DECISAO_RESPONSAVEL'; tipoResposta = 'MES_ALEM_LIMITE';
    } else {
      const de = ini < primeiroPossivel ? primeiroPossivel : proximoUtil(ini);
      const ate = fim > ultimoPossivel ? ultimoPossivel : anteriorUtil(fim);
      if (membrosGrupo && de > ate) {
        respostaFixa = `Entendo! Em ${nomeMes} não tenho um dia disponível para reagendar todos os seus pedidos por aqui. ${OFERTA_RESPONSAVEL}`;
        statusFinal = 'AGUARDANDO_DECISAO_RESPONSAVEL'; tipoResposta = 'MES_SEM_DIA_GRUPO';
      } else {
      const DIA = 86400000;
