}

// v20 — documento da intranet: CPF e CNPJ vêm com 15 dígitos (antes o CPF se perdia ou virava "CNPJ")
function cpfValido(c) {
  if (!/^\d{11}$/.test(c) || /^(\d)\1{10}$/.test(c)) return false;
  const dv = n => { let s = 0; for (let i = 0; i < n; i++) s += Number(c[i]) * (n + 1 - i); const r = (s * 10) % 11; return r === 10 ? 0 : r; };
  return dv(9) === Number(c[9]) && dv(10) === Number(c[10]);
}
function cnpjValido(c) {
  if (!/^\d{14}$/.test(c) || /^(\d)\1{13}$/.test(c)) return false;
  const dv = n => { const p = n === 12 ? [5,4,3,2,9,8,7,6,5,4,3,2] : [6,5,4,3,2,9,8,7,6,5,4,3,2]; let s = 0; for (let i = 0; i < n; i++) s += Number(c[i]) * p[i]; const r = s % 11; return r < 2 ? 0 : 11 - r; };
  return dv(12) === Number(c[12]) && dv(13) === Number(c[13]);
}
// A intranet grava o documento com 15 dígitos:
//   CNPJ = 0 + 14 dígitos               ex.: 046069303000161 -> 46069303000161
//   CPF  = 9 dígitos + 0000 + 2 dígitos ex.: 114679806000076 -> 11467980676
function normalizarCpf(raw) {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (d.length === 15) {
    const cpf = d.slice(0, 9) + d.slice(13);
    const cnpj = d.startsWith('0') ? d.slice(1) : null;
    if (d.slice(9, 13) === '0000' && cpfValido(cpf)) return cpf;
    if (cnpj && cnpjValido(cnpj)) return cnpj;
    if (cpfValido(cpf)) return cpf;
    return cnpj;
  }
  if (d.length === 10) return d.padStart(11, '0');
  if (d.length === 11 || d.length === 14) return d;
  return null;
}

