const PLACEHOLDERS = ['01/01/2027'];
const REGEX_DATA = /^\d{2}\/\d{2}\/\d{4}$/;

const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
const parseData = d => { const [dd, mm, aa] = d.split('/').map(Number); return new Date(aa, mm - 1, dd); };
const num = d => Number(d.split('/').reverse().join(''));
const dataValida = d => !!d && !PLACEHOLDERS.includes(d) && parseData(d) >= hoje;
const limpar = t => String(t ?? '').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();

function primeiroNome(nome) {
  const n = String(nome ?? '').trim();
  if (!n || /\b(LTDA|S\/A|SA|ME|EIRELI|SISTEMAS|COMERCIO|INDUSTRIA)\b/i.test(n)) return null;
  const p = n.split(/\s+/)[0];
  return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
}

// "2", "2,00", "1.000,00" -> número
function parseQtd(q) {
  const s = String(q ?? '').trim();
  const n = s.includes(',') ? Number(s.replace(/\./g, '').replace(',', '.')) : Number(s);
  return Number.isFinite(n) ? n : 1;
}

const linhaItem = it => {
  const nome = String(it.descricao ?? '').split(' - ')[0].replace(/\s+/g, ' ').trim();
  const q = parseQtd(it.quantidade);
  return `• ${q > 1 ? q + 'x ' : ''}${nome}`;
};

function extrairItens(html, pedidoLider) {
  const identificador = `(11)-${String(pedidoLider).trim()}`;
  const mapa = new Map();
  for (const linha of (html.match(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi) || [])) {
    if (!limpar(linha.replace(/<[^>]+>/g, ' ')).includes(identificador)) continue;
    const celulas = (linha.match(/<td\b[^>]*>[\s\S]*?<\/td>/gi) || [])
      .map(c => limpar(c.replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ')));
    if (celulas.length < 7) continue;
    const [pedidoHtml, , situacao, dataEntrega, , codigoItem, descricao, quantidade] = celulas;
    if (!pedidoHtml.includes(identificador) || !REGEX_DATA.test(dataEntrega) || !codigoItem) continue;
    const k = `${codigoItem}|${dataEntrega}`;
    if (!mapa.has(k)) mapa.set(k, { codigoItem, descricao, quantidade, dataEntrega, situacao });
  }
  return [...mapa.values()];
}

