      .trim();
  }

  let pedidoOriginal = pedidosOriginais[index];
  if (!pedidoOriginal) {
    pedidoOriginal = pedidosOriginais.find(p =>
      html.includes(`(11)-${String(p.json.pedidoLider || '').trim()}`)
    );
