  const pedido = { ...pedidoOriginal.json };
  delete pedido.data;
  delete pedido.dadosPedidoOriginal;

  const numeroPedido = String(pedido.pedidoLider).trim();
  const identificador = `(11)-${numeroPedido}`;

  const linhas = html.match(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi) || [];
  const produtos = [];

