function parseData(data) {
  const [dia, mes, ano] = data.split('/').map(Number);
  return new Date(ano, mes - 1, dia);
}

function formatarData(data) {
  const dia = String(data.getDate()).padStart(2, '0');
  const mes = String(data.getMonth() + 1).padStart(2, '0');
  const ano = data.getFullYear();

  return `${dia}/${mes}/${ano}`;
}

function pascoa(ano) {
  const a = ano % 19;
  const b = Math.floor(ano / 100);
  const c = ano % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);

  const mes = Math.floor((h + l - 7 * m + 114) / 31);
  const dia = ((h + l - 7 * m + 114) % 31) + 1;

  return new Date(ano, mes - 1, dia);
}

function feriadosNacionais(ano) {
  const feriados = [
    new Date(ano, 0, 1),
    new Date(ano, 3, 21),
    new Date(ano, 4, 1),
    new Date(ano, 8, 7),
    new Date(ano, 9, 12),
    new Date(ano, 10, 2),
    new Date(ano, 10, 15),
    new Date(ano, 10, 20),
    new Date(ano, 11, 25)
  ];

  const domingoPascoa = pascoa(ano);
  const sextaSanta = new Date(domingoPascoa);
  sextaSanta.setDate(sextaSanta.getDate() - 2);
  feriados.push(sextaSanta);

  return feriados;
}

function ehFeriado(data) {
  const feriados = feriadosNacionais(data.getFullYear());
  return feriados.some(feriado =>
    feriado.getFullYear() === data.getFullYear() &&
    feriado.getMonth() === data.getMonth() &&
    feriado.getDate() === data.getDate()
  );
}

function ehDiaUtil(data) {
  const diaSemana = data.getDay();
  if (diaSemana === 0 || diaSemana === 6) return false;
  return !ehFeriado(data);
}

function adicionarDiasUteis(data, quantidade) {
  let diasAdicionados = 0;
  while (diasAdicionados < quantidade) {
    data.setDate(data.getDate() + 1);
    if (ehDiaUtil(data)) {
      diasAdicionados++;
    }
  }
  return data;
}

