  // TELEFONES
  const telefones = [
    ...new Set(
      [...texto.matchAll(/\b\d{10,11}\b/g)]
        .map(m => m[0])
        .filter(t => t !== cpfLider)
    )
  ];

  const telefone = telefones[0] || null;
  const telefone2 = telefones[1] || null;

  // REFERÊNCIA
  const referenciaMatch = texto.match(
    /([A-ZÀ-Ú][A-ZÀ-Ú\s.']+?)\s*\(\s*([A-ZÀ-Ú][A-ZÀ-Ú0-9\s.\-']*?)\s*\)(?=\s*NATUREZA)/
  );

  const referencia = referenciaMatch
    ? `${limpar(referenciaMatch[1])} (${limpar(referenciaMatch[2])})`
    : null;

  // ENDEREÇO
  let enderecoEntrega = null;
  let bairroEntrega = null;
  let cidadeEntrega = null;
  let ufEntrega = null;
  let cepEntrega = null;

  const entregaHtmlMatch = html.match(
    /<b>\s*ENTREGA\s*<\/b>\s*:\s*([\s\S]*?)<br\s*\/?>/i
  );

  if (entregaHtmlMatch) {
    const enderecoTexto = limparHtml(entregaHtmlMatch[1]);
    const partes = enderecoTexto.match(
      /^(.+?)\s*-\s*([^,]+?)\s*,\s*(.+?)\s*-\s*([A-Z]{2})\s*\.?\s*$/i
    );

    if (partes) {
      enderecoEntrega = limpar(partes[1]);
      bairroEntrega = limpar(partes[2]);
      cidadeEntrega = limpar(partes[3]);
      ufEntrega = limpar(partes[4]);
    } else {
      enderecoEntrega = enderecoTexto;
    }
  } else {
    const linhas = [
      ...html.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)
    ].map(m => m[1]);

    const linhasTd = linhas.map(linha => {
      return [
        ...linha.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)
      ].map(m => limparHtml(m[1]));
    });

    const indiceCliente = linhasTd.findIndex(celulas =>
      clienteLider &&
      celulas.some(celula =>
        celula.toUpperCase().includes(clienteLider.toUpperCase())
      )
    );

    if (indiceCliente >= 0) {
      const linhaEndereco = linhasTd[indiceCliente + 1] || [];
      const linhaLocalizacao = linhasTd[indiceCliente + 2] || [];

      enderecoEntrega = linhaEndereco[0] || null;
      bairroEntrega = linhaEndereco[1] || null;

      cepEntrega = linhaLocalizacao[0] || null;
      cidadeEntrega = linhaLocalizacao[1] || null;
      ufEntrega = linhaLocalizacao[2] || null;

      const cepMatch = linhaLocalizacao.join(' ').match(/\b\d{5}-?\d{3}\b/);
      if (cepMatch) {
        cepEntrega = cepMatch[0];
      }

      const ufsValidas = ['MG','RJ','SP','ES','BA','DF'];
      const ufEncontrada = [...linhaLocalizacao.join(' ').matchAll(/\b([A-Z]{2})\b/g)]
        .map(m => m[1])
        .find(uf => ufsValidas.includes(uf));

      if (ufEncontrada) {
        ufEntrega = ufEncontrada;
      }
    }
  }

  return {
    json: {
      pedidoLider,
      pedidoCancelado: ehCancelado,
      motivoCancelamento,
      statusCancelamento,
      dataPedidoLider,
      entregaLider,
      situacaoLider,
      clienteLider,
      cpf: cpfLider,
      datasEntrega,

      telefone,
      telefone2,
      telefones,

      referencia,

      enderecoEntrega,
      bairroEntrega,
      cidadeEntrega,
      ufEntrega,
      cepEntrega,

      observacaoEntrega,
      diasAdicionaisLider,

      "RESPONSÁVEL": responsavel,
      "Pedido": pedidoPlanilha,
      "Cliente": clientePlanilha,
      motivoPlanilha,
      confirmadoPlanilha
    }
  };
});

const itens = $input.all();

return itens.map(item => {
