// Encerramento por falta de retorno (seg-qui 16:20 / sex 15:20)
// Regra: colunas G/H/I da planilha vazias + status AGUARDANDO (não aceitou o template)
//        ou DATA_ENVIADA (não respondeu a mensagem de confirmação).
// v24: também roda na varredura da manhã (só as linhas que ela mandar; ver abaixo).
// v23: também encerra quem ficou o dia todo em AGUARDANDO_CHAMADO_LIVRE (⏳ chamado ocupado), igual ao sem retorno:
//      planilha NÃO / SEM RETORNO CLIENTE, status SEM_RETORNO_CLIENTE, anota no SEM_CONFIRMACAO_DIARIO (conta para os 2 dias).
//      O chamado só é fechado se, na reconferência feita na hora, estiver na fila sem atendente (ou já comigo);
//      com outro atendente, o chamado fica como está.
const sheetRows = $('Ler planilha de confirmações').all().map(i => i.json);
const tableRowsBrutos = $input.all().map(i => i.json).filter(t => t && t.pedidoLider !== undefined);

const norm = v => String(v ?? '').trim().normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
const pedidoNorm = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };
const lerDp = t => { try { return JSON.parse(t.dadosPedido || '{}') || {}; } catch (_) { return {}; } };

// v12: pedido AGRUPADO (foi junto na mensagem única de outro pedido do mesmo cliente)
// segue o status e o contato do pedido principal; a planilha e o SEM_CONFIRMACAO_DIARIO são gravados nele também.
const tableRowsTodos = tableRowsBrutos.map(t => {
  if (norm(t.status) !== 'AGRUPADO') return t;
  const dp = lerDp(t);
  const p = tableRowsBrutos.find(x => pedidoNorm(x.pedidoLider) === pedidoNorm(dp.agrupadoEm) && norm(x.status) !== 'AGRUPADO');
  return p ? { ...t, status: p.status, contactId: p.contactId, responsavel: t.responsavel || p.responsavel, cliente: t.cliente || p.cliente, agrupadoEm: String(p.pedidoLider), _idPrincipal: String(p.id) } : t;
});

// v24 — VARREDURA DA MANHÃ: o encerramento das 16:20 não rodou (computador desligado).
// Quando quem chama é a "Varredura de respostas tardias", só entram as linhas de dias anteriores que ela mandou
// (cliente não respondeu nada); o dia anotado no SEM_CONFIRMACAO_DIARIO é o dia do pedido, não hoje.
let varredura = null;
try {
  const v = $('Analisar respostas (varredura tardia)');
  if (v.isExecuted) {
    const enc = v.all().map(i => i.json).find(j => j && j.acao === 'ENCERRAR');
    if (enc) varredura = { ids: new Set((enc.ids || []).map(String)), dia: Object.fromEntries((enc.linhas || []).map(l => [String(l.id), l.dataRef])) };
  }
} catch (_) { varredura = null; }
const tableRows = varredura
  ? tableRowsTodos.filter(t => varredura.ids.has(String(t.id)) || (t._idPrincipal && varredura.ids.has(t._idPrincipal)))
  : tableRowsTodos;

// Está na mão de um responsável: nunca encerrar
const COM_RESPONSAVEL = ['TRANSFERIDO', 'TRANSFERENCIA_MANUAL', 'ESCALADO'];
// Conversa em andamento com consultor/responsável: não fechar o chamado desse contato no Digisac
const PROTEGER_CHAMADO = [...COM_RESPONSAVEL, 'AGUARDANDO_CONSULTOR', 'AGUARDANDO_DECISAO_RESPONSAVEL'];
// Só encerra quem está esperando o CLIENTE:
//   AGUARDANDO   = template enviado e o cliente não aceitou (não clicou no botão)
//   DATA_ENVIADA = aceitou o template, recebeu a mensagem de confirmação e não respondeu
//   AGUARDANDO_CHAMADO_LIVRE = (v22) o template nunca saiu porque o chamado ficou ocupado o dia todo
// Qualquer outro status (consultor, responsável, cancelado, boleto, não enviado...) fica de fora.
const ETAPA_SEM_RETORNO = {
  AGUARDANDO: 'SEM_RETORNO_TEMPLATE',
  DATA_ENVIADA: 'SEM_RETORNO_CONFIRMACAO',
  AGUARDANDO_CHAMADO_LIVRE: 'SEM_RETORNO_CHAMADO_OCUPADO'
};
const OCUPADO = 'AGUARDANDO_CHAMADO_LIVRE';
const agoraTxt = $now.setZone('America/Sao_Paulo').toFormat('dd/LL/yyyy HH:mm');

// Contatos que têm algum pedido com consultor/responsável: não fechar o chamado deles no Digisac
const contatosComResponsavel = new Set(
  tableRowsTodos.filter(t => PROTEGER_CHAMADO.includes(norm(t.status)) && String(t.contactId ?? '').trim())
           .map(t => String(t.contactId).trim())
);
const chamadosAFechar = new Set(); // 1 fechamento por contato, mesmo com vários pedidos

const saida = [];
for (const row of sheetRows) {
  const pedido = row['Pedido'] ?? row['PEDIDO'] ?? row['pedidoLider'];
  if (!pedido || row.row_number === undefined) continue;

  // G, H e I vazias = sem nenhum retorno registrado
  if ([row['CONFIRMADO'], row['MOTIVO'], row['DATA ENVIO CONF.']].some(v => String(v ?? '').trim() !== '')) continue;

  const key = pedidoNorm(pedido);
  const matches = tableRows.filter(t => pedidoNorm(t.pedidoLider) === key);
  if (!matches.length) continue; // sem registro no n8n: não dá para confirmar o envio

  // Se qualquer registro do pedido está com responsável, preservar
  if (matches.some(t => COM_RESPONSAVEL.includes(norm(t.status)))) continue;

  // AGUARDANDO / DATA_ENVIADA precisam do contactId (prova de que o template foi enviado).
  // Chamado ocupado não precisa: o template não saiu; o contato vem do dadosPedido.
  const t = matches.find(m => ETAPA_SEM_RETORNO[norm(m.status)] && norm(m.status) !== OCUPADO && String(m.contactId ?? '').trim())
         || matches.find(m => norm(m.status) === OCUPADO);
  if (!t) continue;

  const ocupado = norm(t.status) === OCUPADO;
  const contactId = String(t.contactId ?? '').trim() || String(lerDp(t).contactId ?? '').trim();
  // Ocupado: candidato a fechar; a decisão final é da reconferência ao vivo ("Reconferir fila (encerramento)").
  const fecharChamado = !!contactId && !contatosComResponsavel.has(contactId) && !chamadosAFechar.has(contactId);
  if (fecharChamado) chamadosAFechar.add(contactId);

  let resumoEncerramento;
  if (ocupado) {
    const ce = lerDp(t).chamadoEspera || {};
    const quem = ce.chamadoAtendente ? ` com ${ce.chamadoAtendente}` : (ce.chamadoSituacao === 'FILA_SEM_ATENDENTE' ? ' na fila sem atendente' : '');
    resumoEncerramento = `Sem retorno do cliente: chamado ocupado o dia todo${quem}, template não enviado; encerrado automaticamente em ${agoraTxt}`;
  } else {
    resumoEncerramento = `Sem retorno do cliente; chamado encerrado automaticamente em ${agoraTxt}`;
  }
  // v24: encerrado na varredura da manhã (o encerramento da tarde não rodou)
  if (varredura) resumoEncerramento += ' (varredura da manhã: o encerramento da tarde não rodou)';

  saida.push({ json: {
    row_number: Number(row.row_number),
    pedido: String(pedido),
    pedidoLider: String(t.pedidoLider ?? '').trim(),
    responsavel: String(t.responsavel ?? '').trim(),
    contactId,
    dataTableId: t.id,
    statusAnterior: t.status,
    etapaSemRetorno: ETAPA_SEM_RETORNO[norm(t.status)],
    cliente: row['Cliente'] ?? row['CLIENTE'] ?? t.cliente ?? '',
    fecharChamado,
    // v23
    chamadoOcupado: ocupado,
    resumoEncerramento,
    // v24: dia anotado no SEM_CONFIRMACAO_DIARIO (varredura = dia do pedido; normal = hoje)
    dataRef: varredura ? (varredura.dia[String(t.id)] || varredura.dia[String(t._idPrincipal)] || null) : null
  }});
}
return saida;

// Reenvio do template (seg-sex 12:30): só para quem AINDA NÃO respondeu o 1º envio.
const MIN_MINUTOS = 60;  // não reenvia se o 1º template foi enviado há menos de 1h
const MAX_HORAS = 72;    // ignora linhas antigas/esquecidas (72h cobre o fim de semana)

const agora = Date.now();
const porContato = new Map();

for (const { json: r } of $input.all()) {
  // Status diferente de AGUARDANDO = cliente já respondeu, foi transferido ou encerrado
  if (String(r.status ?? '').trim().toUpperCase() !== 'AGUARDANDO') continue;
  // Já reenviado antes (marca gravada na coluna template): não reenviar de novo
  if (String(r.template ?? '').toLowerCase().includes('reenvio')) continue;

  const contactId = String(r.contactId ?? '').trim();
  const phone = String(r.phone ?? '').trim();
  const serviceId = String(r.serviceId ?? '').trim();
  if (!contactId || !phone || !serviceId) continue;

  const enviadoMs = new Date(r.enviadoEm).getTime();
  if (isNaN(enviadoMs)) continue;
  const idadeMin = (agora - enviadoMs) / 60000;
  if (idadeMin < MIN_MINUTOS || idadeMin > MAX_HORAS * 60) continue;

  // Um único template por contato, mesmo que ele tenha vários pedidos aguardando
  if (!porContato.has(contactId)) {
    porContato.set(contactId, { contactId, phone, serviceId, pedidos: [] });
  }
  porContato.get(contactId).pedidos.push(String(r.pedidoLider ?? ''));
}

return [...porContato.values()].map(x => ({ json: x }));

// Registra um evento de progresso para a tela "Disparar Fluxo"
const MAPA = {"Status: Coletando dados da planilha": ["Coletando dados da planilha", 8], "Status: Acessando a intranet": ["Acessando a intranet", 18], "Status: Consultando pedidos na intranet": ["Consultando pedidos na intranet", 28], "Status: Verificando entregas realizadas": ["Verificando entregas realizadas", 40], "Status: Verificando boletos": ["Verificando boletos", 52], "Status: Verificando pedidos de outlet": ["Verificando pedidos de outlet", 58], "Status: Calculando rota e prazo": ["Calculando rota e prazo de entrega", 64], "Status: Registrando pendências": ["Registrando pendências para preenchimento manual", 0], "Status: Pesquisando contatos": ["Pesquisando contatos no Digisac", 78], "Status: Montando e enviando mensagens": ["Montando e enviando mensagens", 88], "Status: Registrando envios": ["Registrando envios", 96]};
