const texto = String(body.texto || '').trim();
const RESULTADOS = { CONFIRMADO: 'Cliente confirmou a data de entrega', NAO_CONCORDA: 'Cliente não concorda com a data de entrega', ADIADO: 'Cliente adiou a entrega' };
let resultado = String(body.resultado || '').toUpperCase().trim();
if (acao === 'TRANSFERIR') resultado = '';

// data do adiamento: aceita AAAA-MM-DD (input date) ou DD/MM/AAAA
const parseData = s => {
  s = String(s || '').trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/); if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/); if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  return null;
};
const fmt = d => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
const dataAdiamento = resultado === 'ADIADO' ? parseData(body.dataAdiamento) : null;
const hoje = new Date(); hoje.setHours(0, 0, 0, 0);

let chat = [];
try { chat = JSON.parse(row.chatConsultor || '[]'); if (!Array.isArray(chat)) chat = []; } catch (_) { chat = []; }
const jaRegistrado = chat.some(m => m && m.tipo === 'resultado');

let dpRow = {};
try { dpRow = JSON.parse(row.dadosPedido || '{}'); } catch (_) {}
const primeiraConfirmacao = String(row.tipoMensagem || dpRow.tipoMensagem || '') === 'PRIMEIRA_CONFIRMACAO';

let erro = '';
if (!row.id) erro = 'Consulta não encontrada.';
else if (!['RESPONDER', 'REGISTRAR', 'TRANSFERIR'].includes(acao)) erro = 'Ação inválida.';
else if (acao !== 'REGISTRAR' && row.status !== 'AGUARDANDO_CONSULTOR') erro = 'Esta consulta já foi tratada.';
// v24: "✅ Registrar confirmado" da tela Respostas tardias também passa por aqui (status PENDENTE_RESPOSTA_TARDIA)
else if (acao === 'REGISTRAR' && !['AGUARDANDO_CONSULTOR', 'CONCLUIDO', 'PENDENTE_RESPOSTA_TARDIA'].includes(row.status)) erro = `Não é possível registrar resultado com o pedido em ${row.status}.`;
else if (acao === 'RESPONDER' && !texto) erro = 'Escreva a orientação para o cliente.';
else if (acao === 'REGISTRAR' && !resultado) erro = 'Escolha o resultado do contato.';
else if (resultado && !RESULTADOS[resultado]) erro = 'Resultado inválido.';
// v28: resultado já registrado antes pelo consultor não bloqueia mais (fecha a nova consulta; intranet é pulada)
// v27 — se o contato já foi registrado na intranet (registroContato da v26), o consultor ainda registra o resultado
// (planilha + fechar o card), mas a observação de contato NÃO é gravada de novo na intranet.
else if (resultado === 'ADIADO' && primeiraConfirmacao) erro = '1ª confirmação de planejados não tem data de entrega para adiar. Registre como Confirmado ou transfira.';
else if (resultado === 'ADIADO' && !dataAdiamento) erro = 'Informe a nova data de entrega.';
else if (resultado === 'ADIADO' && dataAdiamento <= hoje) erro = 'A nova data precisa ser futura.';

const ts = new Date().toISOString();
// v27: contato já registrado na intranet -> pula só a observação da intranet
const pularIntranet = !!(resultado && (dpRow.registroContato || jaRegistrado));   // v28: inclui resultado já registrado pelo consultor
if (!erro) {
  if (acao === 'RESPONDER') chat.push({ role: 'consultor', texto, ts });
  if (acao === 'TRANSFERIR') chat.push({ role: 'consultor', texto: texto ? `Solicitou a transferência: ${texto}` : 'Solicitou a transferência do atendimento.', ts });
  if (resultado) chat.push({ role: 'consultor', tipo: 'resultado', resultado, texto: `Resultado registrado: ${RESULTADOS[resultado]}${dataAdiamento ? ' para ' + fmt(dataAdiamento) : ''}.${pularIntranet ? ' (Contato já registrado na intranet antes: observação não gravada de novo.)' : ''}`, ts });
}
const resumoChat = chat.slice(-4).map(m => `${m.role}: ${m.texto}`).join(' | ');
return [{ json: {
  ...row, acao, resultado, statusAnterior: row.status, pularIntranet,
  // v24: veio da tela Respostas tardias (marca o SEM_CONFIRMACAO_DIARIO como tratado depois do registro)
  origemTardia: row.status === 'PENDENTE_RESPOSTA_TARDIA',
  semConfPedidoTardia: row.status === 'PENDENTE_RESPOSTA_TARDIA' ? String(((dpRow.respostaTardia || {}).pedidoLiderRegistro) || row.pedidoLider || '') : '',
  dataAdiamentoBR: dataAdiamento ? fmt(dataAdiamento) : null,
  textoConsultor: texto, chatConsultor: JSON.stringify(chat), resumoChat, erro
} }];

const base = $('Processar ação do consultor').first().json;
const out = $input.first().json || {};
const ia = String(out.text ?? out.output ?? '').trim().replace(/^["“”]+|["“”]+$/g, '');
const msg = ia || base.textoConsultor;
let chat = [];
try { chat = JSON.parse(base.chatConsultor || '[]'); if (!Array.isArray(chat)) chat = []; } catch (_) { chat = []; }
chat.push({ role: 'ia', tipo: 'envio', texto: 'Mensagem enviada ao cliente: ' + msg, ts: new Date().toISOString() });
return [{ json: { ...base, respostaCliente: msg, chatConsultor: JSON.stringify(chat) } }];

// Reincidência: pedido que já ficou sem confirmar em 2 dias diferentes (tabela SEM_CONFIRMACAO_DIARIO)
// e voltou hoje para confirmar -> vai para o consultor em vez de receber o template de novo.
const hoje = $now.setZone('America/Sao_Paulo').toFormat('yyyy-LL-dd');
const normPed = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };

// v8: a tabela vem do nó "Ler SEM_CONFIRMACAO_DIARIO" (a entrada deste nó agora é MENSAGENS_CLIENTE).
// Dias em que o cliente respondeu depois do encerramento não contam como "sem retorno".
const NAO_CONTA = ['RESPONDEU_DEPOIS', 'RESPOSTA_TARDIA_TRATADA'];
const historico = $('Ler SEM_CONFIRMACAO_DIARIO').all().map(i => i.json)
  .filter(r => r && String(r.pedidoLider ?? '').trim() !== '' && !NAO_CONTA.includes(String(r.status ?? '').toUpperCase()));

const porPedido = new Map();
for (const r of historico) {
  const k = normPed(r.pedidoLider);
  if (!k) continue;
  if (!porPedido.has(k)) porPedido.set(k, []);
  porPedido.get(k).push(r);
}

return $('Calcular Data de Entrega').all().map(({ json: p }) => {
  const regs = porPedido.get(normPed(p.pedidoLider)) ?? [];
  const jaEscalado = regs.some(r => String(r.status ?? '').toUpperCase() === 'ESCALADO');
  // dias distintos anteriores a hoje (rodar o fechamento 2x no mesmo dia não conta duas vezes)
  const dias = [...new Set(regs.map(r => String(r.dataRef ?? '').trim()).filter(x => x && x !== hoje))].sort();

  let acaoReincidencia = 'NORMAL';
  if (jaEscalado) acaoReincidencia = 'JA_ESCALADO';
  else if (dias.length >= 2) acaoReincidencia = 'ESCALAR';

  return { json: { ...p, acaoReincidencia, diasSemRetorno: dias, qtdDiasSemRetorno: dias.length } };
});

const MODO_TESTE = false;
const EMAIL_TESTE = 'mateus.oliveira@lider.design';
const SETOR_ATENDENTE = '0104-CENTRAL DE RELACIONAMENTO';

const htmlEmails = String($json.data ?? '');
// v25: o e-mail leva TODOS os pedidos do consultor que saíram hoje por "2 dias sem retorno":
// os que viraram ESCALAR agora e os que já tinham sido encaminhados antes (JA_ESCALADO) e voltaram na planilha.
// Antes só ia o ESCALAR (caso Raynner 12/11: e-mail só com o pedido 209643; o 206407 ficou de fora).
const VAI_NO_EMAIL = ['ESCALAR', 'JA_ESCALADO'];
const normPedEmail = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };
const vistos = new Set();
const itens = $('Verificar resposta tardia').all().map(i => i.json)
  .filter(p => VAI_NO_EMAIL.includes(p.acaoReincidencia))
  .filter(p => { const k = normPedEmail(p.pedidoLider || p.Pedido); if (!k || vistos.has(k)) return !k; vistos.add(k); return true; })
  .sort((a, b) => (a.acaoReincidencia === 'ESCALAR' ? 0 : 1) - (b.acaoReincidencia === 'ESCALAR' ? 0 : 1)
    || Number(normPedEmail(a.pedidoLider || a.Pedido)) - Number(normPedEmail(b.pedidoLider || b.Pedido)));

if (!itens.length) return [];

const limpar = s => String(s ?? '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

const norm = s => limpar(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const ignorar = ['DE', 'DA', 'DO', 'DAS', 'DOS', 'E'];

const registros = [];
for (const linha of (htmlEmails.match(/<tr[\s\S]*?<\/tr>/gi) || [])) {
  const tds = linha.match(/<td[\s\S]*?<\/td>/gi) || [];
  if (tds.length < 5) continue;

  const email = limpar(tds[2]).toLowerCase();
  if (!email.includes('@')) continue;

  registros.push({ nome: norm(tds[0]), email, setor: norm(tds[4]) });
}

function buscarAtendente(responsavel) {
  const tokens = norm(responsavel).split(' ').filter(t => t && !ignorar.includes(t));
  if (!tokens.length) return { email: null, status: 'SEM_RESPONSAVEL' };

  const confere = nome => {
    const tn = nome.split(' ').filter(Boolean);
    return tokens.every(t => tn.some(x => x === t || (t.length >= 4 && x.startsWith(t))));
  };

  const cand = registros.filter(r => r.setor.includes(SETOR_ATENDENTE) && confere(r.nome));
  const nomes = [...new Set(cand.map(c => c.nome))];
  const emails = [...new Set(cand.map(c => c.email))];

  if (!emails.length) return { email: null, status: 'NAO_ENCONTRADO' };
  if (nomes.length > 1) return { email: null, status: 'AMBIGUO_NOMES: ' + nomes.join(' / ') };
  if (emails.length === 1) return { email: emails[0], status: 'OK' };

  const partes = nomes[0].split(' ').filter(p => p && !ignorar.includes(p));
  const primeiro = partes[0].toLowerCase();
  const ultimo = partes[partes.length - 1].toLowerCase();
  const preferidos = emails.filter(e => {
    const local = e.split('@')[0];
    return local.startsWith(primeiro + '.') && local.includes(ultimo);
  });

  return preferidos.length === 1
    ? { email: preferidos[0], status: 'OK_NOME_REPETIDO' }
    : { email: null, status: 'AMBIGUO_EMAILS: ' + emails.join(' / ') };
}

const hora = Number(new Intl.DateTimeFormat('pt-BR', { hour: 'numeric', hour12: false, timeZone: 'America/Sao_Paulo' }).format(new Date()));
const saudacao = hora < 12 ? 'Bom dia' : hora < 18 ? 'Boa tarde' : 'Boa noite';

const grupos = {};
for (const p of itens) {
  const chave = String(p['RESPONSÁVEL'] ?? '').trim() || 'SEM RESPONSÁVEL';
  (grupos[chave] ??= []).push(p);
}

const numPedido = p => {
  const bruto = String(p.Pedido ?? '').trim();
  if (bruto) return bruto.replace(/^\((\d+)\)\s*/, '$1-');
  return p.pedidoLider ? '11-' + p.pedidoLider : '-';
};
const nomeCliente = p => p.Cliente || p.clienteLider || '-';
const fmtDia = iso => { const [a, m, d] = String(iso).split('-'); return d && m ? `${d}/${m}` : iso; };
const situacao = p => p.acaoReincidencia === 'JA_ESCALADO' ? 'Já encaminhado antes' : '1º aviso';
const telefones = p => [...new Set([p.telefone, p.telefone2].map(t => String(t ?? '').trim()).filter(Boolean))].join(' / ') || '-';

return Object.entries(grupos).map(([responsavel, lista]) => {
  const { email: emailAtendente, status } = buscarAtendente(responsavel);

  const primeiroNome = responsavel.split(/\s+/)[0];
  const nomeFmt = primeiroNome.charAt(0).toUpperCase() + primeiroNome.slice(1).toLowerCase();

  const th = t => `<th style="border:1px solid #999;padding:4px 8px;background:#f2f2f2;font-size:12px;">${t}</th>`;
  const td = t => `<td style="border:1px solid #999;padding:4px 8px;font-size:12px;">${esc(t)}</td>`;

  const linhas = lista.map(p => `<tr>
    ${td(numPedido(p))}
    ${td(nomeCliente(p))}
    ${td(telefones(p))}
    ${td((p.cidadeEntrega || '-') + '/' + (p.ufEntrega || '-'))}
    ${td((p.diasSemRetorno || []).map(fmtDia).join(', '))}
    ${td(situacao(p))}
  </tr>`).join('');

  const aviso = MODO_TESTE
    ? `<p style="color:#c00;">[TESTE] destinatário real: ${esc(emailAtendente || 'não encontrado')} (responsável: ${esc(responsavel)}; busca: ${esc(status)})</p>`
    : '';

  const html = `<div style="font-family:Arial,sans-serif;font-size:14px;">
${aviso}
<p>${saudacao}, ${esc(nomeFmt)}. Tudo bem?</p>
<p>Os pedidos abaixo ficaram sem confirmar a data de entrega em 2 dias no fluxo automático e voltaram hoje na planilha para confirmação. O template não foi reenviado: por favor, tente contato com o cliente por outro meio (ligação, e-mail ou representante).</p>
<table style="border-collapse:collapse;font-family:Arial,sans-serif;">
<tr>${['Pedido', 'Cliente', 'Telefone(s)', 'Destino', 'Dias sem retorno', 'Situação'].map(th).join('')}</tr>
${linhas}
</table>
${lista.some(p => p.acaoReincidencia === 'JA_ESCALADO') ? '<p style="font-size:12px;color:#555;">"Já encaminhado antes": o pedido já tinha sido passado a você num dia anterior e continua sem confirmação na planilha.</p>\n' : ''}<p>Obrigado!</p>
</div>`;

  const para = MODO_TESTE ? EMAIL_TESTE : (emailAtendente || EMAIL_TESTE);
  const prefixo = `${MODO_TESTE ? '[TESTE] ' : ''}${emailAtendente ? '' : '[SEM E-MAIL DO ATENDENTE] '}`;

  return {
    json: {
      para,
      assunto: `${prefixo}Pedidos sem confirmação há 2 dias - contato alternativo (${lista.length}): ${lista.map(p => p.pedidoPlanilha || p.pedidoLider).join(', ')}`,
      html,
      atendente: responsavel,
      emailAtendente,
      status
    }
  };
});

const linha = $('Escolher Linha').first().json;
const bruto = String($input.first().json.text ?? $input.first().json.output ?? '').trim();
let r = {};
try { r = JSON.parse(bruto.replace(/```json|```/g, '').trim()); } catch (_) {}
let tipo = String(r.tipo ?? '').toUpperCase();
if (!['DUVIDA', 'SEM_ACAO', 'REGRA'].includes(tipo)) tipo = 'DUVIDA'; // falha de leitura: melhor consultar do que ignorar o cliente
if (/^\[mensagem sem texto/i.test(String(linha.textoCliente || ''))) tipo = 'DUVIDA';
return [{ json: { ...linha, vigTipo: tipo, vigResumo: String(r.resumo ?? '') } }];

const linha = $('Interpretar classificação (vigilância)').first().json;
const base = $input.all().map(i => i.json).filter(r => r && r.id !== undefined && r.pergunta && r.resposta);
const lista = base.slice(-200); // limita o tamanho do prompt
const baseTexto = lista.map(r => `[ID ${r.id}]\nPergunta: ${r.pergunta}\nResposta: ${r.resposta}`).join('\n\n');
return [{ json: { ...linha, baseVazia: lista.length === 0, baseTexto } }];

parameters.text:
=Você é o assistente de atendimento da Líder Interiores. Um cliente enviou uma mensagem sobre a entrega do pedido. Verifique se alguma entrada da base de conhecimento responde a dúvida dele.

Mensagem do cliente:
{{ $json.textoCliente }}

Última mensagem enviada pela empresa (contexto):
{{ String($json.mensagem || '').slice(0, 600) }}

Base de conhecimento:
{{ $json.baseTexto }}

Regras:
- Use uma entrada somente se ela responder de fato à dúvida (mesmo assunto e mesma intenção). Perguntas parecidas sobre coisas diferentes NÃO servem.
- Se nenhuma servir com segurança, encontrou=false. Na dúvida, encontrou=false.
- Se encontrar, escreva "resposta" como mensagem curta, cordial e clara, em português do Brasil, no tom de WhatsApp, usando SOMENTE as informações da entrada. Não invente datas, prazos, valores ou promessas. Não mencione "base", "IA" ou "consultor".
- Responda APENAS com JSON, sem markdown: {"encontrou": true, "id": 12, "resposta": "texto"} ou {"encontrou": false, "id": null, "resposta": ""}

parameters.jsCode:
const j = $('Montar consulta à base').first().json;
const bruto = String($input.first().json.text ?? $input.first().json.output ?? '').trim();
let r = {};
try { r = JSON.parse(bruto.replace(/```json|```/g, '').trim()); } catch (_) {}
const base = $('Ler base de conhecimento').all().map(i => i.json).filter(x => x && x.id !== undefined);
const entrada = base.find(x => String(x.id) === String(r.id));
const resp = String(r.resposta ?? '').trim();
const usarBase = r.encontrou === true && !!entrada && !!resp;
return [{ json: { ...j, usarBase, kbId: usarBase ? entrada.id : null, kbUsos: usarBase ? Number(entrada.usos || 0) : 0, respostaBase: resp } }];

const j = $('Interpretar resposta da base').first().json;
const ts = new Date().toISOString();
let chat = [];
try { chat = JSON.parse(j.chatConsultor || '[]'); if (!Array.isArray(chat)) chat = []; } catch (_) { chat = []; }
chat.push({ role: 'cliente', texto: String(j.textoCliente || ''), ts });
chat.push({ role: 'ia', tipo: 'envio', texto: 'Resposta automática (base de conhecimento): ' + j.respostaBase, ts });
return [{ json: { id: j.id, chatConsultor: JSON.stringify(chat), kbId: j.kbId, kbUsos: j.kbUsos } }];

const n = $('Interpretar classificação (vigilância)').first().json;
const ts = new Date().toISOString();
let chat = [];
try { chat = JSON.parse(n.chatConsultor || '[]'); if (!Array.isArray(chat)) chat = []; } catch (_) { chat = []; }
chat.push({ role: 'cliente', texto: String(n.textoCliente || ''), ts });
const pergunta = [
  `O cliente ${n.cliente || ''} (pedido ${n.pedidoLider}) escreveu depois de confirmar a entrega e parece ter uma dúvida.`,
  n.vigResumo ? `Resumo: ${n.vigResumo}` : '',
  'Não encontrei essa resposta na minha base. O que devo responder? Escreva a orientação e eu passo ao cliente; ela também fica salva para eu responder sozinha em casos parecidos. Se for algo mais sério, solicite a transferência.'
].filter(Boolean).join('\n');
chat.push({ role: 'ia', tipo: 'pergunta', texto: pergunta, ts });
return [{ json: { id: n.id, pedidoLider: n.pedidoLider, contactId: n.contactId, cliente: n.cliente, chatConsultor: JSON.stringify(chat) } }];

const b = $('Montar resposta ao cliente').first().json;
let chat = [];
try { chat = JSON.parse(b.chatConsultor || '[]'); if (!Array.isArray(chat)) chat = []; } catch (_) {}
// mensagens do cliente desde o último envio ao cliente = a dúvida atual
let atual = [];
for (const m of chat) {
  if (m.role === 'ia' && m.tipo === 'envio') atual = [];
  else if (m.role === 'cliente') atual.push(String(m.texto || ''));
}
const perguntaCliente = atual.join(' / ').trim();
const orientacao = String(b.textoConsultor || '').trim();
if (!perguntaCliente || !orientacao || b.acao !== 'RESPONDER') return [];
const base = $input.all().map(i => i.json).filter(r => r && r.id !== undefined && r.pergunta && r.resposta).slice(-200);
const baseTexto = base.map(r => `[ID ${r.id}]\nPergunta: ${r.pergunta}\nResposta: ${r.resposta}`).join('\n\n');
return [{ json: { perguntaCliente, orientacao, respostaEnviada: String(b.respostaCliente || ''), baseTexto } }];

parameters.text:
=Você alimenta a base de conhecimento do atendimento da Líder Interiores (entrega de móveis). Um cliente fez uma pergunta, um consultor orientou a resposta e ela foi enviada ao cliente. Decida se essa resposta pode ser REUSADA com outros clientes e, se sim, escreva a entrada da base.

Pergunta do cliente: {{ $json.perguntaCliente }}
Orientação do consultor: {{ $json.orientacao }}
Mensagem enviada ao cliente: {{ $json.respostaEnviada }}

Base atual:
{{ $json.baseTexto || '(vazia)' }}

Regras:
- generalizavel=false se a resposta depende do pedido, cliente, data, valor ou situação específica daquele caso (ex.: "seu pedido sai dia 12", "vou verificar o seu pedido"), se for apenas recado/agradecimento, ou se for encaminhamento.
- generalizavel=true somente para informação de política ou procedimento válida para qualquer cliente (ex.: como funciona o prazo, como solicitar algo, horário de atendimento).
- "pergunta": reescreva a dúvida de forma genérica e curta, sem nomes, números de pedido ou datas.
- "resposta": reescreva a resposta para valer para qualquer cliente, sem nomes, números de pedido, datas ou valores do caso. Use só o que o consultor informou; não invente nada.
- Se uma entrada da base atual trata do mesmo assunto, devolva o ID dela em "idExistente" (a nova resposta a substitui); senão null.
- Responda APENAS com JSON, sem markdown: {"generalizavel": true, "pergunta": "", "resposta": "", "idExistente": null}

parameters.jsCode:
const bruto = String($input.first().json.text ?? $input.first().json.output ?? '').trim();
let r = {};
try { r = JSON.parse(bruto.replace(/```json|```/g, '').trim()); } catch (_) { return []; }
const pergunta = String(r.pergunta ?? '').trim();
const resposta = String(r.resposta ?? '').trim();
if (r.generalizavel !== true || !pergunta || !resposta) return [];
const base = $('Ler base (aprendizado)').all().map(i => i.json).filter(x => x && x.id !== undefined);
const existente = r.idExistente !== null && r.idExistente !== undefined ? base.find(x => String(x.id) === String(r.idExistente)) : null;
return [{ json: { pergunta, resposta, kbIdExistente: existente ? existente.id : null } }];

// Pedido cujo RESPONSÁVEL não está nas listas de Planejados / Móveis soltos.
// Antes era descartado em silêncio; agora vai para revisão BLOQUEADA com o motivo.
return $input.all().map(i => {
  const r = String(i.json['RESPONSÁVEL'] || '').trim() || 'vazio';
  return { json: { ...i.json, bloqueado: true, motivosBloqueio: `Responsável "${r}" não está cadastrado em Planejados nem Móveis soltos` } };
});

// VARREDURA DE VIGILÂNCIA (roda sozinha a cada 10 min, sem depender de Wait/execução aberta).
// - FECHAR: pedido CONCLUIDO cuja vigilância (vigiaAte) venceu -> fecha o chamado no DigiSac.
// - LIMPAR: vigilância vencida em outro status (ex.: transferido) -> só limpa vigiaAte, NÃO fecha.
// - LEMBRAR: consulta aguardando o consultor há muito tempo -> lembrete por e-mail (com limite).
const AGORA = Date.now();
const LEMBRAR_APOS_MIN = 60;      // 1ª cobrança após 1h sem resposta do consultor
const REPETIR_APOS_MIN = 180;     // repete a cada 3h
const MAX_LEMBRETES = 4;
const out = [];
const min = ts => { const t = new Date(ts).getTime(); return isNaN(t) ? null : (AGORA - t) / 60000; };

for (const { json: r } of $input.all()) {
  if (!r || r.id === undefined || !String(r.pedidoLider ?? '').trim()) continue;
  const status = String(r.status ?? '');
  let chat = [];
  try { chat = JSON.parse(r.chatConsultor || '[]'); if (!Array.isArray(chat)) chat = []; } catch (_) { chat = []; }

  if (status === 'AGUARDANDO_CONSULTOR') {
    const perguntas = chat.filter(m => m && m.role === 'ia' && m.tipo === 'pergunta');
    const lembretes = chat.filter(m => m && m.tipo === 'lembrete');
    const refTs = perguntas.length ? perguntas[perguntas.length - 1].ts : (r.respondidoEm || r.enviadoEm);
    const desdePergunta = min(refTs);
    if (desdePergunta === null || desdePergunta < LEMBRAR_APOS_MIN) continue;
    if (lembretes.length >= MAX_LEMBRETES) continue;
    const desdeUltimo = lembretes.length ? min(lembretes[lembretes.length - 1].ts) : null;
    if (desdeUltimo !== null && desdeUltimo < REPETIR_APOS_MIN) continue;
    const novo = [...chat, { role: 'ia', tipo: 'lembrete', texto: `Lembrete enviado ao responsável por e-mail: consulta sem resposta há ${Math.round(desdePergunta)} min.`, ts: new Date().toISOString() }];
    out.push({ json: { acao: 'LEMBRAR', id: r.id, pedidoLider: r.pedidoLider, cliente: r.cliente || '', contactId: r.contactId || '', status, minutos: Math.round(desdePergunta), chatConsultorNovo: JSON.stringify(novo) } });
    continue;
  }

  if (!String(r.vigiaAte ?? '').trim()) continue;          // sem vigilância
  const venc = new Date(r.vigiaAte).getTime();
  if (!isNaN(venc) && venc > AGORA) continue;              // ainda vigiando

  const pode = status === 'CONCLUIDO' && !!r.contactId;
  const novo = [...chat, { role: 'ia', tipo: 'encerramento', texto: pode ? 'Vigilância encerrada: chamado fechado automaticamente.' : `Vigilância encerrada (status ${status}); chamado mantido aberto.`, ts: new Date().toISOString() }];
  out.push({ json: { acao: pode ? 'FECHAR' : 'LIMPAR', id: r.id, pedidoLider: r.pedidoLider, cliente: r.cliente || '', contactId: r.contactId || '', status, chatConsultorNovo: JSON.stringify(novo) } });
}
return out;

// Mantém só os eventos dos últimos 3 dias (a tela de status lê a tabela inteira a cada consulta)
const LIMITE = Date.now() - 3 * 86400000;
return $input.all()
  .map(i => i.json)
  .filter(r => r && r.id !== undefined && r.id !== null && Number(r.ts) > 0 && Number(r.ts) < LIMITE)
  .map(r => ({ json: { id: r.id } }));

// Pedido com boleto em ANALISAR (ou consulta com erro) cuja data de 50% não pôde ser calculada.
// O pedido já foi BLOQUEADO (PENDENCIA_BOLETO); aqui só avisamos para tratar manualmente.
const itens = $input.all().map(i => i.json);
if (!itens.length) return [];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linhas = itens.map(p => `<tr><td>${esc(p.Pedido || ('11-' + p.pedidoLider))}</td><td>${esc(p.clienteLider || p.Cliente)}</td><td>${esc(p['RESPONSÁVEL'])}</td><td>${esc(p.boleto?.status)}</td><td>${esc(p.pagamento50?.motivo || 'desconhecido')}</td></tr>`).join('');
return [{ json: {
  assunto: `[AÇÃO MANUAL] Boleto 50% não calculado - ${itens.length} pedido(s)`,
  html: `<p>Os pedidos abaixo estão com boleto em análise (ou a consulta de boletos falhou) e o fluxo não conseguiu calcular a nova data de entrega. Eles foram bloqueados (PENDENCIA_BOLETO) e <b>não receberam mensagem</b>. Favor verificar manualmente.</p>
<table border="1" cellpadding="5" style="border-collapse:collapse;font-family:Arial;font-size:12px"><tr><th>Pedido</th><th>Cliente</th><th>Responsável</th><th>Status boleto</th><th>Motivo</th></tr>${linhas}</table>`
} }];

// A API do Digisac falhou em alguma tentativa de busca: NÃO cria contato (evita duplicar)
// O pedido segue sem contactId e vai para revisão BLOQUEADO (motivo SEM_CONTATO_DIGISAC).
return [{ json: { ...$json, statusBusca: 'ERRO_BUSCA_DIGISAC', contactId: null } }];

// Qualquer erro do fluxo (disparo, webhooks, agendamentos) gera um e-mail.
const j = $input.first().json || {};
const ex = j.execution || {};
const err = ex.error || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const quando = $now.setZone('America/Sao_Paulo').toFormat('dd/LL/yyyy HH:mm:ss');
return [{ json: {
  assunto: `[n8n] Erro no fluxo Central Líder - ${ex.lastNodeExecuted || 'nó desconhecido'}`,
  html: `<p><b>Quando:</b> ${quando}<br><b>Nó:</b> ${esc(ex.lastNodeExecuted)}<br><b>Modo:</b> ${esc(ex.mode)}<br>
<b>Execução:</b> ${ex.url ? `<a href="${esc(ex.url)}">${esc(ex.id)}</a>` : esc(ex.id)}</p>
<p><b>Erro:</b> ${esc(err.message)}${err.description ? '<br>' + esc(err.description) : ''}</p>`
} }];

// Cliente costuma mandar várias mensagens seguidas ("Extender*", "Deixar para março").
// Cada uma dispara uma execução. Aqui só a execução da ÚLTIMA mensagem segue; ela junta
// todas as mensagens desde a última resposta da Líder e monta o histórico da conversa.
const JANELA_MS = 5 * 60 * 1000;   // junta no máximo os últimos 5 min de mensagens sem resposta
const HISTORICO_MAX = 14;          // falas anteriores enviadas para a IA

const me = $('Filtrar Mensagem').first().json;
const meTs = Number(me.ts) || Date.now();
const ord = (a, b) => (Number(a.ts) - Number(b.ts)) || String(a.messageId).localeCompare(String(b.messageId));

let linhas = $input.all().map(i => i.json)
  .filter(r => r && !r.error && String(r.contactId ?? '') === String(me.contactId) && String(r.texto ?? '').trim() !== '')
  .sort(ord);

// v21 — ANTI-REPETIÇÃO (entrada): o Digisac pode entregar o MESMO evento mais de uma vez
// (reenvio, instabilidade, atualização da mensagem). Cada entrega grava outra linha com o mesmo messageId.
// Só segue a execução que gravou a 1ª linha; as outras param aqui e o cliente não recebe resposta em dobro.
const meId = String(me.messageId ?? '');
if (meId && !meId.startsWith('sem-id-')) {
  const jaRecebida = linhas.some(r => String(r.papel ?? '').toUpperCase() === 'CLIENTE' && String(r.messageId) === meId && Number(r.ts) < meTs);
  if (jaRecebida) return [];
}
// No histórico, cada mensagem do cliente entra uma vez só (fica a 1ª linha de cada messageId).
const idsVistos = new Set();
linhas = linhas.filter(r => {
  if (String(r.papel ?? '').toUpperCase() !== 'CLIENTE') return true;
  const k = String(r.messageId ?? '');
  if (!k || k.startsWith('sem-id-')) return true;
  if (idsVistos.has(k)) return false;
  idsVistos.add(k); return true;
});

// v18 — RECOMEÇO: o consultor recomeçou o atendimento deste contato no painel.
// A IA só considera as mensagens DEPOIS da última marca (papel RECOMECO); a marca em si não entra no histórico.
const marcasRecomeco = linhas.filter(r => String(r.papel ?? '').toUpperCase() === 'RECOMECO' && Number(r.ts) <= meTs);
const corteRecomeco = marcasRecomeco.length ? Number(marcasRecomeco[marcasRecomeco.length - 1].ts) : 0;
linhas = linhas.filter(r => String(r.papel ?? '').toUpperCase() !== 'RECOMECO' && Number(r.ts) > corteRecomeco);

const doCliente = linhas.filter(r => r.papel === 'CLIENTE');
const maisNova = doCliente[doCliente.length - 1];

// Chegou mensagem mais nova depois desta: a execução dela responde por todas.
if (maisNova && String(maisNova.messageId) !== String(me.messageId) && ord(maisNova, { ts: meTs, messageId: me.messageId }) > 0) {
  return [];
}

const bots = linhas.filter(r => r.papel === 'BOT' && Number(r.ts) <= meTs);
const ultimoBotTs = bots.length ? Number(bots[bots.length - 1].ts) : 0;
const corte = Math.max(ultimoBotTs, meTs - JANELA_MS);

let grupo = doCliente.filter(r => Number(r.ts) > corte && Number(r.ts) <= meTs);
if (!grupo.some(r => String(r.messageId) === String(me.messageId))) grupo.push({ texto: me.text, ts: meTs, messageId: me.messageId });
grupo.sort(ord);

const historico = linhas
  .filter(r => Number(r.ts) <= corte)
  .slice(-HISTORICO_MAX)
  .map(r => `${r.papel === 'BOT' ? 'Líder' : 'Cliente'}: ${String(r.texto).replace(/\s+/g, ' ').trim().slice(0, 600)}`)
  .join('\n');

return [{ json: {
  ...me,
  text: grupo.map(r => String(r.texto).trim()).join('\n'),
  qtdMensagensAgrupadas: grupo.length,
  historico
} }];

// Guarda o que a Líder respondeu, para a IA ter o histórico e para o agrupamento saber
// a partir de quando juntar as próximas mensagens do cliente.
const fonte = $prevNode.name;
const tentar = f => { try { return f(); } catch (e) { return ''; } };
let texto = '';
if (fonte === 'POST Enviar mensagem para contato ja cadastrado1') {
  texto = tentar(() => $('Normalizar Categoria').first().json.respostaFixa);
} else if (fonte === 'POST Enviar mensagem para contato ja cadastrado') {
  texto = tentar(() => $('Escolher Linha').all().map(i => i.json.mensagem).filter(Boolean).join('\n\n'));
} else if (fonte === 'Enviar Confirmação Adiamento') {
  texto = tentar(() => {
    const ok = $('Confirmar Alteração Intranet').first().json.alteracaoDataConcluida;
    const dt = $('Normalizar Categoria').first().json.dataSolicitada;
    return ok ? `Conseguimos atualizar a previsão de entrega para ${dt}.`
              : `Recebi o pedido para adiar para ${dt}, mas não consegui registrar no sistema. Ofereci encaminhar ao responsável.`;
  });
} else if (fonte === 'Enviar resposta da base ao cliente') {
  texto = tentar(() => $('Interpretar resposta da base').first().json.respostaBase);
}
const contactId = tentar(() => $('Escolher Linha').first().json.contactId);
if (!contactId || !String(texto).trim()) return [];
const ts = Date.now();
return [{ json: { contactId, messageId: 'lider-' + ts, papel: 'BOT', texto: String(texto).slice(0, 3000), ts } }];

// Entrega à IA as datas concretas (hoje, prevista, limite) e o histórico da conversa.
const j = $input.first().json;
const LIMITE_ADIAMENTO_DIAS = 130;
const parseBR = s => {
  const m = String(s ?? '').match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  if (!m) return null;
  const d = new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]));
  return d.getMonth() === Number(m[2]) - 1 ? d : null;
};
const fmt = d => `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
const datas = String(j.mensagem ?? '').match(/\b\d{1,2}[\/.-]\d{1,2}[\/.-]\d{4}\b/g) || [];
// v12: mensagem única para vários pedidos -> usa as datas registradas de cada pedido
let dpJ = {};
try { dpJ = JSON.parse(j.dadosPedido || '{}'); } catch (_) {}
const membros = Array.isArray(dpJ.pedidosGrupo) && dpJ.pedidosGrupo.length > 1 ? dpJ.pedidosGrupo : null;
const datasGrupo = membros ? membros.flatMap(m => (m.entregas || []).map(e => parseBR(e?.data))).filter(Boolean).sort((a, b) => a - b) : [];
// v26: depois do registro (ex.: adiamento já feito), a referência é a data que ficou registrada
const registro = dpJ.registroContato || null;
const dataRegistrada = parseBR(registro && registro.dataEntrega);
const prevista = dataRegistrada || (membros ? (datasGrupo[0] || null) : (datas.map(parseBR).find(Boolean) || null));
const limite = prevista ? new Date(prevista.getFullYear(), prevista.getMonth(), prevista.getDate() + LIMITE_ADIAMENTO_DIAS) : null;
const hoje = $now.setZone('America/Sao_Paulo');
return [{ json: {
  ...j,
  ctxHoje: `${hoje.toFormat('dd/LL/yyyy')} (${hoje.setLocale('pt-BR').toFormat('cccc')})`,
  ctxPrevista: dataRegistrada
    ? `${fmt(dataRegistrada)} (data já registrada na intranet${membros ? ' para todos os pedidos da mensagem' : ''})`
    : membros
    ? membros.map(m => `pedido ${m.pedidoLider}: ${(m.entregas || []).map(e => e.data).join(', ')}`).join('; ') + ' (mensagem única: a resposta do cliente vale para todos esses pedidos)'
    : (prevista ? fmt(prevista) : 'não identificada'),
  ctxLimite: limite ? fmt(limite) : 'não identificada',
  ctxRegistro: registro
    ? `O contato deste pedido JÁ FOI REGISTRADO na planilha e na intranet (${registro.resultado || registro.categoria || 'registrado'}${registro.dataEntrega ? ', data ' + registro.dataEntrega : ''}). Não existe novo registro: só interprete a fala.`
    : 'Ainda não registrado.',
  ctxHistorico: String(j.historicoConversa || '').slice(-4000) || '(sem mensagens anteriores registradas)'
} }];

// Monta tudo o que o fluxo automático faria se a IA tivesse entendido o cliente.
// v12: mensagem única para vários pedidos do mesmo cliente -> 1 item por pedido (o resultado vale para todos).
const r = $('Processar ação do consultor').first().json;
let dp = {};
try { dp = JSON.parse(r.dadosPedido ?? '{}'); } catch (_) {}

const semAcento = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '');
const toISO = br => { const m = String(br ?? '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/); return m ? `${m[3]}-${m[2]}-${m[1]}` : ''; };
const numBR = d => Number(String(d).split('/').reverse().join(''));
const CATEGORIA = { CONFIRMADO: 'ACEITA', NAO_CONCORDA: 'NAO_ACEITA', ADIADO: 'PEDE_ADIAR' };

function montar(fonte, usarMensagem) {
  const pedidoLider = String(fonte.pedidoLider ?? '').trim();
  const cliente = String(fonte.clienteLider ?? dp.Cliente ?? r.cliente ?? '').trim();

  // datas informadas ao cliente
  let datas = Array.isArray(fonte.entregas) ? fonte.entregas.map(e => e?.data).filter(Boolean) : [];
  if (!datas.length && usarMensagem) datas = String(r.mensagem ?? '').match(/\b\d{2}\/\d{2}\/\d{4}\b/g) || [];
  datas = [...new Set(datas)];
  if (!usarMensagem) datas.sort((a, b) => numBR(a) - numBR(b));

  const primeiraConfirmacao = String((usarMensagem ? (r.tipoMensagem || dp.tipoMensagem) : fonte.tipoMensagem) || '') === 'PRIMEIRA_CONFIRMACAO';
  // 1ª confirmação de planejados: mantém a data do sistema (fictícia 01/12/2040) no aviso da intranet
  if (primeiraConfirmacao && !datas.length) datas = [fonte.dataSistema || fonte.entregaLider || '01/12/2040'];

  const pedidoSheet = String(fonte.Pedido ?? fonte.pedidoOriginal ?? `11-${pedidoLider}`).trim();

  return {
    id: r.id, pedidoLider, pedidoSheet, contactId: r.contactId,
    clienteIntranet: semAcento(cliente).toUpperCase(),
    resultado: r.resultado, categoria: CATEGORIA[r.resultado],
    datasInformadas: datas.join(' E '),
    dataPrevistaBR: datas[0] || null,
    dataPrevistaISO: toISO(datas[0]),
    dataAdiamentoBR: r.dataAdiamentoBR,
    dataAdiamentoISO: toISO(r.dataAdiamentoBR),
    statusAnterior: r.statusAnterior,
    primeiraConfirmacao,
    pularIntranet: !!r.pularIntranet,   // v27
    vigiaAteAnterior: r.vigiaAte || ''
  };
}

const membros = Array.isArray(dp.pedidosGrupo) && dp.pedidosGrupo.length > 1 ? dp.pedidosGrupo : null;
if (membros) {
  return membros.map(m => ({ json: { ...montar(m, false), pedidoPrincipal: String(r.pedidoLider ?? ''), qtdPedidosGrupo: membros.length } }));
}

const fonteSolo = {
  pedidoLider: r.pedidoLider ?? dp.pedidoLider,
  clienteLider: dp.clienteLider ?? dp.Cliente ?? r.cliente,
  entregas: dp.entregas,
  dataSistema: dp.dataSistema, entregaLider: dp.entregaLider,
  Pedido: dp.Pedido, pedidoOriginal: dp.pedidoOriginal
};
return [{ json: montar(fonteSolo, true) }];

// v12: roda 1 vez por pedido.
const p = $('Itens do registro (consultor)').item.json;
const html = String($json.data ?? '');
const itens = [];
for (const tag of (html.match(/<input\b[^>]*>/gi) || [])) {
  if (!/name\s*=\s*["']?item\[\]["']?/i.test(tag)) continue;
  const v = tag.match(/value\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
  if (v) itens.push((v[1] ?? v[2] ?? v[3] ?? '').replace(/&amp;/g, '&'));
}
const unicos = [...new Set(itens)];
if (!unicos.length) {
  const txt = html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  return { json: { urlAlterar: null, pedidoLider: p.pedidoLider, erroAdiamento: `Itens do formulário não encontrados. Resposta: ${txt.slice(0, 200)}` } };
}
const observacao = `ADIAMENTO SOLICITADO PELO CLIENTE (REGISTRADO PELO CONSULTOR): DATA ALTERADA DE ${p.dataPrevistaBR || '-'} PARA ${p.dataAdiamentoBR}.`;
const params = [['data', p.dataAdiamentoISO], ['cod_empresa', '11'], ['pedido', p.pedidoLider], ['motivo', 'SOLICITACAO DO CLIENTE'],
  ['agendamento', ''], ['observacao', observacao], ['opcao[]', 'A'], ...unicos.map(i => ['item[]', i])];
const qs = params.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
return { json: { urlAlterar: `http://192.168.0.6/vdp/altera_data_entrega2.php?${qs}`, qtdItens: unicos.length, pedidoLider: p.pedidoLider } };

// v12: 1 item por pedido (mensagem única pode ter vários pedidos do mesmo cliente).
const lista = $('Itens do registro (consultor)').all().map(i => i.json);
const entradas = $input.all();
const semAcento = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '');
const ts = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(new Date()).replace(',', '');
let urls = [];
try { urls = $('Montar URL (consultor)').all().map(i => i.json); } catch (_) { urls = []; }

return lista.map((p, i) => {
  let alteracaoOk = null, erroAdiamento = null;
  if (p.resultado === 'ADIADO') {
    const montar = urls[i] || {};
    const resp = (entradas[i] || {}).json || {};
    alteracaoOk = !!montar.urlAlterar && !resp.error;
    if (!alteracaoOk) erroAdiamento = montar.erroAdiamento || String(resp.error?.message || resp.error || 'falha ao alterar a data na intranet');
  }
  let observacao = '', datEntrega = p.dataPrevistaISO;
  if (p.primeiraConfirmacao && p.resultado === 'CONFIRMADO') observacao = 'CLIENTE CONTATADO VIA WHATSAPP (1A CONFIRMACAO - PLANEJADOS) E CONFIRMOU O RECEBIMENTO DA MENSAGEM. PRAZO DE ENTREGA SERA INFORMADO APOS A POSTAGEM DO PROJETO. (ATENDIMENTO PELO CONSULTOR)';
  else if (p.resultado === 'CONFIRMADO') observacao = `CLIENTE CONTATADO VIA WHATSAPP E CONFIRMOU A DATA DE ENTREGA ${p.datasInformadas}. (ATENDIMENTO PELO CONSULTOR)`;
  else if (p.resultado === 'NAO_CONCORDA') observacao = `CLIENTE CONTATADO VIA WHATSAPP E NAO ACEITA A DATA DE ENTREGA ${p.datasInformadas}. (ATENDIMENTO PELO CONSULTOR)`;
  else if (p.resultado === 'ADIADO' && alteracaoOk) { datEntrega = p.dataAdiamentoISO; observacao = `CLIENTE CONTATADO VIA WHATSAPP E SOLICITOU ADIAMENTO DA ENTREGA DE ${p.dataPrevistaBR || p.datasInformadas} PARA ${p.dataAdiamentoBR}. PRAZO ALTERADO NO SISTEMA. (ATENDIMENTO PELO CONSULTOR)`; }
  else if (p.resultado === 'ADIADO') observacao = `CLIENTE CONTATADO VIA WHATSAPP E SOLICITOU ADIAMENTO DA ENTREGA PARA ${p.dataAdiamentoBR}. ALTERACAO AUTOMATICA FALHOU: AJUSTAR O PRAZO MANUALMENTE.`;

  const sheet = {
    CONFIRMADO: ['SIM', 'CONFIRMADO'],
    NAO_CONCORDA: ['SIM', 'CLIENTE NÃO CONCORDA'],
    ADIADO: alteracaoOk ? ['SIM', 'CONFIRMADO'] : ['SIM', 'ADIAR MANUALMENTE (FALHA INTRANET)']
  }[p.resultado] || ['', ''];

  return { json: { ...p, alteracaoOk, erroAdiamento, observacao: semAcento(observacao).toUpperCase(), datEntrega,
    temObservacao: /* v27: já registrado -> não grava de novo */ !p.pularIntranet && !!(observacao && p.pedidoLider && datEntrega), sheetG: sheet[0], sheetH: sheet[1], sheetI: ts }, pairedItem: { item: Math.min(i, Math.max(entradas.length - 1, 0)) } };
});

// v12: 1 item por pedido (mensagem única pode ter vários pedidos).
const regs = $('Montar observação (consultor)').all().map(i => i.json);
const norm = v => { const g = String(v ?? '').match(/\d+/g); return g ? g[g.length - 1].replace(/^0+/, '') : ''; };
const linhas = $input.all().map(i => i.json).filter(r => r && r.row_number !== undefined);
return regs.map(p => {
  const alvo = norm(p.pedidoSheet) || norm(p.pedidoLider);
  let achadas = linhas.filter(r => norm(r['Pedido']) === alvo);
  if (achadas.length > 1) { const ex = achadas.filter(r => String(r['Pedido']).trim() === p.pedidoSheet); if (ex.length) achadas = ex; }
