// Qualquer dúvida (erro na API, resposta estranha) = NÃO envia; o pedido fica no loop de 30 min.
function avaliarChamado(contactId, respostaItens, nomesUsuarios) {
  const cid = String(contactId ?? '').trim();
  const nomes = nomesUsuarios || {};
  const nomeDe = id => nomes[String(id)] || String(id);
  const r = (livre, situacao, motivo, extra = {}) => ({
    chamadoLivre: livre,
    chamadoSituacao: situacao,
    chamadoMotivo: motivo,
    chamadoVerificadoEm: new Date().toISOString(),
    ...extra
  });

  if (!cid) return r(false, 'INDETERMINADO', 'Sem contactId para consultar o chamado.');

  const itens = (respostaItens || []).map(i => (i && i.json !== undefined ? i.json : i)).filter(Boolean);
  if (!itens.length) return r(false, 'INDETERMINADO', 'Consulta de chamados sem resposta.');
  const comErro = itens.find(j => j.error);
  if (comErro) {
    const msg = typeof comErro.error === 'string' ? comErro.error : (comErro.error.message || JSON.stringify(comErro.error));
    return r(false, 'INDETERMINADO', 'Erro ao consultar chamados: ' + String(msg).slice(0, 200));
  }

  let lista = null;
  if (itens.length === 1 && Array.isArray(itens[0].data)) lista = itens[0].data;
  else if (itens.every(j => Object.prototype.hasOwnProperty.call(j, 'isOpen'))) lista = itens;
  if (!Array.isArray(lista)) return r(false, 'INDETERMINADO', 'Resposta inesperada da consulta de chamados.');

  // Se vier chamado de outro contato, o filtro não foi aplicado: não dá para confiar no resultado.
  if (lista.some(t => t && t.contactId && String(t.contactId) !== cid)) {
    return r(false, 'INDETERMINADO', 'A API não filtrou por contato; envio bloqueado por segurança.');
  }

  const abertos = lista.filter(t => t && (t.isOpen === true || t.isOpen === 'true' || t.isOpen === 1));
  if (!abertos.length) return r(true, 'SEM_CHAMADO', 'Nenhum chamado aberto para o contato.');
  if (abertos.some(t => !Object.prototype.hasOwnProperty.call(t, 'userId'))) {
    return r(false, 'INDETERMINADO', 'Chamado aberto sem a informação do atendente.');
  }

  const deOutros = abertos.filter(t => !MEUS_USER_IDS.includes(String(t.userId ?? '')));
  if (!deOutros.length) return r(true, 'CHAMADO_MEU', 'Chamado aberto já está comigo.', { chamadoId: String(abertos[0].id ?? '') });

  const comAtendente = deOutros.find(t => t.userId);
  if (comAtendente) {
    return r(false, 'OCUPADO', `Chamado aberto com ${nomeDe(comAtendente.userId)}.`, {
      chamadoId: String(comAtendente.id ?? ''),
      chamadoUserId: String(comAtendente.userId),
      chamadoAtendente: nomeDe(comAtendente.userId),
      chamadoDepartamentoId: String(comAtendente.departmentId ?? '')
    });
  }
  if (BLOQUEAR_FILA_SEM_ATENDENTE) {
    return r(false, 'FILA_SEM_ATENDENTE', 'Chamado aberto na fila, ainda sem atendente.', {
      chamadoId: String(deOutros[0].id ?? ''),
      chamadoDepartamentoId: String(deOutros[0].departmentId ?? '')
    });
  }
  return r(true, 'FILA_LIBERADA', 'Chamado na fila sem atendente (liberado pela configuração).', { chamadoId: String(deOutros[0].id ?? '') });
}

function mapaNomes(itensUsuarios) {
  const nomes = {};
  (function coletar(v) {
    if (!v) return;
    if (Array.isArray(v)) { v.forEach(coletar); return; }
    if (typeof v !== 'object') return;
    const id = v.id ?? v.userId;
    const name = v.name ?? v.nome;
    if (id && name) nomes[String(id)] = String(name);
    for (const k of ['data', 'users', 'items', 'results', 'rows']) if (v[k] && typeof v[k] === 'object') coletar(v[k]);
  })((itensUsuarios || []).map(i => (i && i.json !== undefined ? i.json : i)));
  return nomes;
}

function semCamposChamado(obj) {
  const o = { ...obj };
  for (const k of ['chamadoLivre', 'chamadoSituacao', 'chamadoMotivo', 'chamadoVerificadoEm', 'chamadoId', 'chamadoUserId',
    'chamadoAtendente', 'chamadoDepartamentoId', 'rowId', 'dadosPedidoAtualizado', 'nomesUsuarios', 'enviar']) delete o[k];
