  if (abertos.some(t => !Object.prototype.hasOwnProperty.call(t, 'userId'))) {
    return r(false, 'INDETERMINADO', 'Chamado aberto sem a informação do atendente.');
  }

  const deOutros = abertos.filter(t => !MEUS_USER_IDS.includes(String(t.userId ?? '')));
  if (!deOutros.length) return r(true, 'CHAMADO_MEU', 'Chamado aberto já está comigo.', { chamadoId: String(abertos[0].id ?? '') });

  const comAtendente = deOutros.find(t => t.userId);
  if (comAtendente) {
    return r(false, 'OCUPADO', `Chamado aberto com ${nomeDe(comAtendente.userId)}.`, {
      chamadoId: String(comAtendente.id ?? ''),
      chamadoUserId: String(comAtendente.userId),
      chamadoAtendente: nomeDe(comAtendente.userId),
      chamadoDepartamentoId: String(comAtendente.departmentId ?? '')
    });
  }
  if (BLOQUEAR_FILA_SEM_ATENDENTE) {
    return r(false, 'FILA_SEM_ATENDENTE', 'Chamado aberto na fila, ainda sem atendente.', {
      chamadoId: String(deOutros[0].id ?? ''),
      chamadoDepartamentoId: String(deOutros[0].departmentId ?? '')
    });
  }
  return r(true, 'FILA_LIBERADA', 'Chamado na fila sem atendente (liberado pela configuração).', { chamadoId: String(deOutros[0].id ?? '') });
}

function mapaNomes(itensUsuarios) {
  const nomes = {};
  (function coletar(v) {
    if (!v) return;
    if (Array.isArray(v)) { v.forEach(coletar); return; }
    if (typeof v !== 'object') return;
    const id = v.id ?? v.userId;
    const name = v.name ?? v.nome;
    if (id && name) nomes[String(id)] = String(name);
    for (const k of ['data', 'users', 'items', 'results', 'rows']) if (v[k] && typeof v[k] === 'object') coletar(v[k]);
  })((itensUsuarios || []).map(i => (i && i.json !== undefined ? i.json : i)));
  return nomes;
}

function semCamposChamado(obj) {
  const o = { ...obj };
  for (const k of ['chamadoLivre', 'chamadoSituacao', 'chamadoMotivo', 'chamadoVerificadoEm', 'chamadoId', 'chamadoUserId',
    'chamadoAtendente', 'chamadoDepartamentoId', 'rowId', 'dadosPedidoAtualizado', 'nomesUsuarios', 'enviar']) delete o[k];
  return o;
}

// Leva o nome dos atendentes junto com cada pedido (para mostrar no front com quem está o chamado).
const nomes = mapaNomes($input.all());
return $('Preparar retomada do envio').all().map(i => ({ json: { ...i.json, nomesUsuarios: nomes } }));

// ===== CONFIGURAÇÃO DA CHECAGEM DE CHAMADO =====
// Usuário(s) DigiSac considerados "eu" (mesmo usuário que recebe a transferência do chamado).
const MEUS_USER_IDS = ['f4a00c56-b35b-4c7c-a5d5-9f963757ba93'];
// true = chamado aberto na fila, ainda sem atendente, também bloqueia o envio (mais seguro).
const BLOQUEAR_FILA_SEM_ATENDENTE = true;

// Regra: só libera o envio quando NÃO existe chamado aberto, ou quando o chamado aberto já é meu.
// Qualquer dúvida (erro na API, resposta estranha) = NÃO envia; o pedido fica no loop de 30 min.
function avaliarChamado(contactId, respostaItens, nomesUsuarios) {
  const cid = String(contactId ?? '').trim();
  const nomes = nomesUsuarios || {};
  const nomeDe = id => nomes[String(id)] || String(id);
  const r = (livre, situacao, motivo, extra = {}) => ({
    chamadoLivre: livre,
    chamadoSituacao: situacao,
    chamadoMotivo: motivo,
    chamadoVerificadoEm: new Date().toISOString(),
    ...extra
  });

  if (!cid) return r(false, 'INDETERMINADO', 'Sem contactId para consultar o chamado.');

  const itens = (respostaItens || []).map(i => (i && i.json !== undefined ? i.json : i)).filter(Boolean);
  if (!itens.length) return r(false, 'INDETERMINADO', 'Consulta de chamados sem resposta.');
  const comErro = itens.find(j => j.error);
  if (comErro) {
    const msg = typeof comErro.error === 'string' ? comErro.error : (comErro.error.message || JSON.stringify(comErro.error));
    return r(false, 'INDETERMINADO', 'Erro ao consultar chamados: ' + String(msg).slice(0, 200));
  }

  let lista = null;
  if (itens.length === 1 && Array.isArray(itens[0].data)) lista = itens[0].data;
  else if (itens.every(j => Object.prototype.hasOwnProperty.call(j, 'isOpen'))) lista = itens;
  if (!Array.isArray(lista)) return r(false, 'INDETERMINADO', 'Resposta inesperada da consulta de chamados.');

  // Se vier chamado de outro contato, o filtro não foi aplicado: não dá para confiar no resultado.
  if (lista.some(t => t && t.contactId && String(t.contactId) !== cid)) {
    return r(false, 'INDETERMINADO', 'A API não filtrou por contato; envio bloqueado por segurança.');
  }

  const abertos = lista.filter(t => t && (t.isOpen === true || t.isOpen === 'true' || t.isOpen === 1));
  if (!abertos.length) return r(true, 'SEM_CHAMADO', 'Nenhum chamado aberto para o contato.');
  if (abertos.some(t => !Object.prototype.hasOwnProperty.call(t, 'userId'))) {
    return r(false, 'INDETERMINADO', 'Chamado aberto sem a informação do atendente.');
  }

  const deOutros = abertos.filter(t => !MEUS_USER_IDS.includes(String(t.userId ?? '')));
  if (!deOutros.length) return r(true, 'CHAMADO_MEU', 'Chamado aberto já está comigo.', { chamadoId: String(abertos[0].id ?? '') });

  const comAtendente = deOutros.find(t => t.userId);
  if (comAtendente) {
    return r(false, 'OCUPADO', `Chamado aberto com ${nomeDe(comAtendente.userId)}.`, {
      chamadoId: String(comAtendente.id ?? ''),
      chamadoUserId: String(comAtendente.userId),
      chamadoAtendente: nomeDe(comAtendente.userId),
      chamadoDepartamentoId: String(comAtendente.departmentId ?? '')
    });
  }
  if (BLOQUEAR_FILA_SEM_ATENDENTE) {
    return r(false, 'FILA_SEM_ATENDENTE', 'Chamado aberto na fila, ainda sem atendente.', {
      chamadoId: String(deOutros[0].id ?? ''),
      chamadoDepartamentoId: String(deOutros[0].departmentId ?? '')
    });
  }
  return r(true, 'FILA_LIBERADA', 'Chamado na fila sem atendente (liberado pela configuração).', { chamadoId: String(deOutros[0].id ?? '') });
}

function mapaNomes(itensUsuarios) {
  const nomes = {};
  (function coletar(v) {
    if (!v) return;
    if (Array.isArray(v)) { v.forEach(coletar); return; }
    if (typeof v !== 'object') return;
    const id = v.id ?? v.userId;
    const name = v.name ?? v.nome;
    if (id && name) nomes[String(id)] = String(name);
    for (const k of ['data', 'users', 'items', 'results', 'rows']) if (v[k] && typeof v[k] === 'object') coletar(v[k]);
  })((itensUsuarios || []).map(i => (i && i.json !== undefined ? i.json : i)));
  return nomes;
}

function semCamposChamado(obj) {
  const o = { ...obj };
  for (const k of ['chamadoLivre', 'chamadoSituacao', 'chamadoMotivo', 'chamadoVerificadoEm', 'chamadoId', 'chamadoUserId',
    'chamadoAtendente', 'chamadoDepartamentoId', 'rowId', 'dadosPedidoAtualizado', 'nomesUsuarios', 'enviar']) delete o[k];
  return o;
}

// ===== LOOP DE 30 MIN =====
const pedido = $('Timer retomada').first().json;
const av = avaliarChamado(pedido.contactId, $input.all(), pedido.nomesUsuarios || {});
const base = semCamposChamado(pedido);
const esp = pedido.chamadoEspera || {};
const dadosPedidoAtualizado = JSON.stringify({
  ...base,
  chamadoEspera: { ...esp, ...av, desde: esp.desde || av.chamadoVerificadoEm, verificacoes: Number(esp.verificacoes || 0) + 1 }
});
return [{ json: { ...base, ...av, dadosPedidoAtualizado } }];

// ===== RESPOSTA TARDIA (v8) =====
// Pedido que ficou "sem retorno" num dia anterior (o fluxo encerrou o chamado) e o cliente
// mandou mensagem DEPOIS do encerramento. O pedido segue o caminho normal (busca do contato
// e montagem da mensagem), mas no fim cai na tela "Respostas tardias" do front, e não na
// Revisão de envio: o consultor lê a resposta e decide se segue o fluxo normal ou se manda
// uma resposta diferente. O template continua sendo enviado primeiro.
const hoje = $now.setZone('America/Sao_Paulo').toFormat('yyyy-LL-dd');
const normPed = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };
const IGNORAR = ['ESCALADO', 'RESPOSTA_TARDIA_TRATADA'];   // já foi ao consultor / consultor já decidiu
const MAX_RESPOSTAS = 20;
const MAX_CONTEXTO = 6;

const semConf = $('Ler SEM_CONFIRMACAO_DIARIO').all().map(i => i.json)
  .filter(r => r && String(r.pedidoLider ?? '').trim() !== '');

let mensagens = [];
try { mensagens = $('Ler MENSAGENS_CLIENTE (resposta tardia)').all().map(i => i.json); } catch (e) { mensagens = []; }
const tsDe = m => Number(m.ts) || Date.parse(m.recebidoEm) || 0;
const porContato = new Map();
for (const m of mensagens) {
  if (!m || m.error) continue;
  const cid = String(m.contactId ?? '').trim();
  if (!cid || String(m.texto ?? '').trim() === '') continue;
  if (!porContato.has(cid)) porContato.set(cid, []);
  porContato.get(cid).push(m);
}
for (const l of porContato.values()) l.sort((a, b) => tsDe(a) - tsDe(b));

const quando = r => Date.parse(r.registradoEm) || 0;
const fala = m => ({
  papel: String(m.papel ?? '').toUpperCase() === 'CLIENTE' ? 'CLIENTE' : 'LIDER',
  texto: String(m.texto ?? '').trim().slice(0, 2000),
  ts: tsDe(m)
});

return $input.all().map((item, i) => {
  const p = item.json;
  const semTardia = { json: { ...p, respostaTardia: null }, pairedItem: { item: i } };
  if (p.acaoReincidencia === 'JA_ESCALADO') return semTardia;

  // Último encerramento "sem retorno" deste pedido (de um dia anterior)
  const regs = semConf
    .filter(r => normPed(r.pedidoLider) === normPed(p.pedidoLider) && String(r.dataRef ?? '').trim() !== hoje)
    .sort((a, b) => (quando(b) - quando(a)) || String(b.dataRef ?? '').localeCompare(String(a.dataRef ?? '')));
  const ult = regs[0];
  if (!ult || IGNORAR.includes(String(ult.status ?? '').toUpperCase())) return semTardia;

  // v24: se a varredura da manhã já marcou RESPONDEU_DEPOIS, vale tudo o que o cliente mandou desde o início
  // daquele dia (a varredura também recupera mensagens anteriores ao encerramento que o n8n nunca recebeu).
  const corte = String(ult.status ?? '').toUpperCase() === 'RESPONDEU_DEPOIS'
    ? (Date.parse(`${String(ult.dataRef ?? '').trim()}T00:00:00-03:00`) || quando(ult))
    : quando(ult);
  const contactId = String(ult.contactId ?? '').trim();
  if (!corte || !contactId) return semTardia;

  // Mensagens do cliente que chegaram depois do encerramento
  const conversa = porContato.get(contactId) || [];
  const respostas = conversa.filter(m => String(m.papel ?? '').toUpperCase() === 'CLIENTE' && tsDe(m) > corte);
  if (!respostas.length) return semTardia;

  return {
    json: {
      ...p,
      // Cliente respondeu: não é mais "2 dias sem retorno"; o consultor decide na tela de respostas tardias
      acaoReincidencia: p.acaoReincidencia === 'ESCALAR' ? 'NORMAL' : p.acaoReincidencia,
      respostaTardia: {
        pedidoLiderRegistro: String(ult.pedidoLider),
        dataRef: String(ult.dataRef ?? ''),
        encerradoEm: String(ult.registradoEm ?? ''),
        etapa: String(ult.status ?? ''),
        contactId,
        respostas: respostas.slice(-MAX_RESPOSTAS).map(fala),
        contexto: conversa.filter(m => tsDe(m) <= corte).slice(-MAX_CONTEXTO).map(fala),
        detectadoEm: new Date().toISOString(),
        reincidenciaIgnorada: p.acaoReincidencia === 'ESCALAR'
      }
    },
    pairedItem: { item: i }
  };
});

// v12 — UMA MENSAGEM POR CLIENTE
// Se o mesmo cliente (mesmo contato no Digisac) tem 2 ou mais pedidos prontos para confirmar a data
// nesta execução, o fluxo junta tudo numa mensagem só (1 template, 1 mensagem, 1 conversa).
//  - PRINCIPAL = pedido de menor número: leva a mensagem única e a lista pedidosGrupo.
//  - Os demais ficam com agrupadoEm = principal -> status AGRUPADO (acompanham o principal).
//    Planilha, intranet, adiamento e "sem retorno" são gravados em TODOS os pedidos do grupo.
// Não agrupa: bloqueados, 1ª confirmação de planejados (texto e vídeo próprios),
// pedidos com resposta tardia (vão para a tela própria) e pedidos sem itens/datas legíveis.
const AGRUPAVEL = ['UNICA', 'PARCIAL', 'SEGUNDA_CONFIRMACAO'];
const itens = $input.all();
const n = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };
const num = d => Number(String(d).split('/').reverse().join(''));

let tardias = [];
try { tardias = $('Verificar resposta tardia').all().filter(i => i.json.respostaTardia).map(i => n(i.json.pedidoLider)); } catch (e) { tardias = []; }

const entregasOk = j => Array.isArray(j.entregas) && j.entregas.length > 0 && j.entregas.every(e =>
  /^\d{2}\/\d{2}\/\d{4}$/.test(String(e?.data ?? '')) && Array.isArray(e.itens) && e.itens.length > 0 &&
  e.itens.every(it => String(it?.descricao ?? '').trim()));

const chave = j => String(j.contactId ?? '').trim();
const podeAgrupar = j => !j.bloqueado && !!String(j.mensagem ?? '').trim() && !!chave(j) &&
  AGRUPAVEL.includes(String(j.tipoMensagem ?? '')) && !tardias.includes(n(j.pedidoLider)) && entregasOk(j);

// "2", "2,00", "1.000,00" -> número (mesma regra das mensagens individuais)
const parseQtd = q => { const s = String(q ?? '').trim(); const x = s.includes(',') ? Number(s.replace(/\./g, '').replace(',', '.')) : Number(s); return Number.isFinite(x) ? x : 1; };
const linhaItem = it => {
  const nome = String(it.descricao ?? '').split(' - ')[0].replace(/\s+/g, ' ').trim();
  const q = parseQtd(it.quantidade);
  return `• ${q > 1 ? q + 'x ' : ''}${nome}`;
};
const listaTxt = arr => arr.length > 1 ? `${arr.slice(0, -1).join(', ')} e ${arr[arr.length - 1]}` : arr[0];

// agrupa por contato (sem repetir o mesmo pedido)
const grupos = new Map();
itens.forEach((it, idx) => {
  const j = it.json;
  if (!podeAgrupar(j)) return;
  const k = chave(j);
  if (!grupos.has(k)) grupos.set(k, []);
  const g = grupos.get(k);
  if (!g.some(i => n(itens[i].json.pedidoLider) === n(j.pedidoLider))) g.push(idx);
});

const saida = itens.map(it => ({ json: { ...it.json } }));

for (const idxs of grupos.values()) {
  if (idxs.length < 2) continue;
  idxs.sort((a, b) => Number(n(itens[a].json.pedidoLider)) - Number(n(itens[b].json.pedidoLider)));
  const membrosJson = idxs.map(i => itens[i].json);
  const principal = membrosJson[0];

  const membros = membrosJson.map(j => ({
    pedidoLider: String(j.pedidoLider),
    Pedido: j.Pedido ?? null,
    clienteLider: j.clienteLider ?? null,
    'RESPONSÁVEL': j['RESPONSÁVEL'] ?? null,
    tipoMovel: j.tipoMovel ?? null,
    tipoMensagem: j.tipoMensagem,
    entregas: j.entregas.map(e => ({ data: e.data, itens: e.itens.map(x => ({ descricao: x.descricao, quantidade: x.quantidade })) })),
    dataSistema: j.dataSistema ?? null,
    entregaLider: j.entregaLider ?? null
  }));

  const todasDatas = [...new Set(membros.flatMap(m => m.entregas.map(e => e.data)))].sort((a, b) => num(a) - num(b));
  const umaData = todasDatas.length === 1;
  const pedidosFmt = membros.map(m => `*${m.pedidoLider}*`);
  const rotulo = m => `Pedido ${m.pedidoLider}${m.tipoMovel === 'Planejados' ? ' (móveis planejados)' : ''}`;

  const abertura = String(principal.mensagem).split('\n')[0].trim() || 'Olá! Aqui é da *Líder*.';
  const corpo = umaData
    ? [
        `A previsão de entrega dos seus pedidos ${listaTxt(pedidosFmt)} é *${todasDatas[0]}*.`, '',
        membros.map(m => `*Produtos do ${rotulo(m).replace(/^Pedido/, 'pedido')}:*\n${m.entregas.flatMap(e => e.itens).map(linhaItem).join('\n')}`).join('\n\n')
      ]
    : [
        `Seus pedidos ${listaTxt(pedidosFmt)} têm as seguintes previsões de entrega:`, '',
        membros.map(m => `📦 *${rotulo(m)}*\n` + [...m.entregas].sort((a, b) => num(a.data) - num(b.data))
          .map(e => `📅 *${e.data}*\n${e.itens.map(linhaItem).join('\n')}`).join('\n')).join('\n\n')
      ];
  const rodape = umaData
    ? 'Lembrando que se trata de uma data *prevista*. Se houver qualquer impedimento para receber, é só nos avisar por aqui.\n\nPodemos confirmar a data de entrega?'
    : 'Lembrando que se trata de datas *previstas*. Se houver qualquer impedimento para receber, é só nos avisar por aqui.\n\nPodemos confirmar as datas de entrega?';
  const mensagem = [abertura, '', ...corpo, '', rodape].join('\n');

  const pedidosGrupo = membros;
  saida[idxs[0]].json = {
    ...principal,
    mensagemIndividual: principal.mensagem,
    mensagem,
    tipoMensagem: 'AGRUPADA',
    tipoMensagemOriginal: principal.tipoMensagem,
    entregas: todasDatas.map(data => ({ data, itens: membros.flatMap(m => (m.entregas.find(e => e.data === data)?.itens) ?? []) })),
    pedidosGrupo,
    qtdPedidosGrupo: membros.length
  };
  idxs.slice(1).forEach(i => {
    saida[i].json = {
      ...itens[i].json,
      agrupadoEm: String(principal.pedidoLider),
      pedidosGrupoNumeros: membros.map(m => m.pedidoLider)
    };
  });
}

return saida.map((s, i) => ({ json: s.json, pairedItem: { item: i } }));

// v12 — adiamento de mensagem única (vários pedidos do mesmo cliente):
// a nova data é aplicada na intranet em CADA pedido do grupo. Pedido sozinho: segue igual (1 item).
const n = $input.first().json;
const membros = Array.isArray(n.grupoPedidos) && n.grupoPedidos.length > 1 ? n.grupoPedidos : null;
if (!membros) return [{ json: { ...n }, pairedItem: { item: 0 } }];
const numBR = d => Number(String(d).split('/').reverse().join(''));
return membros.map(m => {
  const datas = (m.entregas || []).map(e => e.data).filter(Boolean).sort((a, b) => numBR(a) - numBR(b));
  return { json: { ...n, pedidoPrincipal: n.pedidoLider, pedidoLider: String(m.pedidoLider), dataPrevistaOriginal: datas[0] || n.dataPrevistaOriginal }, pairedItem: { item: 0 } };
});

// v13 — PEDIDO DE OUTLET (retirado direto na loja)
// Página vdp/situacao_pedidos.php (a mesma do nó "Cosultada Data Produto"): se TODOS os itens do pedido têm Quantidade = Estoque,
// o pedido é de outlet. Ele é registrado como confirmado (planilha + intranet) e o cliente NÃO é contatado.
// Linhas sem quantidade (ex.: IPI, quantidade 0) não contam. Na dúvida (página fora do ar,
// pedido não encontrado, número ilegível), o pedido segue o fluxo normal.
const todosMerge = $('Merge1').all();
const pedidoDe = i => { try { const x = $('Merge1').itemMatching(i); if (x && x.json) return x.json; } catch (_) {} return (todosMerge[i] || {}).json || {}; };
const limpar = t => String(t ?? '').replace(/&nbsp;/gi, ' ').replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const semAcento = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
// "1.0" (vdp/situacao_pedidos.php), "Qtd. 1,000" / "1.000,000" (formato brasileiro) -> número
const numero = t => {
  const m = String(t ?? '').match(/-?\d[\d.,]*/);
  if (!m) return null;
  let s = m[0].replace(/[.,]$/, '');
  s = s.includes(',') ? s.replace(/\./g, '').replace(',', '.') : s;   // com vírgula: padrão BR; sem vírgula: ponto é decimal
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};
const nPed = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };

return $input.all().map((resp, i) => {
  const p = pedidoDe(i);
  const html = String(resp.json?.data ?? '');
  const linhas = html.match(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi) || [];

  // acha o cabeçalho e a posição das colunas pelo nome (não depende da ordem)
  let col = null;
  for (const l of linhas) {
    const c = (l.match(/<td\b[^>]*>[\s\S]*?<\/td>/gi) || []).map(x => semAcento(limpar(x)));
    // cabeçalhos aceitos: "Qtde"/"Quantidade" e "Est"/"Estoque"
    const iQtd = c.findIndex(x => x === 'QTDE' || x === 'QUANTIDADE');
    const iEst = c.findIndex(x => x === 'EST' || x === 'ESTOQUE');
    if (c.includes('PEDIDO') && iQtd >= 0 && iEst >= 0) {
      col = { pedido: c.indexOf('PEDIDO'), item: c.findIndex(x => x.startsWith('COD')), qtd: iQtd,
              est: iEst, prazo: c.findIndex(x => x.startsWith('PRAZO')), desc: c.findIndex(x => x.startsWith('DESCRI')) };
      break;
    }
  }

  const alvo = nPed(p.pedidoLider);
  const itens = [];
  if (col && alvo) {
    for (const l of linhas) {
      const c = (l.match(/<td\b[^>]*>[\s\S]*?<\/td>/gi) || []).map(limpar);
      if (c.length <= Math.max(col.pedido, col.qtd, col.est)) continue;
      const ped = c[col.pedido];
      if (!/^\(11\)-/.test(ped) || nPed(ped) !== alvo) continue;   // só a empresa 11 e o próprio pedido
      itens.push({ codigoItem: c[col.item] || '', descricao: c[col.desc] || '', prazo: c[col.prazo] || '', quantidade: numero(c[col.qtd]), estoque: numero(c[col.est]) });
    }
  }
  const itensComQtd = itens.filter(x => x.quantidade !== null && x.quantidade > 0);
  const outlet = itensComQtd.length > 0 && itensComQtd.every(x => x.estoque !== null && Math.abs(x.estoque - x.quantidade) < 1e-9);

  let motivoOutlet = '';
  if (!col) motivoOutlet = /Saldo de pedidos entre os dias/i.test(html) ? 'PAGINA_SEM_COLUNA_ESTOQUE' : 'PAGINA_ESTOQUE_INVALIDA';
  else if (!itensComQtd.length) motivoOutlet = 'PEDIDO_NAO_ENCONTRADO_NA_PAGINA_ESTOQUE';
  else motivoOutlet = outlet ? 'OUTLET: QUANTIDADE = ESTOQUE EM TODOS OS ITENS' : 'NAO_OUTLET';

  // data para o aviso da intranet: prazo dos itens (o mais antigo) ou a data do pedido no sistema
  const toISO = br => { const m = String(br ?? '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/); return m ? `${m[3]}-${m[2]}-${m[1]}` : ''; };
  const prazos = itensComQtd.map(x => x.prazo).filter(x => /^\d{2}\/\d{2}\/\d{4}$/.test(x)).sort((a, b) => a.split('/').reverse().join('').localeCompare(b.split('/').reverse().join('')));
  const dataOutlet = prazos[0] || p.entregaLider || '';

  return { json: { ...p, outlet, motivoOutlet, itensOutlet: itensComQtd, dataOutlet, dataOutletISO: toISO(dataOutlet) }, pairedItem: { item: i } };
});

// v17 — Pedido de outlet é registrado EXATAMENTE como um cliente que confirmou a data pelo WhatsApp (categoria ACEITA):
// AGUARDANDO_ENTREGA = CONCLUIDO / ACEITA; planilha SIM / CONFIRMADO / data e hora; intranet com a mesma observação
// do nó "Montar Observação Contato" (ACEITA). Nenhuma mensagem é enviada. O vínculo "outlet" fica só no dadosPedido (auditoria).
const semAcento = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '');
const toISO = br => { const m = String(br ?? '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/); return m ? `${m[3]}-${m[2]}-${m[1]}` : ''; };
const numBR = d => Number(String(d).split('/').reverse().join(''));
const ts = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(new Date()).replace(',', '');
const agoraISO = new Date().toISOString();
return $input.all().map((it, i) => {
  const p = it.json;
  // datas do pedido (prazo de cada item; parcial pode ter mais de uma), como o "datas" da confirmação normal
  let datas = [...new Set((p.itensOutlet || []).map(x => String(x.prazo || '').trim()).filter(x => /^\d{2}\/\d{2}\/\d{4}$/.test(x)))].sort((a, b) => numBR(a) - numBR(b));
  if (!datas.length && /^\d{2}\/\d{2}\/\d{4}$/.test(String(p.dataOutlet || ''))) datas = [p.dataOutlet];
  if (!datas.length && /^\d{2}\/\d{2}\/\d{4}$/.test(String(p.entregaLider || ''))) datas = [p.entregaLider];
  const datasTxt = datas.join(' E ');
  const datEntrega = toISO(datas[0]) || p.dataOutletISO || '';
  return { json: {
    ...p,
    pedidoSheet: String(p.Pedido ?? p.pedidoOriginal ?? `11-${p.pedidoLider}`).trim(),
    sheetG: 'SIM', sheetH: 'CONFIRMADO', sheetI: ts,
    clienteIntranet: semAcento(p.clienteLider ?? p.Cliente ?? '').trim(),
    datEntrega,
    temDataIntranet: !!datEntrega,
    entregas: datas.map(data => ({ data })),
    observacaoOutlet: semAcento(`CLIENTE CONTATADO VIA WHATSAPP E CONFIRMOU A DATA DE ENTREGA ${datasTxt}.`).toUpperCase(),
    statusFinal: 'CONCLUIDO',
    categoria: 'ACEITA',
    resumoOutlet: 'Cliente confirmou a data de entrega.',
    registradoEm: agoraISO
  }, pairedItem: { item: i } };
});

// v14 — LEMBRETE DE CONFIRMAÇÃO (seg-sex 13:00)
// Cliente aceitou o template (clicou no botão), recebeu a mensagem de confirmação e NÃO respondeu nada.
// Às 13:00 o fluxo manda UM lembrete curto no mesmo chamado. A resposta segue para a IA normalmente
// (o status continua DATA_ENVIADA). O encerramento "sem retorno" da tarde não muda.
const MIN_MINUTOS = 60;   // mensagem de confirmação enviada há menos de 1h: ainda não cobra
const MAX_HORAS = 23;     // janela de 24h do WhatsApp (conta do clique do cliente no template)
// Outro pedido do mesmo contato nestes status: não manda lembrete (evita misturar conversas)
const PROTEGER = ['AGUARDANDO', 'AGUARDANDO_CONSULTOR', 'AGUARDANDO_DECISAO_RESPONSAVEL', 'TRANSFERIDO',
  'TRANSFERENCIA_MANUAL', 'ESCALADO', 'PENDENTE_REVISAO', 'PENDENTE_RESPOSTA_TARDIA', 'AGUARDANDO_CHAMADO_LIVRE', 'EM_PROCESSAMENTO'];

const norm = v => String(v ?? '').trim().toUpperCase();
const num = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };
const lerDp = r => { try { return JSON.parse(r.dadosPedido || '{}') || {}; } catch (_) { return {}; } };
const agora = Date.now();

// Mensagens: se a leitura falhou, não manda lembrete para ninguém (não dá para saber quem respondeu)
const msgsBrutas = $input.all().map(i => i.json);
if (msgsBrutas.some(m => m && m.error)) return [];
const msgs = msgsBrutas.filter(m => m && m.contactId !== undefined && m.contactId !== null);

const linhas = $('Ler AGUARDANDO_ENTREGA (lembrete)').all().map(i => i.json).filter(r => r && r.id !== undefined);

function primeiroNome(r, dp) {
  const m = String(r.mensagem || dp.mensagem || '').match(/^\s*Ol[áa],\s*([^!\n,]{2,30})!/i);
  if (m) return m[1].trim();
  const n = String(r.cliente ?? '').replace(/^[\d\s.\-\/]+-\s*/, '').trim();
  if (!n || /\b(LTDA|S\/A|SA|ME|EIRELI|SISTEMAS|COMERCIO|INDUSTRIA)\b/i.test(n)) return null;
  const x = n.split(/\s+/)[0];
  return x.charAt(0).toUpperCase() + x.slice(1).toLowerCase();
}

function saudacao() {
  let h = 13;
  try { h = Number(new Intl.DateTimeFormat('pt-BR', { hour: 'numeric', hour12: false, timeZone: 'America/Sao_Paulo' }).format(new Date())); } catch (_) {}
  return h < 12 ? 'Bom dia' : (h < 18 ? 'Boa tarde' : 'Boa noite');
}

const listaPedidos = ps => ps.length === 1 ? `*${ps[0]}*` : ps.slice(0, -1).map(p => `*${p}*`).join(', ') + ` e *${ps[ps.length - 1]}*`;

const porContato = new Map();
for (const r of linhas) {
  const cid = String(r.contactId ?? '').trim();
  if (!cid) continue;
  if (!porContato.has(cid)) porContato.set(cid, []);
  porContato.get(cid).push(r);
}

const saida = [];
for (const [contactId, rows] of porContato) {
  if (rows.some(r => PROTEGER.includes(norm(r.status)))) continue;

  const alvo = rows.filter(r => {
    if (norm(r.status) !== 'DATA_ENVIADA') return false;
    if (String(r.categoria ?? '').trim()) return false;          // a IA já tratou alguma resposta do cliente
    const dp = lerDp(r);
    if (dp.lembreteConfirmacaoEm) return false;                  // lembrete já enviado
    const t = new Date(r.respondidoEm).getTime();                // hora em que a mensagem de confirmação saiu
    if (isNaN(t)) return false;
    const idadeMin = (agora - t) / 60000;
    return idadeMin >= MIN_MINUTOS && idadeMin <= MAX_HORAS * 60;
  });
  if (!alvo.length) continue;
  // Algum pedido do contato com a confirmação já respondida/em conversa: não cobra
  if (rows.some(r => norm(r.status) === 'DATA_ENVIADA' && !alvo.includes(r))) continue;

  const desde = Math.min(...alvo.map(r => new Date(r.respondidoEm).getTime()));
  const respondeu = msgs.some(m => String(m.contactId).trim() === contactId && String(m.papel ?? '').toUpperCase() === 'CLIENTE' && Number(m.ts) > desde);
  if (respondeu) continue;

  // Pedidos citados: os da linha + os do grupo (mensagem única, v12)
  const pedidos = [];
  const add = p => { const x = num(p); if (x && !pedidos.includes(x)) pedidos.push(x); };
  for (const r of alvo) {
    add(r.pedidoLider);
    const dp = lerDp(r);
    (Array.isArray(dp.pedidosGrupo) ? dp.pedidosGrupo : []).forEach(g => add(g && typeof g === 'object' ? g.pedidoLider : g));
    rows.filter(x => norm(x.status) === 'AGRUPADO' && num(lerDp(x).agrupadoEm) === num(r.pedidoLider)).forEach(x => add(x.pedidoLider));
  }
  pedidos.sort((a, b) => Number(a) - Number(b));

  const tipos = alvo.map(r => String(r.tipoMensagem || lerDp(r).tipoMensagem || '').toUpperCase());
  const soPrimeira = tipos.length && tipos.every(t => t === 'PRIMEIRA_CONFIRMACAO');
  const nome = primeiroNome(alvo[0], lerDp(alvo[0]));
  const plural = pedidos.length > 1;
  const ped = `${plural ? 'dos pedidos' : 'do pedido'} nº ${listaPedidos(pedidos)}`;
  const pergunta = soPrimeira
    ? `Pode nos confirmar o recebimento da mensagem sobre ${plural ? 'os seus pedidos' : 'o seu pedido'} nº ${listaPedidos(pedidos)}?`
    : `Podemos confirmar a data de entrega ${ped}?`;
  const mensagem = `${saudacao()}${nome ? `, ${nome}` : ''}!\n\n${pergunta}`;

  saida.push({ json: {
    contactId,
    rowIds: alvo.map(r => r.id),
    respondidoEmOriginal: alvo.map(r => String(r.respondidoEm)),
    pedidos,
    cliente: String(alvo[0].cliente ?? ''),
    tipoLembrete: soPrimeira ? 'PRIMEIRA_CONFIRMACAO' : 'DATA',
    mensagem
  } });
}
return saida;

// ===== CONFIGURAÇÃO DA CHECAGEM DE CHAMADO =====
// Usuário(s) DigiSac considerados "eu" (mesmo usuário que recebe a transferência do chamado).
const MEUS_USER_IDS = ['f4a00c56-b35b-4c7c-a5d5-9f963757ba93'];
// true = chamado aberto na fila, ainda sem atendente, também bloqueia o envio (mais seguro).
const BLOQUEAR_FILA_SEM_ATENDENTE = true;

// Regra: só libera o envio quando NÃO existe chamado aberto, ou quando o chamado aberto já é meu.
// Qualquer dúvida (erro na API, resposta estranha) = NÃO envia; o pedido fica no loop de 30 min.
function avaliarChamado(contactId, respostaItens, nomesUsuarios) {
  const cid = String(contactId ?? '').trim();
  const nomes = nomesUsuarios || {};
  const nomeDe = id => nomes[String(id)] || String(id);
  const r = (livre, situacao, motivo, extra = {}) => ({
    chamadoLivre: livre,
    chamadoSituacao: situacao,
    chamadoMotivo: motivo,
    chamadoVerificadoEm: new Date().toISOString(),
    ...extra
  });

  if (!cid) return r(false, 'INDETERMINADO', 'Sem contactId para consultar o chamado.');

  const itens = (respostaItens || []).map(i => (i && i.json !== undefined ? i.json : i)).filter(Boolean);
  if (!itens.length) return r(false, 'INDETERMINADO', 'Consulta de chamados sem resposta.');
  const comErro = itens.find(j => j.error);
  if (comErro) {
    const msg = typeof comErro.error === 'string' ? comErro.error : (comErro.error.message || JSON.stringify(comErro.error));
    return r(false, 'INDETERMINADO', 'Erro ao consultar chamados: ' + String(msg).slice(0, 200));
  }

  let lista = null;
  if (itens.length === 1 && Array.isArray(itens[0].data)) lista = itens[0].data;
  else if (itens.every(j => Object.prototype.hasOwnProperty.call(j, 'isOpen'))) lista = itens;
  if (!Array.isArray(lista)) return r(false, 'INDETERMINADO', 'Resposta inesperada da consulta de chamados.');

  // Se vier chamado de outro contato, o filtro não foi aplicado: não dá para confiar no resultado.
  if (lista.some(t => t && t.contactId && String(t.contactId) !== cid)) {
    return r(false, 'INDETERMINADO', 'A API não filtrou por contato; envio bloqueado por segurança.');
  }

  const abertos = lista.filter(t => t && (t.isOpen === true || t.isOpen === 'true' || t.isOpen === 1));
  if (!abertos.length) return r(true, 'SEM_CHAMADO', 'Nenhum chamado aberto para o contato.');
  if (abertos.some(t => !Object.prototype.hasOwnProperty.call(t, 'userId'))) {
    return r(false, 'INDETERMINADO', 'Chamado aberto sem a informação do atendente.');
  }

  const deOutros = abertos.filter(t => !MEUS_USER_IDS.includes(String(t.userId ?? '')));
  if (!deOutros.length) return r(true, 'CHAMADO_MEU', 'Chamado aberto já está comigo.', { chamadoId: String(abertos[0].id ?? '') });

  const comAtendente = deOutros.find(t => t.userId);
  if (comAtendente) {
    return r(false, 'OCUPADO', `Chamado aberto com ${nomeDe(comAtendente.userId)}.`, {
      chamadoId: String(comAtendente.id ?? ''),
      chamadoUserId: String(comAtendente.userId),
      chamadoAtendente: nomeDe(comAtendente.userId),
      chamadoDepartamentoId: String(comAtendente.departmentId ?? '')
    });
  }
  if (BLOQUEAR_FILA_SEM_ATENDENTE) {
    return r(false, 'FILA_SEM_ATENDENTE', 'Chamado aberto na fila, ainda sem atendente.', {
      chamadoId: String(deOutros[0].id ?? ''),
      chamadoDepartamentoId: String(deOutros[0].departmentId ?? '')
    });
  }
  return r(true, 'FILA_LIBERADA', 'Chamado na fila sem atendente (liberado pela configuração).', { chamadoId: String(deOutros[0].id ?? '') });
}

function mapaNomes(itensUsuarios) {
  const nomes = {};
  (function coletar(v) {
    if (!v) return;
    if (Array.isArray(v)) { v.forEach(coletar); return; }
    if (typeof v !== 'object') return;
    const id = v.id ?? v.userId;
    const name = v.name ?? v.nome;
    if (id && name) nomes[String(id)] = String(name);
    for (const k of ['data', 'users', 'items', 'results', 'rows']) if (v[k] && typeof v[k] === 'object') coletar(v[k]);
  })((itensUsuarios || []).map(i => (i && i.json !== undefined ? i.json : i)));
  return nomes;
}

function semCamposChamado(obj) {
  const o = { ...obj };
  for (const k of ['chamadoLivre', 'chamadoSituacao', 'chamadoMotivo', 'chamadoVerificadoEm', 'chamadoId', 'chamadoUserId',
    'chamadoAtendente', 'chamadoDepartamentoId', 'rowId', 'dadosPedidoAtualizado', 'nomesUsuarios', 'enviar']) delete o[k];
  return o;
}

// ===== LEMBRETE 13:00 =====
const item = $('Timer lembrete').first().json;
const av = avaliarChamado(item.contactId, $input.all(), {});
return [{ json: { ...item, ...av }, pairedItem: { item: 0 } }];

// v14 — Conferência final antes do lembrete: chamado comigo + pedido ainda sem resposta.
const item = $('Avaliar chamado (lembrete)').first().json;
const atuais = $input.all().map(i => i.json).filter(r => r && r.id !== undefined);
const norm = v => String(v ?? '').trim().toUpperCase();
const PROTEGER = ['AGUARDANDO', 'AGUARDANDO_CONSULTOR', 'AGUARDANDO_DECISAO_RESPONSAVEL', 'TRANSFERIDO',
  'TRANSFERENCIA_MANUAL', 'ESCALADO', 'PENDENTE_REVISAO', 'PENDENTE_RESPOSTA_TARDIA', 'AGUARDANDO_CHAMADO_LIVRE', 'EM_PROCESSAMENTO'];
const lerDp = r => { try { return JSON.parse(r.dadosPedido || '{}') || {}; } catch (_) { return {}; } };

let motivo = '';
if ($input.all().some(i => i.json && i.json.error)) motivo = 'Erro ao reconferir o pedido.';
else if (item.chamadoSituacao !== 'CHAMADO_MEU') motivo = `Chamado não está comigo (${item.chamadoSituacao}): ${item.chamadoMotivo || ''}`.trim();
else if (atuais.some(r => String(r.contactId ?? '').trim() === String(item.contactId) && PROTEGER.includes(norm(r.status)))) motivo = 'Outro pedido do contato em atendimento.';
else {
  for (let k = 0; k < (item.rowIds || []).length; k++) {
    const r = atuais.find(x => String(x.id) === String(item.rowIds[k]));
    if (!r) { motivo = 'Pedido não encontrado na reconferência.'; break; }
    if (norm(r.status) !== 'DATA_ENVIADA' || String(r.categoria ?? '').trim()) { motivo = 'Cliente respondeu antes do lembrete.'; break; }
    if (String(r.respondidoEm) !== String((item.respondidoEmOriginal || [])[k])) { motivo = 'Pedido mudou desde a leitura das 13:00.'; break; }
    if (lerDp(r).lembreteConfirmacaoEm) { motivo = 'Lembrete já enviado.'; break; }
  }
}

const enviadoEm = new Date().toISOString();
const linhasMarcar = motivo ? [] : (item.rowIds || []).map(id => {
  const r = atuais.find(x => String(x.id) === String(id));
  const dp = lerDp(r);
  return { id, dadosPedido: JSON.stringify({ ...dp, lembreteConfirmacaoEm: enviadoEm, lembreteConfirmacaoTexto: item.mensagem }) };
});

return [{ json: { ...item, enviar: !motivo, motivoLembrete: motivo || 'OK', linhasMarcar }, pairedItem: { item: 0 } }];

// v14 — Uma linha por pedido para gravar a marca do lembrete no dadosPedido.
const it = $('Pode enviar lembrete?').first().json;
return (it.linhasMarcar || []).map(l => ({ json: l, pairedItem: { item: 0 } }));

// v14 — Grava o lembrete na conversa (papel BOT): a IA vê o lembrete no histórico
// e o agrupamento das mensagens do cliente passa a contar a partir dele.
const it = $('Pode enviar lembrete?').first().json;
const ts = Date.now();
return [{ json: { contactId: it.contactId, messageId: 'lider-lembrete-' + ts, papel: 'BOT', texto: String(it.mensagem).slice(0, 3000), ts }, pairedItem: { item: 0 } }];

// v15 — Grava o resultado do vídeo no dadosPedido (aparece no painel e serve de auditoria).
return $input.all().map((item, i) => {
  const l = item.json;
  let dados = {};
  try { dados = typeof l.dadosPedido === 'string' ? JSON.parse(l.dadosPedido || '{}') : (l.dadosPedido || {}); } catch (e) { dados = {}; }
  dados.videoEnvio = l.videoEnvio;
  return { json: { id: l.id, dadosPedido: JSON.stringify(dados) }, pairedItem: { item: i } };
});

// v18 — RECOMEÇAR PEDIDO: valida o pedido do painel antes de mexer em qualquer coisa.
const body = $('Central - Lider - Recomeçar Pedido').first().json.body ?? {};
const recusar = msg => [{ json: { ok: false, resposta: { ok: false, erro: msg } } }];

const PODE = ['PENDENTE_REVISAO', 'PENDENTE_RESPOSTA_TARDIA', 'AGUARDANDO_CHAMADO_LIVRE', 'AGUARDANDO', 'DATA_ENVIADA',
  'AGUARDANDO_DECISAO_RESPONSAVEL', 'AGUARDANDO_CONSULTOR', 'ESCALADO', 'TRANSFERIDO', 'TRANSFERENCIA_MANUAL',
  'SEM_RETORNO_CLIENTE', 'CANCELADO', 'CONCLUIDO'];
const SO_COM_NUMERO_NOVO = ['PENDENTE_REVISAO', 'PENDENTE_RESPOSTA_TARDIA'];
const SERVICES = ['1211d47b-8ab8-47e8-8055-6b2307a8f466', '6518c8e7-72a4-4796-bb09-2ebd252ef2d6'];

function cpfValido(c) {
  if (!/^\d{11}$/.test(c) || /^(\d)\1{10}$/.test(c)) return false;
  const dv = n => { let s = 0; for (let i = 0; i < n; i++) s += Number(c[i]) * (n + 1 - i); const r = (s * 10) % 11; return r === 10 ? 0 : r; };
  return dv(9) === Number(c[9]) && dv(10) === Number(c[10]);
}
function cnpjValido(c) {
  if (!/^\d{14}$/.test(c) || /^(\d)\1{13}$/.test(c)) return false;
  const dv = n => { const p = n === 12 ? [5,4,3,2,9,8,7,6,5,4,3,2] : [6,5,4,3,2,9,8,7,6,5,4,3,2]; let s = 0; for (let i = 0; i < n; i++) s += Number(c[i]) * p[i]; const r = s % 11; return r < 2 ? 0 : 11 - r; };
  return dv(12) === Number(c[12]) && dv(13) === Number(c[13]);
}
// A intranet grava o documento com 15 dígitos:
//   CNPJ = 0 + 14 dígitos               ex.: 046069303000161 -> 46069303000161
//   CPF  = 9 dígitos + 0000 + 2 dígitos ex.: 114679806000076 -> 11467980676
function normalizarCpf(raw) {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (d.length === 15) {
    const cpf = d.slice(0, 9) + d.slice(13);
    const cnpj = d.startsWith('0') ? d.slice(1) : null;
    if (d.slice(9, 13) === '0000' && cpfValido(cpf)) return cpf;
    if (cnpj && cnpjValido(cnpj)) return cnpj;
    if (cpfValido(cpf)) return cpf;
    return cnpj;
  }
  if (d.length === 10) return d.padStart(11, '0');
  if (d.length === 11 || d.length === 14) return d;
  return null;
}

function chave(raw) {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length >= 12) d = d.slice(2);
  d = d.replace(/^0+/, '');
  return d.length >= 10 ? d.slice(0, 2) + d.slice(-8) : null;
}
function normalizarCelular(raw) {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length >= 12) d = d.slice(2);
  d = d.replace(/^0+/, '');
  if (d.length === 10 && /^[1-9][1-9][6-9]/.test(d)) d = d.slice(0, 2) + '9' + d.slice(2);
  return /^[1-9][1-9]9\d{8}$/.test(d) ? '55' + d : null;
}

const pedido = (String(body.pedidoLider ?? '').match(/\d+/g) || ['']).pop();
const motivo = String(body.motivo ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
const nomeContato = String(body.nomeContato ?? '').replace(/[^\p{L}\p{N} .'-]/gu, '').replace(/\s+/g, ' ').trim().slice(0, 60);
const telInformado = String(body.novoTelefone ?? '').trim();
// v20 — aviso ao contato antigo (ex.: "a partir de agora falamos com a Anete"). Só com número novo.
const avisoContatoAntigo = String(body.avisoContatoAntigo ?? '').replace(/\r\n/g, '\n').trim().slice(0, 1000);

if (!pedido) return recusar('Informe o número do pedido.');
if (motivo.length < 5) return recusar('Escreva o motivo do recomeço (mínimo 5 letras). Ele fica registrado no pedido.');

const linhas = $input.all().map(i => i.json).filter(r => r && !r.error && r.pedidoLider !== undefined && r.pedidoLider !== null && String(r.pedidoLider) !== '');
if (!linhas.length) return recusar(`Pedido 11-${pedido} não encontrado na AGUARDANDO_ENTREGA (a tabela guarda só os pedidos do dia).`);
if (linhas.length > 1) return recusar(`O pedido 11-${pedido} aparece ${linhas.length} vezes na AGUARDANDO_ENTREGA. Nada foi alterado; corrija a tabela antes.`);
const linha = linhas[0];
const status = String(linha.status ?? '');

let dados;
try { dados = typeof linha.dadosPedido === 'string' ? JSON.parse(linha.dadosPedido) : (linha.dadosPedido || {}); }
catch (e) { return recusar(`dadosPedido inválido no pedido 11-${pedido}. Nada foi alterado.`); }

if (status === 'AGRUPADO' || dados.agrupadoEm) return recusar(`O pedido 11-${pedido} foi na mensagem única do pedido 11-${dados.agrupadoEm || '?'}. Recomece pelo pedido 11-${dados.agrupadoEm || '?'}.`);
if (status === 'OUTLET' || dados.outlet === true) return recusar(`O pedido 11-${pedido} é outlet (confirmado sem contato). Não há conversa para recomeçar.`);
if (!PODE.includes(status)) return recusar(`O pedido 11-${pedido} está com status ${status || '(vazio)'}, que não permite recomeço. Só pedidos que já têm mensagem pronta podem recomeçar.`);
if (status === 'CONCLUIDO' && body.confirmarConcluido !== true) return recusar(`O pedido 11-${pedido} já está CONCLUIDO. Para recomeçar, marque a confirmação: o que já foi gravado na intranet e na planilha NÃO é desfeito.`);
if (!String(dados.mensagem ?? '').trim()) return recusar(`O pedido 11-${pedido} não tem mensagem de confirmação montada. Nada foi alterado.`);

const phoneAtual = linha.phone || dados.phone || null;
const contactIdAtual = linha.contactId || dados.contactId || null;
const serviceIdAtual = linha.serviceId || dados.serviceId || null;

let novoPhone = null;
if (telInformado) {
  novoPhone = normalizarCelular(telInformado);
  if (!novoPhone) return recusar(`O número "${telInformado}" não é um celular válido (DDD + 9 dígitos). Nada foi alterado.`);
}
const modo = novoPhone && chave(novoPhone) !== chave(phoneAtual) ? 'NOVO_NUMERO' : 'MESMO_NUMERO';

if (modo === 'MESMO_NUMERO' && avisoContatoAntigo) return recusar('O aviso ao contato atual só vale quando o número muda. Informe o número novo ou apague o aviso.');
if (avisoContatoAntigo && !contactIdAtual) return recusar(`O pedido 11-${pedido} não tem contato atual no Digisac para receber o aviso. Apague o aviso para seguir.`);
if (modo === 'MESMO_NUMERO') {
  if (SO_COM_NUMERO_NOVO.includes(status)) return recusar(`O pedido 11-${pedido} ainda não foi enviado (${status}). Recomeçar sem trocar o número não muda nada: use a tela de Revisão${status === 'PENDENTE_RESPOSTA_TARDIA' ? ' / Respostas tardias' : ''}.`);
  if (!contactIdAtual) return recusar(`O pedido 11-${pedido} não tem contato no Digisac. Informe o número para recomeçar.`);
}

const tentativas = [];
if (modo === 'NOVO_NUMERO') {
  const ult8 = novoPhone.replace(/\D/g, '').slice(-8);
  for (const serviceId of SERVICES) tentativas.push({ phoneBusca: `%${ult8}`, serviceBusca: serviceId, chaveBusca: chave(novoPhone) });
}

const cliente = linha.cliente || dados.clienteLider || '';
// v20 — padrão do nome no Digisac: "02791934677 - RAFI GREEN-(Anete)" (CPF/CNPJ - CLIENTE-(quem atende))
// Pedidos gravados antes da v20 podem ter o CPF como "CNPJ" de 14 dígitos (ex.: 98182996000012): refaz pela regra nova.
const docBruto = String(dados.cpf ?? '').replace(/\D/g, '');
const doc = (docBruto.length === 14 ? normalizarCpf('0' + docBruto) : normalizarCpf(docBruto)) || docBruto;
const base = [doc, String(cliente).trim()].filter(Boolean).join(' - ') || `Contato pedido 11-${pedido}`;
const internalName = (nomeContato ? `${base}-(${nomeContato})` : base).slice(0, 120);


return [{ json: {
  ok: true,
  modo,
  pedidoLider: String(linha.pedidoLider),
  idLinha: linha.id,
  statusAnterior: status,
  linha,
  dados,
  motivo,
  nomeContato,
  novoPhone,
  chaveNovo: novoPhone ? chave(novoPhone) : null,
  phoneAtual, contactIdAtual, serviceIdAtual,
  tentativas,
  internalName,
  avisoContatoAntigo,
  serviceCriacao: '6518c8e7-72a4-4796-bb09-2ebd252ef2d6'
} }];

// v18 — uma busca por canal do Digisac (mesma regra da "Preparar Tentativas Digisac": últimos 8 dígitos).
const v = $json;
return v.tentativas.map(t => ({ json: t }));

// v18 — junta as buscas nos 2 canais. Se QUALQUER busca falhar, não cria contato (evita duplicar) e não altera nada.
const v = $('Validar recomeço').first().json;
const res = $input.all().map(i => i.json);
const SERVICES = ['1211d47b-8ab8-47e8-8055-6b2307a8f466', '6518c8e7-72a4-4796-bb09-2ebd252ef2d6'];

function chave(raw) {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length >= 12) d = d.slice(2);
  d = d.replace(/^0+/, '');
  return d.length >= 10 ? d.slice(0, 2) + d.slice(-8) : null;
}
function normalizarCelular(raw) {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length >= 12) d = d.slice(2);
  d = d.replace(/^0+/, '');
  if (d.length === 10 && /^[1-9][1-9][6-9]/.test(d)) d = d.slice(0, 2) + '9' + d.slice(2);
  return /^[1-9][1-9]9\d{8}$/.test(d) ? '55' + d : null;
}

if (res.length !== v.tentativas.length || res.some(r => !r || r.error || !Array.isArray(r.data))) {
  return [{ json: { ok: false, acao: 'ERRO', resposta: { ok: false, erro: 'Falha ao pesquisar o número no Digisac. Nada foi alterado; tente de novo em instantes.' } } }];
}

const digNovo = String(v.novoPhone).replace(/\D/g, '');
const candidatos = res.flatMap(r => r.data).filter(c => c && c.id && chave(c?.data?.number) === v.chaveNovo);
candidatos.sort((a, b) => {
  const exA = String(a?.data?.number ?? '').replace(/\D/g, '') === digNovo ? 0 : 1;
  const exB = String(b?.data?.number ?? '').replace(/\D/g, '') === digNovo ? 0 : 1;
  if (exA !== exB) return exA - exB;
  const sa = SERVICES.indexOf(a.serviceId), sb = SERVICES.indexOf(b.serviceId);
  return (sa < 0 ? 99 : sa) - (sb < 0 ? 99 : sb);
});

if (!candidatos.length) return [{ json: { ...v, acao: 'CRIAR' } }];

const c = candidatos[0];
return [{ json: {
  ...v,
  acao: 'USAR',
  ok: true,
  contactIdNovo: c.id,
  serviceIdNovo: c.serviceId || null,
  phoneNovo: normalizarCelular(c?.data?.number) || v.novoPhone,
  statusContato: 'ENCONTRADO',
  nomeDigisac: c.internalName || c.name || null,
  qtdEncontrados: candidatos.length
} }];

// v18 — confere o contato criado no Digisac.
const v = $('Avaliar busca (recomeço)').first().json;
const criado = $json;
if (!criado || criado.error || !criado.id) {
  return [{ json: { ok: false, resposta: { ok: false, erro: 'Não foi possível salvar o número no Digisac. Nada foi alterado no pedido. Detalhe: ' + JSON.stringify(criado?.error ?? criado ?? null).slice(0, 300) } } }];
}
return [{ json: {
  ...v,
  ok: true,
  contactIdNovo: criado.id,
  serviceIdNovo: criado.serviceId || v.serviceCriacao,
  phoneNovo: v.novoPhone,
  statusContato: 'CRIADO',
  nomeDigisac: criado.internalName || criado.name || v.internalName
} }];

// v18 — ponto único: daqui para frente o contato do recomeço está definido.
const v = $('Validar recomeço').first().json;
if (v.modo === 'MESMO_NUMERO') {
  return [{ json: { ...v, contactIdNovo: v.contactIdAtual, serviceIdNovo: v.serviceIdAtual, phoneNovo: v.phoneAtual, statusContato: 'MESMO_CONTATO' } }];
}
const c = $json;
if (!c.ok || !c.contactIdNovo) return [{ json: { ok: false, resposta: { ok: false, erro: 'Contato do Digisac não definido. Nada foi alterado.' } } }];
return [{ json: c }];

// v18 — monta o recomeço: zera a conversa do pedido e devolve para a Revisão de Envio com o contato definido.
const v = $('Contato definido (recomeço)').first().json;
const outros = $input.all().map(i => i.json);
const recusar = msg => [{ json: { ok: false, resposta: { ok: false, erro: msg } } }];

if (!v || !v.ok || !v.contactIdNovo) return recusar('Contato do Digisac não definido. Nada foi alterado.');
if (outros.some(o => o && o.error)) return recusar('Falha ao conferir outros pedidos deste contato. Nada foi alterado; tente de novo.');

// Não deixa o mesmo número ficar com 2 conversas da IA ao mesmo tempo
const grupo = new Set([String(v.pedidoLider), ...((Array.isArray(v.dados.pedidosGrupo) ? v.dados.pedidosGrupo : []).map(g => String(g.pedidoLider)))]);
const ATIVOS = ['AGUARDANDO', 'DATA_ENVIADA', 'AGUARDANDO_DECISAO_RESPONSAVEL', 'AGUARDANDO_CONSULTOR', 'AGUARDANDO_CHAMADO_LIVRE', 'EM_PROCESSAMENTO'];
const conflito = outros.filter(o => o && o.pedidoLider !== undefined && o.pedidoLider !== null && !grupo.has(String(o.pedidoLider)) &&
  (ATIVOS.includes(o.status) || (o.status === 'CONCLUIDO' && o.vigiaAte && Date.parse(o.vigiaAte) > Date.now())));
if (conflito.length) {
  return recusar(`Este número já está em atendimento no pedido ${conflito.map(o => '11-' + o.pedidoLider + ' (' + o.status + ')').join(', ')}. Nada foi alterado. Termine aquele atendimento antes, para a IA não misturar os pedidos.`);
}

const agora = new Date();
const agoraIso = agora.toISOString();
const ts = agora.getTime();
const l = v.linha;
const d = { ...v.dados };

const registro = {
  em: agoraIso,
  modo: v.modo,
  motivo: v.motivo,
  statusAnterior: v.statusAnterior,
  categoriaAnterior: l.categoria || null,
  resumoIAAnterior: l.resumoIA || null,
  respostaAnterior: l.resposta || null,
  enviadoEmAnterior: l.enviadoEm || null,
  respondidoEmAnterior: l.respondidoEm || null,
  chatConsultorAnterior: l.chatConsultor || null,
  contactIdAnterior: v.contactIdAtual,
  phoneAnterior: v.phoneAtual,
  contactIdNovo: v.contactIdNovo,
  phoneNovo: v.phoneNovo,
  statusContato: v.statusContato,
  nomeContato: v.nomeContato || null,
  nomeDigisac: v.nomeDigisac || null
};
d.recomecos = [...(Array.isArray(d.recomecos) ? d.recomecos : []), registro];

d.contactId = v.contactIdNovo;
d.serviceId = v.serviceIdNovo;
d.phone = v.phoneNovo;
if (v.modo === 'NOVO_NUMERO') {
  d.statusBusca = v.statusContato;   // ENCONTRADO / CRIADO
  d.contatoAlternativo = { nome: v.nomeContato || null, phone: v.phoneNovo, definidoEm: agoraIso };
}

// Saudação para a pessoa que vai receber (ex.: "Olá, Rafi!" -> "Olá, Anete!")
if (v.nomeContato) {
  const primeiro = v.nomeContato.split(' ')[0];
  const nome = primeiro.charAt(0).toUpperCase() + primeiro.slice(1).toLowerCase();
  const m = String(d.mensagem);
  const nova = m.replace(/^Olá(, [^!\n]{1,60})?!/, `Olá, ${nome}!`);
  if (nova !== m) { d.mensagemAntesRecomeco = d.mensagemAntesRecomeco ?? m; d.mensagem = nova; }
}

// Estado da conversa anterior sai (fica guardado em recomecos)
for (const k of ['respostaTardia', 'respostaTardiaDecisao', 'lembreteConfirmacaoEm', 'lembreteConfirmacaoTexto', 'chamadoEspera', 'videoEnvio']) delete d[k];

const acompanhantes = [...grupo].filter(p => p !== String(v.pedidoLider));
const quem = v.nomeContato ? `${v.nomeContato} ` : '';

return [{ json: {
  ok: true,
  pedidoLider: String(v.pedidoLider),
  statusAnterior: v.statusAnterior,
  modo: v.modo,
  contactId: v.contactIdNovo,
  serviceId: v.serviceIdNovo,
  phone: v.phoneNovo,
  dadosPedido: JSON.stringify(d),
  marcaEm: agoraIso,
  acompanhantes,
  avisoAntigo: (v.modo === 'NOVO_NUMERO' && v.avisoContatoAntigo && v.contactIdAtual && String(v.contactIdAtual) !== String(v.contactIdNovo))
    ? { contactId: v.contactIdAtual, texto: v.avisoContatoAntigo } : null,
  conversa: {
    contactId: v.contactIdNovo,
    messageId: `recomeco-${v.pedidoLider}-${ts}`,
    papel: 'RECOMECO',
    texto: `[Atendimento do pedido 11-${v.pedidoLider} recomeçado pelo consultor. Motivo: ${v.motivo}]`,
    ts
  },
  resposta: {
    ok: true,
    pedidoLider: String(v.pedidoLider),
    modo: v.modo,
    statusContato: v.statusContato,
    phone: v.phoneNovo,
    contactId: v.contactIdNovo,
    mensagem: (v.modo === 'NOVO_NUMERO'
      ? `Pedido 11-${v.pedidoLider} recomeçado com o número ${quem}(${v.phoneNovo}). Contato ${v.statusContato === 'CRIADO' ? 'criado' : 'encontrado'} no Digisac.`
      : `Pedido 11-${v.pedidoLider} recomeçado com o mesmo número.`) +
      ' Ele voltou para a Revisão de Envio: confira a mensagem e clique em Enviar.' +
      (acompanhantes.length ? ` Os pedidos ${acompanhantes.map(p => '11-' + p).join(', ')} da mensagem única acompanham.` : '') +
      (v.statusAnterior === 'CONCLUIDO' ? ' Atenção: o que já foi gravado na intranet e na planilha não foi desfeito.' : '')
  }
} }];

// v18 — relê o pedido e confirma que o recomeço foi gravado (status, contato e marca do recomeço).
const m = $('Montar recomeço').first().json;
const linhas = $input.all().map(i => i.json).filter(r => r && !r.error && String(r.pedidoLider ?? '') === m.pedidoLider);
const ok = linhas.length === 1 && linhas[0].status === 'PENDENTE_REVISAO' && String(linhas[0].contactId) === String(m.contactId) &&
  String(linhas[0].dadosPedido ?? '').includes(m.marcaEm);
if (!ok) {
  return [{ json: { ok: false, resposta: { ok: false, erro: `Não consegui confirmar a gravação do pedido 11-${m.pedidoLider}. O status pode ter mudado durante o recomeço (ex.: o cliente respondeu agora). Atualize o painel e confira o pedido antes de tentar de novo.` } } }];
}
return [{ json: { ...m, ok: true } }];

// v18 — pedidos da mensagem única acompanham o principal: só o contato muda (o status continua AGRUPADO).
const m = $('Conferir gravação (recomeço)').first().json;
return (m.acompanhantes || []).map(p => ({ json: { pedidoLider: p, contactId: m.contactId, serviceId: m.serviceId, phone: m.phone } }));

// v18 — resposta única ao painel (sucesso ou motivo da recusa).
let r = $json && $json.resposta;
if (!r) { try { r = $('Conferir gravação (recomeço)').first().json.resposta; } catch (e) { r = null; } }
if (!r) r = { ok: false, erro: 'Resposta não montada.' };
if (r.ok) {
  let aviso = null;
  try {
    const conv = $('Marcar recomeço na conversa').first().json;
    if (!conv || conv.error) aviso = 'O pedido foi recomeçado, mas a marca de recomeço não foi gravada na MENSAGENS_CLIENTE: a IA ainda pode ver a conversa anterior deste número.';
  } catch (e) { /* nó não executou */ }
  if (aviso) r = { ...r, aviso };
  // v20 — aviso ao contato antigo
  try {
    const a = $('Resultado do aviso (recomeço)').first().json;
    if (a.enviado) r = { ...r, mensagem: r.mensagem + ' Aviso enviado ao contato anterior.' };
    else r = { ...r, aviso: [r.aviso, 'O pedido foi recomeçado, mas o aviso ao contato anterior NÃO foi enviado (' + (a.motivo || 'erro no Digisac') + '). Avise o cliente pelo Digisac.'].filter(Boolean).join(' ') };
  } catch (e) { /* sem aviso pedido */ }
}
return [{ json: r }];

// v20 — confere o envio do aviso ao contato anterior e prepara o registro na conversa dele (papel BOT).
const m = $('Montar recomeço').first().json;
const r = $json || {};
const enviado = !!(r && !r.error && (r.id || r.messageId));
return [{ json: {
  enviado,
  motivo: enviado ? null : String((r && (r.error?.message || r.error || r.message)) || 'resposta sem id').slice(0, 200),
  contactId: m.avisoAntigo.contactId,
  messageId: 'recomeco-aviso-' + (r.id || Date.now()),
  papel: 'BOT',
  texto: m.avisoAntigo.texto,
  ts: Date.now()
} }];

// v21 — ANTI-REPETIÇÃO (saída). Relê a conversa do contato logo antes de enviar e NÃO envia quando:
//  (1) a última resposta da Líder a este contato (últimas 24 h) tem o mesmo texto -> MENSAGEM_REPETIDA;
//  (2) a Líder já respondeu desde a última mensagem do cliente (últimos 30 min) -> RESPOSTAS_DEMAIS.
//      Cada mensagem (ou rajada de mensagens) do cliente recebe no máximo 1 resposta automática.
// Se a leitura da conversa falhar, envia normalmente (a trava da entrada continua valendo).
// Mensagens antes da marca de recomeço (RECOMECO) não contam.
const ORIGEM = 'resposta fixa';
const NO_ENVIO = 'Anti-repetição (resposta fixa)';
const JANELA_REPETIDA_MS = 24 * 60 * 60 * 1000;
const JANELA_RESPOSTAS_MS = 30 * 60 * 1000;
const MAX_RESPOSTAS_POR_MENSAGEM = 1;

const originais = $(NO_ENVIO).all();
const agora = Date.now();
const norm = t => String(t ?? '').replace(/[*_~]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
const tentar = f => { try { return f(); } catch (e) { return ''; } };

// Mesmo texto que o "Preparar registro da resposta" grava como fala da Líder
function textoDoEnvio(j) {
  if (ORIGEM === 'resposta fixa') return j.respostaFixa;
  if (ORIGEM === 'resposta da base') return j.respostaBase;
  if (ORIGEM === 'mensagem programada') return j.mensagem;
  if (ORIGEM === 'adiamento') {
    const dt = tentar(() => $('Normalizar Categoria').first().json.dataSolicitada);
    return j.alteracaoDataConcluida ? `Conseguimos atualizar a previsão de entrega para ${dt}.`
      : `Recebi o pedido para adiar para ${dt}, mas não consegui registrar no sistema. Ofereci encaminhar ao responsável.`;
  }
  return '';
}

// Linhas da MENSAGENS_CLIENTE (sem repetir a mesma linha)
const vistas = new Set();
const todas = $input.all().map(i => i.json)
  .filter(r => r && !r.error && r.papel)
  .filter(r => { const k = (r.id ?? '') + '|' + r.messageId + '|' + r.ts + '|' + r.papel; if (vistas.has(k)) return false; vistas.add(k); return true; })
  .sort((a, b) => Number(a.ts) - Number(b.ts));

const saida = [];
const juntos = originais.map(o => norm(textoDoEnvio(o.json))).filter(Boolean).join(' ');
for (let i = 0; i < originais.length; i++) {
  const o = originais[i];
  const contato = String(o.json.contactId ?? '');
  let linhas = todas.filter(r => String(r.contactId ?? '') === contato);
  const marcas = linhas.filter(r => String(r.papel).toUpperCase() === 'RECOMECO');
  const corte = marcas.length ? Number(marcas[marcas.length - 1].ts) : 0;
  linhas = linhas.filter(r => Number(r.ts) > corte);
  const bots = linhas.filter(r => String(r.papel).toUpperCase() === 'BOT');
  const clientes = linhas.filter(r => String(r.papel).toUpperCase() === 'CLIENTE');
  const ultimoBot = bots[bots.length - 1];
  const ultimoCliTs = clientes.length ? Number(clientes[clientes.length - 1].ts) : 0;
  const texto = norm(textoDoEnvio(o.json));

  let motivo = null;
  if (texto && ultimoBot && agora - Number(ultimoBot.ts) < JANELA_REPETIDA_MS) {
    const anterior = norm(ultimoBot.texto);
    if (anterior === texto || (originais.length > 1 && anterior === juntos)) motivo = 'MENSAGEM_REPETIDA';
  }
  if (!motivo) {
    const depois = bots.filter(r => Number(r.ts) > ultimoCliTs && agora - Number(r.ts) < JANELA_RESPOSTAS_MS).length;
    if (depois >= MAX_RESPOSTAS_POR_MENSAGEM) motivo = 'RESPOSTAS_DEMAIS';
  }
  // o mesmo texto 2 vezes no mesmo envio
  if (!motivo && texto && saida.some(s => norm(textoDoEnvio(s.json)) === texto)) motivo = 'MENSAGEM_REPETIDA';

  if (motivo) {
    console.log(`[anti-repetição] envio bloqueado (${ORIGEM}) contato ${contato}: ${motivo}`);
    continue;
  }
  const par = $input.all().findIndex(it => it.pairedItem && Number(it.pairedItem.item ?? it.pairedItem) === i);
  saida.push({ json: o.json, ...(o.binary ? { binary: o.binary } : {}), pairedItem: { item: par >= 0 ? par : 0 } });
}
return saida;

// v21 — ANTI-REPETIÇÃO (saída). Relê a conversa do contato logo antes de enviar e NÃO envia quando:
//  (1) a última resposta da Líder a este contato (últimas 24 h) tem o mesmo texto -> MENSAGEM_REPETIDA;
//  (2) a Líder já respondeu desde a última mensagem do cliente (últimos 30 min) -> RESPOSTAS_DEMAIS.
//      Cada mensagem (ou rajada de mensagens) do cliente recebe no máximo 1 resposta automática.
// Se a leitura da conversa falhar, envia normalmente (a trava da entrada continua valendo).
// Mensagens antes da marca de recomeço (RECOMECO) não contam.
const ORIGEM = 'mensagem programada';
const NO_ENVIO = 'Anti-repetição (mensagem programada)';
const JANELA_REPETIDA_MS = 24 * 60 * 60 * 1000;
const JANELA_RESPOSTAS_MS = 30 * 60 * 1000;
const MAX_RESPOSTAS_POR_MENSAGEM = 1;

const originais = $(NO_ENVIO).all();
const agora = Date.now();
const norm = t => String(t ?? '').replace(/[*_~]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
const tentar = f => { try { return f(); } catch (e) { return ''; } };

// Mesmo texto que o "Preparar registro da resposta" grava como fala da Líder
function textoDoEnvio(j) {
  if (ORIGEM === 'resposta fixa') return j.respostaFixa;
  if (ORIGEM === 'resposta da base') return j.respostaBase;
  if (ORIGEM === 'mensagem programada') return j.mensagem;
  if (ORIGEM === 'adiamento') {
    const dt = tentar(() => $('Normalizar Categoria').first().json.dataSolicitada);
    return j.alteracaoDataConcluida ? `Conseguimos atualizar a previsão de entrega para ${dt}.`
      : `Recebi o pedido para adiar para ${dt}, mas não consegui registrar no sistema. Ofereci encaminhar ao responsável.`;
  }
  return '';
}

// Linhas da MENSAGENS_CLIENTE (sem repetir a mesma linha)
const vistas = new Set();
const todas = $input.all().map(i => i.json)
  .filter(r => r && !r.error && r.papel)
  .filter(r => { const k = (r.id ?? '') + '|' + r.messageId + '|' + r.ts + '|' + r.papel; if (vistas.has(k)) return false; vistas.add(k); return true; })
  .sort((a, b) => Number(a.ts) - Number(b.ts));

const saida = [];
const juntos = originais.map(o => norm(textoDoEnvio(o.json))).filter(Boolean).join(' ');
for (let i = 0; i < originais.length; i++) {
  const o = originais[i];
  const contato = String(o.json.contactId ?? '');
  let linhas = todas.filter(r => String(r.contactId ?? '') === contato);
  const marcas = linhas.filter(r => String(r.papel).toUpperCase() === 'RECOMECO');
  const corte = marcas.length ? Number(marcas[marcas.length - 1].ts) : 0;
  linhas = linhas.filter(r => Number(r.ts) > corte);
  const bots = linhas.filter(r => String(r.papel).toUpperCase() === 'BOT');
  const clientes = linhas.filter(r => String(r.papel).toUpperCase() === 'CLIENTE');
  const ultimoBot = bots[bots.length - 1];
  const ultimoCliTs = clientes.length ? Number(clientes[clientes.length - 1].ts) : 0;
  const texto = norm(textoDoEnvio(o.json));

  let motivo = null;
  if (texto && ultimoBot && agora - Number(ultimoBot.ts) < JANELA_REPETIDA_MS) {
    const anterior = norm(ultimoBot.texto);
    if (anterior === texto || (originais.length > 1 && anterior === juntos)) motivo = 'MENSAGEM_REPETIDA';
  }
  if (!motivo) {
    const depois = bots.filter(r => Number(r.ts) > ultimoCliTs && agora - Number(r.ts) < JANELA_RESPOSTAS_MS).length;
    if (depois >= MAX_RESPOSTAS_POR_MENSAGEM) motivo = 'RESPOSTAS_DEMAIS';
  }
  // o mesmo texto 2 vezes no mesmo envio
  if (!motivo && texto && saida.some(s => norm(textoDoEnvio(s.json)) === texto)) motivo = 'MENSAGEM_REPETIDA';

  if (motivo) {
    console.log(`[anti-repetição] envio bloqueado (${ORIGEM}) contato ${contato}: ${motivo}`);
    continue;
  }
  const par = $input.all().findIndex(it => it.pairedItem && Number(it.pairedItem.item ?? it.pairedItem) === i);
  saida.push({ json: o.json, ...(o.binary ? { binary: o.binary } : {}), pairedItem: { item: par >= 0 ? par : 0 } });
}
return saida;

// v21 — ANTI-REPETIÇÃO (saída). Relê a conversa do contato logo antes de enviar e NÃO envia quando:
