  const corte = marcas.length ? Number(marcas[marcas.length - 1].ts) : 0;
  linhas = linhas.filter(r => Number(r.ts) > corte);
  const bots = linhas.filter(r => String(r.papel).toUpperCase() === 'BOT');
  const clientes = linhas.filter(r => String(r.papel).toUpperCase() === 'CLIENTE');
  const ultimoBot = bots[bots.length - 1];
  const ultimoCliTs = clientes.length ? Number(clientes[clientes.length - 1].ts) : 0;
  const texto = norm(textoDoEnvio(o.json));

  let motivo = null;
  if (texto && ultimoBot && agora - Number(ultimoBot.ts) < JANELA_REPETIDA_MS) {
    const anterior = norm(ultimoBot.texto);
    if (anterior === texto || (originais.length > 1 && anterior === juntos)) motivo = 'MENSAGEM_REPETIDA';
  }
  if (!motivo) {
    const depois = bots.filter(r => Number(r.ts) > ultimoCliTs && agora - Number(r.ts) < JANELA_RESPOSTAS_MS).length;
    if (depois >= MAX_RESPOSTAS_POR_MENSAGEM) motivo = 'RESPOSTAS_DEMAIS';
  }
  // o mesmo texto 2 vezes no mesmo envio
  if (!motivo && texto && saida.some(s => norm(textoDoEnvio(s.json)) === texto)) motivo = 'MENSAGEM_REPETIDA';

  if (motivo) {
    console.log(`[anti-repetição] envio bloqueado (${ORIGEM}) contato ${contato}: ${motivo}`);
    continue;
  }
  const par = $input.all().findIndex(it => it.pairedItem && Number(it.pairedItem.item ?? it.pairedItem) === i);
  saida.push({ json: o.json, ...(o.binary ? { binary: o.binary } : {}), pairedItem: { item: par >= 0 ? par : 0 } });
}
return saida;

