// v23 — Reconferência ao vivo do chamado, só para pedido que estava em "chamado ocupado".
// Fecha apenas se o chamado aberto estiver na fila sem atendente (ou já comigo).
// Com outro atendente, sem chamado aberto ou qualquer dúvida (erro, resposta estranha) = NÃO fecha.
const MEUS_USER_IDS = ['f4a00c56-b35b-4c7c-a5d5-9f963757ba93'];
const orig = $('Chamado ocupado? (encerramento)').item.json;
const cid = String(orig.contactId ?? '').trim();
const resp = $input.item.json || {};
const body = resp.body !== undefined ? resp.body : resp;

function avaliar() {
  if (!cid) return ['INDETERMINADO', 'Sem contactId.'];
  if (resp.error) return ['INDETERMINADO', 'Erro ao consultar chamados.'];
  let lista = null;
  if (body && Array.isArray(body.data)) lista = body.data;
  else if (Array.isArray(body)) lista = body;
  if (!Array.isArray(lista)) return ['INDETERMINADO', 'Resposta inesperada da consulta de chamados.'];
  if (lista.some(t => t && t.contactId && String(t.contactId) !== cid)) return ['INDETERMINADO', 'A API não filtrou por contato.'];
  const abertos = lista.filter(t => t && (t.isOpen === true || t.isOpen === 'true' || t.isOpen === 1));
  if (!abertos.length) return ['SEM_CHAMADO', 'Nenhum chamado aberto.'];
  if (abertos.some(t => !Object.prototype.hasOwnProperty.call(t, 'userId'))) return ['INDETERMINADO', 'Chamado aberto sem a informação do atendente.'];
  const deOutros = abertos.filter(t => !MEUS_USER_IDS.includes(String(t.userId ?? '')));
  if (!deOutros.length) return ['CHAMADO_MEU', 'Chamado já está comigo.'];
  if (deOutros.some(t => t.userId)) return ['OCUPADO', 'Chamado com outro atendente.'];
  return ['FILA_SEM_ATENDENTE', 'Chamado na fila sem atendente.'];
}
const [situacao, motivo] = avaliar();
const fechar = situacao === 'FILA_SEM_ATENDENTE' || situacao === 'CHAMADO_MEU';
return { json: { ...orig, fecharChamado: fechar, chamadoReconferido: situacao, chamadoReconferidoMotivo: motivo } };

// ===== VARREDURA DE RESPOSTAS TARDIAS (v24) — 1/2: quem consultar no DigiSac =====
// Roda ao iniciar o n8n (computador ligado de manhã), às 07:30 (seg–sex) e pode ser rodada à mão.
// Alvos:
//  (A) ENCERRADO: pedidos encerrados "sem retorno" no ÚLTIMO dia com encerramento (segunda olha sexta),
//      tabela SEM_CONFIRMACAO_DIARIO, status SEM_RETORNO_* (ou RESPONDEU_DEPOIS, para atualizar o cartão).
//  (B) ABERTO: pedidos de dias anteriores que ficaram em AGUARDANDO / DATA_ENVIADA / AGUARDANDO_CHAMADO_LIVRE
//      porque o encerramento das 16:20 não rodou (computador desligado antes).
// Sai 1 item por contato do DigiSac (o próximo nó busca as mensagens desse contato).
const TZ = 'America/Sao_Paulo';
const hoje = $now.setZone(TZ).toFormat('yyyy-LL-dd');
const normPed = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };
const up = v => String(v ?? '').trim().toUpperCase();
const lerJson = s => { try { const o = JSON.parse(s || '{}'); return o && typeof o === 'object' ? o : {}; } catch (_) { return {}; } };
const inicioDoDia = dia => Date.parse(`${dia}T00:00:00-03:00`) || 0;
const diaDe = v => {
  if (v === undefined || v === null || v === '') return null;
  const t = new Date(v).getTime();
  if (isNaN(t)) return null;
  return new Date(t - 3 * 3600e3).toISOString().slice(0, 10);   // Brasília (UTC-3, sem horário de verão)
};
const todos = n => { try { return $(n).all().map(i => i.json).filter(x => x && !x.error); } catch (_) { return []; } };

const semConf = todos('Ler SEM_CONFIRMACAO (varredura tardia)').filter(r => String(r.pedidoLider ?? '').trim());
const linhas = todos('Ler AGUARDANDO_ENTREGA (varredura tardia)').filter(r => r.id !== undefined && String(r.pedidoLider ?? '').trim());
const historico = todos('Ler HISTORICO_PEDIDOS (varredura tardia)').filter(r => String(r.pedidoLider ?? '').trim());

const CONSIDERAR = s => /^SEM_RETORNO/.test(s) || s === 'RESPONDEU_DEPOIS';
const ABERTOS = ['AGUARDANDO', 'DATA_ENVIADA', 'AGUARDANDO_CHAMADO_LIVRE'];

// Linha do pedido: primeiro AGUARDANDO_ENTREGA; se já foi arquivada, a mais recente do HISTORICO_PEDIDOS
function linhaDoPedido(ped) {
  const k = normPed(ped);
  const ag = linhas.filter(r => normPed(r.pedidoLider) === k);
  if (ag.length) return ag.find(r => up(r.status) !== 'AGRUPADO') || ag[0];
  const hs = historico.filter(h => normPed(h.pedidoLider) === k)
    .sort((a, b) => String(b.arquivadoEm ?? '').localeCompare(String(a.arquivadoEm ?? '')));
  return hs.length ? { ...lerJson(hs[0].dados), _doHistorico: true } : null;
}
const enviadoTs = row => Date.parse(row?.enviadoEm || '') || 0;

const alvos = [];

// (A) encerrados sem retorno no último dia com encerramento
const dias = [...new Set(semConf.filter(r => CONSIDERAR(up(r.status))).map(r => String(r.dataRef ?? '').trim()).filter(d => d && d < hoje))].sort();
const ultimoDia = dias.length ? dias[dias.length - 1] : null;
if (ultimoDia) {
  for (const r of semConf) {
    if (String(r.dataRef ?? '').trim() !== ultimoDia || !CONSIDERAR(up(r.status))) continue;
    const contactId = String(r.contactId ?? '').trim();
    if (!contactId) continue;
    const corte = Date.parse(r.registradoEm || '') || 0;
    if (!corte) continue;
    const row = linhaDoPedido(r.pedidoLider);
    const env = enviadoTs(row);
    alvos.push({
      tipo: 'ENCERRADO', pedidoLider: String(r.pedidoLider), contactId, dataRef: ultimoDia,
      corte, desde: Math.min(inicioDoDia(ultimoDia), env || Infinity),
      etapa: up(r.status), encerradoEm: String(r.registradoEm), statusSemConf: up(r.status)
    });
  }
}

// (B) abertos de dias anteriores (o encerramento da tarde não rodou)
for (const r of linhas) {
  const dia = diaDe(r.createdAt);
  if (!dia || dia >= hoje) continue;
  const st = up(r.status);
  if (!ABERTOS.includes(st)) continue;
  const dp = lerJson(r.dadosPedido);
  const contactId = String(r.contactId ?? '').trim() || String(dp.contactId ?? '').trim();
  if (!contactId) continue;
  const env = enviadoTs(r);
  alvos.push({
    tipo: 'ABERTO', pedidoLider: String(r.pedidoLider), contactId, dataRef: dia, idLinha: r.id,
    corte: env || inicioDoDia(dia), desde: env || inicioDoDia(dia),
    etapa: 'NAO_ENCERRADO', statusAnterior: st, enviadoEm: String(r.enviadoEm ?? '')
  });
}

// 1 item por contato
const porContato = new Map();
for (const a of alvos) {
  if (!porContato.has(a.contactId)) porContato.set(a.contactId, { contactId: a.contactId, desde: a.desde, alvos: [] });
  const c = porContato.get(a.contactId);
  c.desde = Math.min(c.desde, a.desde);
  c.alvos.push(a);
}
return [...porContato.values()].map(c => ({ json: { ...c, desdeISO: new Date(c.desde).toISOString(), ultimoDia, hoje } }));

// ===== VARREDURA DE RESPOSTAS TARDIAS (v24) — 2/2: o que o cliente mandou =====
// Junta as mensagens buscadas no DigiSac (todas as páginas) com o que já está na MENSAGENS_CLIENTE e decide:
//  GRAVAR_MSG -> mensagem do cliente que o webhook não recebeu (servidor desligado): grava na MENSAGENS_CLIENTE
//  CARTAO     -> cliente respondeu: pedido vai para a tela ⏰ Respostas tardias (PENDENTE_RESPOSTA_TARDIA)
//  ENCERRAR   -> (só pedidos ABERTOS de dias anteriores) não respondeu: encerra como sem retorno
//                pelo mesmo caminho do encerramento das 16:20 (1 item só, com a lista de linhas)
// Se a consulta ao DigiSac falhar para um contato, nada é feito com ele (a próxima varredura tenta de novo).
const TZ = 'America/Sao_Paulo';
const normPed = v => { const a = String(v ?? '').match(/\d+/g); return a ? a[a.length - 1].replace(/^0+/, '') : ''; };
const up = v => String(v ?? '').trim().toUpperCase();
const lerJson = s => { try { const o = JSON.parse(s || '{}'); return o && typeof o === 'object' ? o : {}; } catch (_) { return {}; } };
const todos = n => { try { return $(n).all().map(i => i.json).filter(x => x && !x.error); } catch (_) { return []; } };
const MAX_RESPOSTAS = 20, MAX_CONTEXTO = 6;
const SEM_TEXTO = '[mensagem sem texto: áudio, imagem ou arquivo]';

const contatos = $('Selecionar contatos (varredura tardia)').all().map(i => i.json);
const linhas = todos('Ler AGUARDANDO_ENTREGA (varredura tardia)').filter(r => r.id !== undefined && String(r.pedidoLider ?? '').trim());
const historico = todos('Ler HISTORICO_PEDIDOS (varredura tardia)').filter(r => String(r.pedidoLider ?? '').trim());
const msgsTabela = todos('Ler MENSAGENS_CLIENTE (varredura tardia)');

// ---- respostas do DigiSac (cada página é um item; o contato vem no pairedItem ou na própria mensagem) ----
const paginas = $input.all();
const apiPorContato = new Map();   // contactId -> Map(id -> msg)
const falhou = new Set();
const cidsDoLote = contatos.map(c => String(c.contactId));
paginas.forEach((it, i) => {
  const j = it.json || {};
  const pi = it.pairedItem;
  const idx = Array.isArray(pi) ? pi[0]?.item : (typeof pi === 'object' && pi ? pi.item : undefined);
  const cidPar = idx !== undefined ? cidsDoLote[idx] : undefined;
  const body = j.body !== undefined ? j.body : j;
  const lista = Array.isArray(body?.data) ? body.data : (Array.isArray(body) ? body : null);
  if (j.error || !lista) { if (cidPar) falhou.add(cidPar); return; }
  for (const m of lista) {
    if (!m || !m.id) continue;
    const cid = String(m.contactId ?? cidPar ?? '');
    if (!cid) continue;
    if (cidPar && cid !== cidPar) { falhou.add(cidPar); continue; }   // API não filtrou por contato: não confia
    if (!apiPorContato.has(cid)) apiPorContato.set(cid, new Map());
    apiPorContato.get(cid).set(String(m.id), m);
  }
  // página vazia também conta como consulta feita
  if (cidPar && !apiPorContato.has(cidPar)) apiPorContato.set(cidPar, new Map());
});

const tsMsg = m => Date.parse(m.timestamp || m.createdAt || '') || Number(m.timestamp) || 0;
const textoMsg = m => String(m.data?.text || m.text || '').trim() || SEM_TEXTO;
const ehInterna = m => ['ticket', 'comment'].includes(String(m.type ?? '').toLowerCase());
const tsTab = m => Number(m.ts) || Date.parse(m.recebidoEm) || 0;

// ---- linha do pedido (AGUARDANDO_ENTREGA ou HISTORICO) e pedido principal (mensagem única) ----
function linhaDoPedido(ped) {
  const k = normPed(ped);
  const ag = linhas.filter(r => normPed(r.pedidoLider) === k);
  if (ag.length) return ag.find(r => up(r.status) !== 'AGRUPADO') || ag[0];
  const hs = historico.filter(h => normPed(h.pedidoLider) === k)
    .sort((a, b) => String(b.arquivadoEm ?? '').localeCompare(String(a.arquivadoEm ?? '')));
  return hs.length ? { ...lerJson(hs[0].dados), _doHistorico: true } : null;
}
function principal(row) {
  if (!row || up(row.status) !== 'AGRUPADO') return row;
  const ag = lerJson(row.dadosPedido).agrupadoEm;
  const p = ag ? linhaDoPedido(ag) : null;
  return p && up(p.status) !== 'AGRUPADO' ? p : row;
}
// Só vira cartão se o pedido ainda está parado (não mexe em quem já está em andamento hoje)
const PODE_CARTAO = {
  ENCERRADO: ['SEM_RETORNO_CLIENTE', 'PENDENTE_REVISAO', 'PENDENTE_RESPOSTA_TARDIA'],
  ABERTO: ['AGUARDANDO', 'DATA_ENVIADA', 'AGUARDANDO_CHAMADO_LIVRE', 'PENDENTE_RESPOSTA_TARDIA']
};

const saida = [];
const encerrar = [];
const cartoes = new Set();
const log = { contatos: contatos.length, falhas: [], cartoes: [], gravadas: 0, encerrar: [], ignorados: [] };

for (const c of contatos) {
  const cid = String(c.contactId);
  if (falhou.has(cid) || !apiPorContato.has(cid)) { log.falhas.push(cid); continue; }

  const doTabela = msgsTabela.filter(m => String(m.contactId ?? '').trim() === cid);
  const conhecidas = new Set(doTabela.map(m => String(m.messageId ?? '')));
  const api = [...apiPorContato.get(cid).values()].filter(m => !ehInterna(m) && tsMsg(m))
    .map(m => ({ id: String(m.id), ts: tsMsg(m), cliente: m.isFromMe !== true, texto: textoMsg(m), nova: !conhecidas.has(String(m.id)) }));

  // 1) mensagens do cliente que o n8n nunca recebeu (dentro da janela da varredura)
  const novas = api.filter(m => m.cliente && m.nova && m.ts >= c.desde);
  for (const m of novas) {
    saida.push({ json: { acao: 'GRAVAR_MSG', contactId: cid, messageId: m.id, papel: 'CLIENTE', texto: m.texto, ts: m.ts, recebidoEm: new Date(m.ts).toISOString() } });
    log.gravadas++;
  }
  const idsNovas = new Set(novas.map(m => m.id));

  for (const a of c.alvos) {
    // Respostas do cliente: depois do corte (encerramento ou envio) OU que o n8n nunca recebeu depois do envio
    const cliTab = doTabela.filter(m => up(m.papel) === 'CLIENTE' && tsTab(m) > a.corte)
      .map(m => ({ id: String(m.messageId ?? ''), ts: tsTab(m), cliente: true, texto: String(m.texto ?? '').trim() || SEM_TEXTO }));
    const cliApi = api.filter(m => m.cliente && (m.ts > a.corte || (idsNovas.has(m.id) && m.ts >= a.desde)));
    const mapa = new Map();
    for (const m of [...cliTab, ...cliApi]) if (!mapa.has(m.id)) mapa.set(m.id, m);
    const respostasCli = [...mapa.values()].sort((x, y) => x.ts - y.ts);

    if (!respostasCli.length) {
      if (a.tipo === 'ABERTO') { encerrar.push({ id: a.idLinha, pedidoLider: a.pedidoLider, dataRef: a.dataRef }); log.encerrar.push(a.pedidoLider); }
      continue;
    }

    // ---- cartão na tela Respostas tardias ----
    const primeiraResp = respostasCli[0].ts;
    const row = principal(linhaDoPedido(a.pedidoLider));
    if (!row) { log.ignorados.push(`${a.pedidoLider}: linha do pedido não encontrada`); continue; }
    const pedidoCartao = String(row.pedidoLider);
    if (cartoes.has(normPed(pedidoCartao))) continue;   // mensagem única: 1 cartão por pedido principal
    const st = up(row.status);
    if (!PODE_CARTAO[a.tipo].includes(st)) { log.ignorados.push(`${pedidoCartao}: pedido já está em ${st}`); continue; }
    cartoes.add(normPed(pedidoCartao));

    // Falas da Líder (atendentes no DigiSac) depois da 1ª resposta: ajudam a ver se alguém já respondeu
    const lider = api.filter(m => !m.cliente && m.ts >= primeiraResp);
    const fala = m => ({ papel: m.cliente ? 'CLIENTE' : 'LIDER', texto: String(m.texto).slice(0, 2000), ts: m.ts });
    const respostas = [...respostasCli, ...lider].sort((x, y) => x.ts - y.ts).slice(-MAX_RESPOSTAS).map(fala);
    const contexto = doTabela.filter(m => tsTab(m) < primeiraResp && up(m.papel) !== 'RECOMECO')
      .sort((x, y) => tsTab(x) - tsTab(y)).slice(-MAX_CONTEXTO)
      .map(m => ({ papel: up(m.papel) === 'CLIENTE' ? 'CLIENTE' : 'LIDER', texto: String(m.texto ?? '').trim().slice(0, 2000), ts: tsTab(m) }));

    const dp = lerJson(row.dadosPedido);
    const respostaTardia = {
      pedidoLiderRegistro: a.tipo === 'ENCERRADO' ? a.pedidoLider : null,
      dataRef: a.dataRef,
      encerradoEm: a.tipo === 'ENCERRADO' ? a.encerradoEm : '',
      enviadoEm: a.enviadoEm || String(row.enviadoEm ?? ''),
      etapa: a.etapa,
      statusAnterior: st,
      contactId: cid,
      respostas, contexto,
      origem: 'VARREDURA',
      detectadoEm: new Date().toISOString()
    };
    const dadosPedido = JSON.stringify({ ...dp, pedidoLider: dp.pedidoLider ?? pedidoCartao, respostaTardia });
    saida.push({ json: {
      acao: 'CARTAO',
      pedidoLider: pedidoCartao,
      status: 'PENDENTE_RESPOSTA_TARDIA',
      dadosPedido,
      cliente: String(row.cliente ?? dp.clienteLider ?? dp.Cliente ?? ''),
      responsavel: String(row.responsavel ?? dp.responsavel ?? ''),
      contactId: String(row.contactId ?? '').trim() || cid,
      mensagem: String(row.mensagem ?? dp.mensagem ?? ''),
      tipoMensagem: String(row.tipoMensagem ?? dp.tipoMensagem ?? ''),
      // SEM_CONFIRMACAO_DIARIO: marcar RESPONDEU_DEPOIS (não conta como dia sem retorno)
      marcarSemConf: a.tipo === 'ENCERRADO' && a.statusSemConf !== 'RESPONDEU_DEPOIS',
      semConfPedido: a.pedidoLider, semConfDataRef: a.dataRef,
      recriado: !!row._doHistorico
    } });
    log.cartoes.push(`${pedidoCartao} (${respostasCli.length} msg)`);
  }
}

if (encerrar.length) {
  saida.push({ json: { acao: 'ENCERRAR', linhas: encerrar, ids: encerrar.map(e => String(e.id)) } });
}
saida.push({ json: { acao: 'RESUMO', ...log, em: $now.setZone(TZ).toFormat('dd/LL/yyyy HH:mm') } });
return saida;

// v26 — a IA marcou um assunto fora das regras: antes de chamar o consultor, procura a resposta na base de conhecimento.
const linha = $('Preparar contexto IA').first().json;
const out = $('Basic LLM Chain').first().json.output || {};
const base = $input.all().map(i => i.json).filter(r => r && r.id !== undefined && r.pergunta && r.resposta);
const lista = base.slice(-200); // limita o tamanho do prompt
const baseTexto = lista.map(r => `[ID ${r.id}]\nPergunta: ${r.pergunta}\nResposta: ${r.resposta}`).join('\n\n');
return [{ json: {
  textoCliente: String(linha.textoCliente || ''),
  mensagem: String(linha.mensagem || ''),
  assuntoFora: String(out.assuntoFora || out.resumo || '').trim(),
  baseVazia: lista.length === 0,
  baseTexto
} }];

parameters.text:
=Você é o assistente de atendimento da Líder Interiores. O cliente respondeu à mensagem sobre a entrega do pedido e trouxe um assunto que as regras automáticas não cobrem. Verifique se alguma entrada da base de conhecimento responde a esse assunto.

Mensagem do cliente:
{{ $json.textoCliente }}

Assunto fora das regras (resumo):
{{ $json.assuntoFora }}

Última mensagem enviada pela empresa (contexto):
{{ String($json.mensagem || '').slice(0, 600) }}

Base de conhecimento:
{{ $json.baseTexto }}

Regras:
- Use uma entrada somente se ela responder de fato ao assunto (mesmo assunto e mesma intenção). Perguntas parecidas sobre coisas diferentes NÃO servem.
- Reclamação, recusa de uma regra, itens faltando ou errados, pedido que o cliente diz já estar pronto: só use a base se houver uma entrada exatamente sobre essa situação.
- Se nenhuma servir com segurança, encontrou=false. Na dúvida, encontrou=false.
- Se encontrar, escreva "resposta" como mensagem curta, cordial e clara, em português do Brasil, no tom de WhatsApp, usando SOMENTE as informações da entrada. Responda só a esse assunto. Não confirme, não altere e não prometa datas de entrega. Não invente prazos, valores ou promessas. Não mencione "base", "IA" ou "consultor".
- Responda APENAS com JSON, sem markdown: {"encontrou": true, "id": 12, "resposta": "texto"} ou {"encontrou": false, "id": null, "resposta": ""}

parameters.jsCode:
// v26 — lê a resposta da IA que consultou a base (assunto fora das regras na resposta à data).
const j = $('Montar consulta à base (1ª resposta)').first().json;
const bruto = String($input.first().json.text ?? $input.first().json.output ?? '').trim();
let r = {};
try { r = JSON.parse(bruto.replace(/```json|```/g, '').trim()); } catch (_) {}
const base = $('Ler base de conhecimento (1ª resposta)').all().map(i => i.json).filter(x => x && x.id !== undefined);
const entrada = base.find(x => String(x.id) === String(r.id));
const resp = String(r.resposta ?? '').trim();
const usarBase = r.encontrou === true && !!entrada && !!resp;
return [{ json: { assuntoFora: j.assuntoFora, usarBase, kbId: usarBase ? entrada.id : null, kbUsos: usarBase ? Number(entrada.usos || 0) : 0, respostaBase: usarBase ? resp : '' } }];

// v26 — REGISTRO ÚNICO: marca no pedido (dadosPedido.registroContato) que o contato foi gravado
// na planilha e na intranet. Depois disso nenhuma resposta do cliente grava de novo, nem o consultor.
const n = $('Normalizar Categoria').first().json;
const c = $input.first().json;
let dp = {};
try { dp = JSON.parse(n.dadosPedido || '{}'); } catch (_) { dp = {}; }
if (dp.registroContato) return [];
const dataEntrega = (n.categoria === 'PEDE_ADIAR' && n.adiamentoValido === true && n.dataSolicitada)
  ? n.dataSolicitada : (n.dataPrevistaOriginal || '');
dp.registroContato = {
  em: new Date().toISOString(),
  origem: 'IA',
  categoria: n.categoria,
  resultado: c.sheetH,
  dataEntrega,
  pedidos: Array.isArray(n.pedidosGrupo) && n.pedidosGrupo.length ? n.pedidosGrupo.map(String) : [String(n.pedidoLider)]
};
return [{ json: { id: n.id, dadosPedido: JSON.stringify(dp) } }];
